window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0158", [{"word":"sociologist","ipa_uk":"/ˌsəʊsiˈɒlədʒɪst/","ipa_us":"/ˌsoʊsiˈɑːlədʒɪst/","definition_zh":"社会学家；以观察、访谈与统计数据研究社会群体、制度与社会关系的研究者","definition_en":"a person trained to study the structure, groups and behaviour of human societies, especially through observation and data","core_image":"一个人带着记录本坐在工厂食堂的长桌边，白天跟班、夜里抄录谈话，把零散的日常写成一份关于群体的报告","scene":"The sociologist spent three years observing how factory families in the town organized their daily lives.","sceneCN":"此处指「研究人群如何共同生活并以调查与观察写成报告的研究者」（第 1 个义项：以观察和数据描述社会群体的专业人员）；句意为这位研究者用三年时间观察镇上工厂家庭如何安排日常生活。可辨识物件：工厂宿舍、记录本、食堂长桌、夜班路灯。","pos":[{"tag":"n.","zh":"社会学家；社会学研究者"},{"tag":"n.","zh":"某一领域的社会学专家（如教育社会学、医学社会学）"}],"collocations":[{"phrase":"urban sociologist","zh":"城市社会学家"},{"phrase":"medical sociologist","zh":"医学社会学家"},{"phrase":"industrial sociologist","zh":"工业社会学家"},{"phrase":"trained sociologist","zh":"受过专业训练的社会学家"},{"phrase":"sociologist of education","zh":"教育社会学家"},{"phrase":"sociologist studying migration","zh":"研究移民问题的社会学家"}],"forms":[{"label":"单数","form":"sociologist"},{"label":"复数","form":"sociologists"},{"label":"名词（学科）","form":"sociology"},{"label":"形容词（社会学的）","form":"sociological"},{"label":"副词（从社会学角度）","form":"sociologically"}],"derivatives":[{"word":"sociology","pos":"n.","zh":"社会学"},{"word":"sociological","pos":"adj.","zh":"社会学的；与社会学有关的"},{"word":"sociologically","pos":"adv.","zh":"从社会学角度"},{"word":"society","pos":"n.","zh":"社会"},{"word":"social","pos":"adj.","zh":"社会的；社交的"}],"senses":[{"no":"01","title":"A researcher who studies how people live together","titleCN":"研究人群如何共同生活的研究者","definition":"a person trained to study the structure, groups and behaviour of human societies, especially through observation and data","definitionCN":"受过训练、以观察和数据研究人类社会结构、群体与行为的人","example":"The sociologist spent three years observing how factory families in the town organized their daily lives.","exampleCN":"这位社会学家用三年时间观察镇上工厂家庭如何安排日常生活。","why":"The word joins Latin socius 'companion, ally' with Greek -logistēs 'one who studies', so the oldest sense is the person who gives an account of how people live together.","whyCN":"这个词把拉丁 socius「同伴、盟友」与希腊 -logistēs「研究的人」结合起来，最早的意思就是「对人群如何共同生活作出记述的人」。"},{"no":"02","title":"An analyst of institutions","titleCN":"把机构当作研究对象的分析者","definition":"a researcher who examines schools, courts, firms or families as organized institutions rather than as isolated individuals","definitionCN":"把学校、法院、公司或家庭当作有组织的机构来考察，而非只看孤立个人的研究者","example":"A sociologist of education mapped which pupils were routed into which school tracks.","exampleCN":"一位教育社会学家描绘出哪些学生被分流到哪一类学校轨道。","why":"Once the field turned to institutions, the same title named the researcher who treats an organization itself as the object of study.","whyCN":"当这门学科转向制度研究后，同一个称谓也指把组织本身当作研究对象的学者。"},{"no":"03","title":"A field observer of everyday life","titleCN":"日常生活的田野观察者","definition":"a researcher who lives among a group and records ordinary routines, talk and gestures in detail","definitionCN":"住进某个群体之中，细致记录日常作息、谈话与举动的研究者","example":"The sociologist shared meals with the night-shift workers to record how they spoke about overtime.","exampleCN":"这位社会学家与夜班工人一起吃饭，记录他们怎样谈论加班。","why":"Observation is the field's oldest method, so the title also marks the person who gathers evidence face to face.","whyCN":"观察是这门学科最古老的方法，因此这个称谓也指面对面收集证据的人。"},{"no":"04","title":"A writer of survey reports","titleCN":"调查报告的撰写者","definition":"a person who turns interviews, censuses and statistics into published accounts of a group","definitionCN":"把访谈、普查与统计数据整理成关于某个群体的公开报告的人","example":"The sociologist published a report showing that the housing queue followed postal codes.","exampleCN":"这位社会学家发表报告，指出住房排队顺序与邮政编码相关。","why":"The Greek root logos also means 'account', so the title covers the person who writes the account, not only the one who collects it.","whyCN":"希腊词根 logos 也有「记述」之意，因此这个称谓既指收集材料的人，也指把材料写成报告的人。"},{"no":"05","title":"A critic of social arrangements","titleCN":"社会安排的批评者","definition":"a researcher whose findings are used to question how a society distributes work, housing or opportunity","definitionCN":"其研究结果被用来质疑社会如何分配工作、住房与机会的研究者","example":"The sociologist argued that the factory's shift system quietly pushed women out of skilled posts.","exampleCN":"这位社会学家指出，工厂的轮班制度在无形中把女性排挤出技术岗位。","why":"Because the field studies inequality, its practitioners often write with a reforming purpose, and the title carries that connotation.","whyCN":"由于这门学科研究不平等，从业者常带着改良社会的目的写作，这个称谓也随之带上这层含义。"},{"no":"06","title":"A specialist in one institution","titleCN":"某一制度领域的专家","definition":"a researcher whose work concentrates on a single field such as medicine, religion, law or the family","definitionCN":"研究集中在一个领域，如医学、宗教、法律或家庭的研究者","example":"As a medical sociologist, she studied how patients were told about their diagnoses.","exampleCN":"作为医学社会学家，她研究医生如何把诊断结果告知病人。","why":"As the discipline grew, titles multiplied by field, and the general word took on the narrower reading of a specialist.","whyCN":"随着学科扩张，按领域划分的称谓越来越多，这个通称也就多了一层「某领域专家」的窄义。"},{"no":"07","title":"A policy adviser","titleCN":"政策顾问","definition":"a researcher who translates findings about groups into advice for officials or planners","definitionCN":"把关于群体的研究结论转化为给官员或规划者的建议的研究者","example":"The sociologist advised the city on how to resettle the riverside households.","exampleCN":"这位社会学家就如何安置江边住户向市政府提出建议。","why":"Governments and firms came to hire people with this training, so the title also names the adviser who applies it.","whyCN":"政府与公司开始聘用受过这种训练的人，因此这个称谓也指把研究用于实务的顾问。"},{"no":"08","title":"A teacher of the discipline","titleCN":"社会学教师","definition":"a person who teaches sociology and trains new researchers in its methods","definitionCN":"教授社会学并训练新研究者掌握其方法的人","example":"The sociologist taught a first-year course on how to read a census table.","exampleCN":"这位社会学家讲授一年级课程，教学生如何读懂普查表格。","why":"Teaching is one of the profession's standard roles, so the title covers the classroom as well as the field.","whyCN":"教学是从业者的标准角色之一，因此这个称谓既指田野里的研究者，也指课堂上的教师。"}],"etymology":{"intro":{"en":"Sociologist joins Latin socius 'companion, ally' with the Greek element -logistēs 'one who studies or accounts for something'. The combination is a modern learned coinage, not an ancient word. Dates are approximate.","cn":"sociologist 把拉丁 socius「同伴、盟友」与希腊成分 -logistēs「研究或记述某事物的人」结合而成。这是一个近代学术合成词，并非古代既有词。年代均为约数。"},"items":[{"era":"LATIN SOCIUS","en":"Socius meant 'companion, ally, associate'. Its deeper origin is not established; a link to Latin sequi 'to follow' is sometimes proposed as a hypothesis rather than a demonstrated derivation.","cn":"socius 意为「同伴、盟友、合伙人」。其更深来源未得到证明；有人提出它与拉丁 sequi「跟随」有关，但那只是假说，并非已证实的派生。"},{"era":"LATIN SOCIETAS","en":"From socius Latin formed societas 'association, community, partnership', the source of English society and of the base behind social.","cn":"拉丁语由 socius 构成 societas「联合、共同体、合伙关系」，它是英语 society 的来源，也是 social 一词的基础。"},{"era":"GREEK LOGOS","en":"Greek logos meant 'word, account, reason'. The combining form -logia named a field of study or discourse, and -logistēs named the person who works in it.","cn":"希腊 logos 意为「言词、记述、理性」。组合成分 -logia 指某个研究或论述领域，-logistēs 则指从事该领域的人。"},{"era":"MODERN COINAGE","en":"The noun sociology was coined in the nineteenth century from Latin socius and Greek -logia; sociologist was then formed by replacing the ending with -logistēs. The word is a deliberate Latin-Greek hybrid.","cn":"名词 sociology 于十九世纪由拉丁 socius 与希腊 -logia 合成；sociologist 随后把词尾换成 -logistēs 而成。这个词是有意拼合的拉丁—希腊混合词。"},{"era":"PROFESSIONAL SENSE","en":"In the twentieth century the title settled on the professional researcher, distinguishing the person from the subject matter and from the amateur observer.","cn":"到二十世纪，这个称谓固定指职业研究者，把「人」与「学科」以及业余观察者区分开来。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin and first date): the pre-Latin origin of socius is unsettled, and the earliest English use of the title is not precisely dated, so any older form offered for socius is a reconstruction.","cn":"来源不确定（更深词源与首见年代）：socius 在拉丁语之前的来源无定论，这个称谓在英语中最早出现的年代也缺乏精确记录，凡为其给出的更早形态均属重构形式。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin companion root or the same Greek study ending; group two holds researchers who study neighbouring subjects.","cn":"第一组是同出拉丁「同伴」词根或同带希腊「研究」词尾的词；第二组是研究相邻学科的研究者。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sociology","ipa":"/ˌsəʊsiˈɒlədʒi/","tag":"the subject, not the person","definition":"The name of the discipline; sociologist is the practitioner who works in it.","definitionCN":"学科名称；sociologist 则是在其中工作的从业者。"},{"word":"social","ipa":"/ˈsəʊʃəl/","tag":"the adjective","definition":"Means of society or of interaction; it describes a quality, not a profession.","definitionCN":"意为「社会的」或「交往的」，描述性质而非职业。"},{"word":"sociable","ipa":"/ˈsəʊsiəbl/","tag":"easy to talk to","definition":"Built on Latin sociare 'to join' plus -able: a person who readily joins others, with no academic sense.","definitionCN":"由拉丁 sociare「结交」加 -able 构成：指乐于与人相处的人，不含学术义。"},{"word":"socialist","ipa":"/ˈsəʊʃəlɪst/","tag":"a political label","definition":"A supporter of a political and economic order, formed with -ist from social; it is not a researcher title.","definitionCN":"指某种政治经济秩序的支持者，由 social 加 -ist 构成，并非研究者称谓。"}]},{"heading":"NEAR MEANING","entries":[{"word":"anthropologist","ipa":"/ˌænθrəˈpɒlədʒɪst/","tag":"culture and fieldwork","definition":"Studies human cultures, often through long fieldwork; sociologist usually works on modern industrial societies and institutions.","definitionCN":"研究人类文化，常做长期田野调查；社会学家多研究现代工业社会与制度。"},{"word":"demographer","ipa":"/dɪˈmɒɡrəfə/","tag":"counts populations","definition":"Measures births, deaths and migration; a sociologist may use such figures but studies wider social relations.","definitionCN":"测量出生、死亡与迁移；社会学家会使用这些数据，但研究更广的社会关系。"},{"word":"ethnographer","ipa":"/eθˈnɒɡrəfə/","tag":"writes the description","definition":"Produces detailed descriptions of a group's life; the role overlaps with field observation but is not tied to one discipline.","definitionCN":"对某一群体的生活作细致描述；这一角色与田野观察重叠，但不专属某一学科。"},{"word":"social scientist","ipa":"/ˈsəʊʃəl ˈsaɪəntɪst/","tag":"the umbrella term","definition":"Any researcher in sociology, economics, political science or anthropology; sociologist names one branch.","definitionCN":"社会学、经济学、政治学或人类学等领域的统称；社会学家只指其中一支。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin socius 'companion' plus Greek -logistēs 'one who studies': the person who gives an account of people living together.","cn":"拉丁 socius「同伴」加希腊 -logistēs「研究的人」：对人群共同生活作出记述的人。"},{"en":"The family runs sociology, sociological, sociologically, society and social.","cn":"同族词包括 sociology、sociological、sociologically、society 与 social。"},{"en":"Fixed phrases mark the specialist: urban sociologist, medical sociologist, sociologist of education.","cn":"固定搭配标出专业方向：城市社会学家、医学社会学家、教育社会学家。"},{"en":"The title is a Latin-Greek hybrid, which is why the ending is -logist and not a native English suffix.","cn":"这个称谓是拉丁—希腊混合词，所以词尾是 -logist 而不是本族英语后缀。"},{"en":"A sociologist usually pairs observation with numbers: field notes on one side, census tables on the other.","cn":"社会学家通常把观察与数字并用：一边是田野笔记，一边是普查表格。"}],"abstract":[{"en":"Picture a person sitting at the edge of a long table, quietly writing down how everyone passes the salt.","cn":"想象一个人坐在长桌一角，安静记下每个人怎样递盐。"},{"en":"Picture a map of a town drawn not with roads but with who meets whom each morning.","cn":"想象一张城镇地图，不画道路，只画每天早晨谁与谁相遇。"},{"en":"Picture a census table turning into a story about which families wait longest for a flat.","cn":"想象一张普查表格变成故事，讲哪些家庭等房子等得最久。"}]},"examples":[{"en":"The sociologist showed that the factory's promotion rules favoured day-shift workers.","cn":"这位社会学家指出，工厂的晋升规则偏向白班工人。"},{"en":"A sociologist of religion compared how the two towns organized their annual festivals.","cn":"一位宗教社会学家比较了两个城镇如何组织年度节庆。"},{"en":"The report by the sociologist was used when the city redrew the bus routes.","cn":"这位社会学家的报告被用于市政府重新规划公交线路。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「social（社会）+ logist（研究者）」——研究社会如何运转的人 → 社会学家","word":"sociologist"},"root":"sociologist 由拉丁 socius「同伴、盟友」加希腊 -logistēs「研究的人」构成，是十九世纪形成的拉丁—希腊混合学术词；socius 更深来源不确定，与 sequi「跟随」的联系仅为假说。英语 society、social 同出 socius 一支。","sensesIntro":{"en":"Eight senses follow one person through the discipline: the general student of living together, the analyst of institutions, the field observer, the writer of reports, the critic, the single-field specialist, the policy adviser and the teacher.","cn":"八个义项跟着同一个人走过这门学科：研究共同生活的一般学者、制度分析者、田野观察者、报告撰写者、批评者、单一领域专家、政策顾问与教师。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person seated at the edge of a group, notebook open, turning ordinary routines into an account.","cn":"核心意象：一个人坐在群体边缘，摊开记录本，把日常作息写成一份记述。"},"chain":["COMPANION ROOT","ACCOUNT OF LIFE","FIELD EVIDENCE","INSTITUTIONS","PUBLIC REPORT","PROFESSIONAL ROLE"],"branches":[{"senses":"01","en":"COMPANION ROOT: socius supplies the subject, people living together, and the account begins there.","cn":"同伴词根：socius 提供研究对象，即共同生活的人，记述由此开始。"},{"senses":"02","en":"INSTITUTIONS: the account turns from individuals to schools, courts and firms as organized wholes.","cn":"制度：记述对象从个人转向作为整体的学校、法院与公司。"},{"senses":"03 · 04","en":"EVIDENCE AND WRITING: watching face to face and writing the report are two halves of one method.","cn":"证据与写作：面对面观察与写成报告，是同一方法的两半。"},{"senses":"05 · 07","en":"PUBLIC USE: findings become criticism and advice once they leave the study.","cn":"公共用途：研究结论一旦离开书斋，就成为批评与建议。"},{"senses":"06 · 08","en":"NARROW ROLES: the same title covers a single-field specialist and a classroom teacher.","cn":"窄化角色：同一称谓既指单一领域专家，也指课堂教师。"}]},"affixes":{"intro":{"en":"The word is built from a Latin root and a Greek ending, and its derived forms keep the same division of labour.","cn":"这个词由一个拉丁词根与一个希腊词尾构成，其派生词也延续同样的分工。"},"latinIntro":{"en":"Latin socius and societas supply the social half; Greek logos and -logistēs supply the studying half.","cn":"拉丁 socius 与 societas 提供「社会」的一半；希腊 logos 与 -logistēs 提供「研究」的一半。"},"items":[{"word":"soci-","structure":"socius (Latin noun, 'companion, ally')","meaning":"companion; ally; associate","meaningCN":"同伴；盟友；合伙人","example":"The root supplies the group being studied.","exampleCN":"这个词根提供被研究的群体。"},{"word":"-logy","structure":"-logia (Greek combining form, from logos 'account, reason')","meaning":"study of; account of","meaningCN":"……学；对……的记述","example":"The ending names a field of study.","exampleCN":"这个词尾指一个研究领域。"},{"word":"-logist","structure":"-logistēs (Greek noun, 'one who studies')","meaning":"one who studies or accounts for","meaningCN":"研究或记述某事物的人","example":"The ending names the practitioner.","exampleCN":"这个词尾指从业者。"},{"word":"sociologist","structure":"soci- + -logist","meaning":"one who studies society","meaningCN":"研究社会的人","example":"The sociologist observed the night shift.","exampleCN":"这位社会学家观察夜班。"},{"word":"sociology","structure":"soci- + -logy","meaning":"the study of society","meaningCN":"社会学","example":"Sociology grew out of nineteenth-century reform debates.","exampleCN":"社会学脱胎于十九世纪的改良争论。"},{"word":"sociological","structure":"sociology + -ical (adjectival)","meaning":"relating to sociology","meaningCN":"社会学的","example":"The survey used a sociological frame.","exampleCN":"这项调查采用了社会学的框架。"},{"word":"sociologically","structure":"sociological + -ly (adverbial)","meaning":"from a sociological point of view","meaningCN":"从社会学角度","example":"The strike can be read sociologically.","exampleCN":"这场罢工可以从社会学角度解读。"},{"word":"societal","structure":"society + -al (adjectival)","meaning":"relating to society as a whole","meaningCN":"整个社会层面的","example":"The change had societal effects.","exampleCN":"这一变化产生了社会层面的影响。"},{"word":"sociable","structure":"sociare (Latin verb 'to join') + -able","meaning":"ready to join others","meaningCN":"乐于与人相处的","example":"She is sociable without being talkative.","exampleCN":"她乐于交往，却并不健谈。"}],"derivatives":[{"word":"sociology","structure":"soci- + -logy (field of study)","meaning":"the study of society","meaningCN":"社会学"},{"word":"sociological","structure":"sociology + -ical (relating to)","meaning":"relating to sociology","meaningCN":"社会学的"},{"word":"sociologically","structure":"sociological + -ly (in that manner)","meaning":"from a sociological standpoint","meaningCN":"从社会学角度"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally, associate","meaningCN":"同伴；盟友；合伙人"},{"word":"societas","structure":"societas, societatis (f., third declension)","meaning":"association, community, partnership","meaningCN":"联合；共同体；合伙关系"},{"word":"sociare","structure":"sociare, sociavi, sociatum (verb, first conjugation)","meaning":"to join, to associate","meaningCN":"使结合；使结伴"}]}},{"word":"society","ipa_uk":"/səˈsaɪəti/","ipa_us":"/səˈsaɪəti/","definition_zh":"社会；有组织的人群共同体；社团；交往；上流社交圈","definition_en":"an organized community of people living together under shared rules and institutions","core_image":"海边村落共同修堤、轮流守夜、合办学校，一张看不见的网把各家各户连成一个能自我维持的整体","scene":"The fishing villages formed a tightly knit society that shared both the dike work and the night watch.","sceneCN":"此处指「共同修堤、办学、轮流守夜而形成彼此依存的共同体」（第 1 个义项：有组织、能自我维持的人群共同体）；句意为这些渔村结成了既共修海堤又共守夜汛的紧密社会。可辨识物件：海堤、渔网、夜灯、村口告示板。","pos":[{"tag":"n.","zh":"社会；人群共同体（可数或不可数）"},{"tag":"n.","zh":"社团；协会（可数）"},{"tag":"n.","zh":"交往；陪伴（不可数，较旧式）"},{"tag":"n.","zh":"上流社会；社交界（常带定冠词）"}],"collocations":[{"phrase":"modern society","zh":"现代社会"},{"phrase":"human society","zh":"人类社会"},{"phrase":"high society","zh":"上流社会"},{"phrase":"member of society","zh":"社会成员"},{"phrase":"society at large","zh":"整个社会"},{"phrase":"friendly society","zh":"互助会"}],"forms":[{"label":"单数","form":"society"},{"label":"复数","form":"societies"},{"label":"形容词（社会的）","form":"social"},{"label":"形容词（社会层面的）","form":"societal"},{"label":"形容词（善于交往的）","form":"sociable"}],"derivatives":[{"word":"social","pos":"adj.","zh":"社会的；社交的"},{"word":"societal","pos":"adj.","zh":"整个社会层面的"},{"word":"sociable","pos":"adj.","zh":"善于交往的；合群的"},{"word":"socialism","pos":"n.","zh":"社会主义"},{"word":"sociologist","pos":"n.","zh":"社会学家"},{"word":"socialize","pos":"v.","zh":"交往；使社会化"}],"senses":[{"no":"01","title":"An organized community","titleCN":"有组织的人群共同体","definition":"a community of people living together under shared rules, institutions and expectations","definitionCN":"在共同规则、制度与期待下一起生活的人群共同体","example":"The fishing villages formed a tightly knit society that shared both the dike work and the night watch.","exampleCN":"这些渔村结成了既共修海堤又共守夜汛的紧密社会。","why":"The word comes from Latin societas 'association, partnership', from socius 'ally', so the base sense is people bound together by mutual obligations.","whyCN":"这个词来自拉丁 societas「联合、合伙」，源于 socius「盟友」，因此基础义就是靠相互义务联结起来的人群。"},{"no":"02","title":"The people of a nation","titleCN":"一个国家的人民整体","definition":"the whole body of citizens considered as one unit, especially in discussions of law, economy or culture","definitionCN":"把全体公民视为一个整体，尤用于法律、经济或文化的讨论","example":"Japanese society places great weight on group harmony in the workplace.","exampleCN":"日本社会非常看重职场中的群体和谐。","why":"Once the word was applied to states, it named the whole population rather than a single local community.","whyCN":"当这个词用于国家层面，它指全体人口，而不再只是某个地方共同体。"},{"no":"03","title":"A club or association","titleCN":"社团；协会","definition":"an organized group formed for a shared purpose, such as a learned society or a debating society","definitionCN":"为共同目的组织起来的团体，如学会或辩论社","example":"The historical society meets on the first Thursday of every month.","exampleCN":"历史学会每月第一个星期四聚会。","why":"Latin societas also meant a partnership, and English kept that smaller, voluntary reading alongside the larger one.","whyCN":"拉丁 societas 也有「合伙」义，英语在保留大义的同时，也保留了这种较小的自愿结社义。"},{"no":"04","title":"High society","titleCN":"上流社会；社交界","definition":"the wealthy and fashionable class, considered as a closed circle of social events and marriages","definitionCN":"由社交活动与联姻维系、自成圈子的富裕时髦阶层","example":"The wedding filled the newspapers because half of high society was invited.","exampleCN":"那场婚礼上了报纸，因为半个上流社会都受邀出席。","why":"The sense of 'company' narrowed in the eighteenth century to the company of the fashionable, and the phrase high society fixed that meaning.","whyCN":"「交往圈」的意思在十八世纪收窄为「时髦人士的圈子」，「上流社会」这一说法把该义固定下来。"},{"no":"05","title":"Companionship","titleCN":"交往；陪伴","definition":"the state of being with other people, or the pleasure of their company","definitionCN":"与他人相处的状态，或与人相伴的乐趣","example":"He sought the society of painters because their talk kept him working.","exampleCN":"他愿意与画家们来往，因为他们的谈话让他保持创作。","why":"This is the oldest personal reading: society as the company one keeps, not as an institution.","whyCN":"这是最古老的个人义：社会指人所结交的同伴，而非制度。"},{"no":"06","title":"A circle of people with a shared practice","titleCN":"同业圈子；同行群体","definition":"a group of people who share a profession, interest or way of life and recognize one another as members","definitionCN":"共享某种职业、兴趣或生活方式并彼此认同的群体","example":"Among translators, a small society of specialists keeps the old terminology alive.","exampleCN":"在译者中间，一个小型专家圈子让旧术语得以延续。","why":"From 'company' came the narrower sense of a company of people with one trade, which persists in phrases such as the society of artists.","whyCN":"由「同伴」引申出「同一行业的一群人」，这一窄义仍见于「艺术家圈子」一类说法。"},{"no":"07","title":"A community of organisms","titleCN":"生物群落","definition":"a group of plants or animals of different species living together in one area and interacting","definitionCN":"不同物种的动植物在同一区域共同生活并相互作用的群体","example":"A fallen log supports a society of beetles, fungi and moss.","exampleCN":"一根倒下的树干养活着由甲虫、真菌与苔藓构成的群落。","why":"Ecology borrowed the word because an assemblage of species behaves like a community with divisions of labour.","whyCN":"生态学借用这个词，因为多物种的聚集像有分工的共同体一样运作。"},{"no":"08","title":"A mutual aid association","titleCN":"互助会","definition":"an association that collects regular payments from members to support them in sickness or old age","definitionCN":"由会员定期缴费、在生病或年老时提供帮助的协会","example":"The miners' friendly society paid for funerals and sick leave before the state did.","exampleCN":"在国家提供保障之前，矿工的互助会支付丧葬费与病假补助。","why":"Working-class groups adopted the word for their own self-help bodies, giving it a practical welfare sense.","whyCN":"工人阶级团体用这个词称呼自己的自助组织，使它多了一层实务福利义。"}],"etymology":{"intro":{"en":"Society comes from Latin societas 'association, partnership', from socius 'companion, ally', through Old French. Its range runs from a whole nation to a club and to mere companionship. Dates are approximate.","cn":"society 经古法语来自拉丁 societas「联合、合伙」，其词根 socius 意为「同伴、盟友」。词义范围从整个国家，到社团，再到单纯的陪伴。年代均为约数。"},"items":[{"era":"LATIN SOCIUS","en":"Socius meant 'companion, ally, associate'. Its deeper origin is not established; a suggested link to sequi 'to follow' remains a hypothesis.","cn":"socius 意为「同伴、盟友、合伙人」。其更深来源未得到证明；有人提出它与 sequi「跟随」有关，仍属假说。"},{"era":"LATIN SOCIETAS","en":"Societas named an association, a partnership or a community, covering both a business partnership and a body of allies.","cn":"societas 指联合、合伙或共同体，既涵盖商业合伙，也涵盖盟友团体。"},{"era":"OLD FRENCH SOCIETE","en":"Old French societe carried the word into English in the sixteenth century, first naming a companionship or an association of people.","cn":"古法语 societe 在十六世纪把这个词带入英语，最初指同伴关系或人的联合体。"},{"era":"NATIONAL SENSE","en":"In the eighteenth and nineteenth centuries the word was extended to the whole population of a state, especially in political and economic writing.","cn":"在十八与十九世纪，这个词被扩展到指一个国家的全体人口，尤见于政治与经济论述。"},{"era":"ECOLOGY","en":"In the twentieth century ecology borrowed the term for an assemblage of species, and the older 'company' reading also survives in high society.","cn":"到二十世纪，生态学借用这个词指物种的聚集；而较旧的「交往圈」义仍保留在「上流社会」的说法里。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin and first date): the pre-Latin origin of socius is unsettled, and the earliest English citation of society is not precisely dated, so any earlier Indo-European form is a reconstruction.","cn":"来源不确定（更深词源与首见年代）：socius 在拉丁语之前的来源无定论，society 在英语中的最早书证也缺乏精确年代，凡给出的更早印欧形态均属重构形式。"}]},"similar":{"note":{"en":"Group one holds look-alikes that share the Latin root or a similar shape; group two holds words for a body of people that differ in size or in kind.","cn":"第一组是同出拉丁词根或外形相近的词；第二组是表示人群整体、但在规模或性质上不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"social","ipa":"/ˈsəʊʃəl/","tag":"the adjective","definition":"The adjective describing interaction or status; society is the body itself.","definitionCN":"描述交往或社会地位的形容词；society 指这个群体本身。"},{"word":"societal","ipa":"/səˈsaɪətəl/","tag":"whole-society adjective","definition":"A formal adjective meaning 'of society as a whole'; it is not a synonym for sociable.","definitionCN":"正式形容词，意为「整个社会层面的」，并非 sociable 的同义词。"},{"word":"sociable","ipa":"/ˈsəʊsiəbl/","tag":"friendly","definition":"Means fond of company; it describes a person's temperament, not a community.","definitionCN":"意为喜欢与人相处，描述人的性情，而非共同体。"},{"word":"association","ipa":"/əˌsəʊsiˈeɪʃən/","tag":"same root, formal body","definition":"From Latin associare, built on socius: an organized body or a connection, often more formal than society in the club sense.","definitionCN":"来自以 socius 为基础的拉丁 associare：指有组织的团体或联系，在社团义上通常比 society 更正式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"community","ipa":"/kəˈmjuːnəti/","tag":"local shared life","definition":"A group sharing a place or interest; it stresses face-to-face ties more than society does.","definitionCN":"共享地点或利益的群体；比 society 更强调面对面的联系。"},{"word":"nation","ipa":"/ˈneɪʃən/","tag":"political unit","definition":"A people organized as a state; society can name the same people without the political frame.","definitionCN":"以国家形式组织起来的人民；society 可以指同一群人，但不带政治框架。"},{"word":"public","ipa":"/ˈpʌblɪk/","tag":"the people as audience","definition":"The people considered as a whole in relation to officials or services; it lacks society's sense of lasting structure.","definitionCN":"相对于官员或公共服务而言的全体民众，缺少 society 那种持久结构义。"},{"word":"club","ipa":"/klʌb/","tag":"small voluntary group","definition":"A small body formed around one activity; society in this range is more formal and often older.","definitionCN":"围绕某项活动形成的小团体；society 在这一范围内更正式，通常历史更久。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin socius 'ally' is the root; association, social and sociable all come from the same stock.","cn":"拉丁 socius「盟友」是词根；association、social 与 sociable 都出自同一来源。"},{"en":"The family runs society, societies, social, societal, sociable, socialize and sociologist.","cn":"同族词包括 society、societies、social、societal、sociable、socialize 与 sociologist。"},{"en":"Fixed phrases mark the scale: human society, modern society, society at large, high society.","cn":"固定搭配标出规模：人类社会、现代社会、整个社会、上流社会。"},{"en":"A learned society is a club of specialists, which shows how far the word can shrink from a nation to a room.","cn":"学会是专家的社团，这说明这个词可以从一个国家缩小到一个房间。"},{"en":"Ecology uses the same word for a community of species, because it too has members and exchanges.","cn":"生态学用同一个词指物种群落，因为它同样有成员与交换。"}],"abstract":[{"en":"Picture a net thrown over many households, each knot tied to a neighbour.","cn":"想象一张网罩住许多家庭，每个结都系在邻居身上。"},{"en":"Picture a town where the rules are not written on a wall but repeated in every kitchen.","cn":"想象一座城镇，规则不写在墙上，却在每间厨房里被重复。"},{"en":"Picture a room where people keep meeting because each one needs something from another.","cn":"想象一个房间，人们不断相聚，因为每个人都从别人那里需要点什么。"}]},"examples":[{"en":"In this society, neighbours still lend tools and watch each other's children.","cn":"在这个社会里，邻居仍会借工具、互相照看孩子。"},{"en":"The medical society publishes a journal for surgeons in the region.","cn":"这个医学学会为本地区的外科医生出版一份期刊。"},{"en":"Ant colonies are often described as a society with clear divisions of labour.","cn":"蚁群常被描述为一个分工明确的社会。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「so（如此）+ ciety（城市）」——如此多的人聚成城市 → 社会","word":"society"},"root":"society 经古法语来自拉丁 societas「联合、合伙」，词根 socius「同伴、盟友」；socius 更深来源不确定，与 sequi「跟随」的联系仅为假说。英语 social、societal、sociable、association 均出同一词根。","sensesIntro":{"en":"Eight senses move outward from a local community to a nation, then inward to a club, a fashionable circle, mere company, a professional circle, a biological community and a mutual aid body.","cn":"八个义项从一个地方共同体向外扩到国家，再向内收为社团、时髦圈子、单纯陪伴、同业圈子、生物群落与互助会。"},"semanticMap":{"core":{"en":"CORE IMAGE: a net of obligations tied across many households, strong enough to hold when one knot slips.","cn":"核心意象：一张由义务结成的网罩住许多家庭，某个结松了也仍能撑住。"},"chain":["ALLY","PARTNERSHIP","ORGANIZED COMMUNITY","NATION","FORMAL BODY","SHARED LIFE"],"branches":[{"senses":"01","en":"ORGANIZED COMMUNITY: the base is a body of people bound by mutual obligations.","cn":"有组织的共同体：基础是靠相互义务联结的人群。"},{"senses":"02","en":"NATION: the same body seen at the scale of a whole state.","cn":"国家：同一群体放大到整个国家的尺度。"},{"senses":"03 · 08","en":"FORMAL BODY: a club and a mutual aid association are both voluntary bodies with rules.","cn":"正式团体：社团与互助会都是带规则的自愿团体。"},{"senses":"04 · 06","en":"CIRCLE: high society and a professional circle are closed groups that recognize their own members.","cn":"圈子：上流社会与同业圈子都是彼此认同的封闭群体。"},{"senses":"05 · 07","en":"SHARED LIFE: companionship and an ecological community both rest on regular exchange.","cn":"共同生活：陪伴与生物群落都建立在经常性的交换之上。"}]},"affixes":{"intro":{"en":"The English word is a Latin noun carried through French, and its derived adjectives split the work of describing a whole society and describing a friendly person.","cn":"这个英语词是经法语传来的拉丁名词，其派生形容词分别承担「描述整个社会」与「描述合群的人」两种任务。"},"latinIntro":{"en":"Latin socius and societas supply the body of people; the adjective endings then branch into social, societal and sociable.","cn":"拉丁 socius 与 societas 提供「人群」这一核心，形容词词尾再分出 social、societal 与 sociable 三条线。"},"items":[{"word":"soci-","structure":"socius (Latin noun, 'companion, ally')","meaning":"companion; ally","meaningCN":"同伴；盟友","example":"The root names the people who are bound together.","exampleCN":"这个词根指被联结起来的人。"},{"word":"-ety","structure":"-etas (Latin noun ending, through French -ete)","meaning":"state or body of","meaningCN":"……的状态或群体","example":"The ending turns the root into a noun of condition.","exampleCN":"这个词尾把词根变成表示状态的名词。"},{"word":"society","structure":"soci- + -ety","meaning":"a body of associated people","meaningCN":"联合起来的人群","example":"The society kept its own fire station.","exampleCN":"这个社会自设消防站。"},{"word":"social","structure":"socius + -alis (relating to)","meaning":"relating to association","meaningCN":"与社会或交往有关的","example":"Social rules vary between towns.","exampleCN":"社交规则因城镇而异。"},{"word":"societal","structure":"society + -al (relating to)","meaning":"relating to society as a whole","meaningCN":"整个社会层面的","example":"The reform had societal consequences.","exampleCN":"这项改革产生了社会层面的后果。"},{"word":"sociable","structure":"sociare (Latin verb 'to join') + -able","meaning":"able to join others easily","meaningCN":"容易与人相处的","example":"He is sociable at every meeting.","exampleCN":"他在每次聚会上都很好相处。"},{"word":"socialize","structure":"social + -ize (to make or become)","meaning":"to make social; to mix","meaningCN":"使社会化；交往","example":"Children socialize through play.","exampleCN":"儿童通过游戏学习交往。"},{"word":"socialization","structure":"socialize + -ation (process)","meaning":"the process of becoming social","meaningCN":"社会化的过程","example":"Socialization begins in the family.","exampleCN":"社会化从家庭开始。"},{"word":"sociologist","structure":"soci- + -logist (one who studies)","meaning":"a person who studies society","meaningCN":"研究社会的人","example":"The sociologist mapped the town.","exampleCN":"这位社会学家绘出了城镇的图景。"}],"derivatives":[{"word":"social","structure":"socius + -alis (relating to)","meaning":"relating to society or interaction","meaningCN":"社会的；社交的"},{"word":"societal","structure":"society + -al (relating to)","meaning":"relating to society as a whole","meaningCN":"整个社会层面的"},{"word":"sociable","structure":"sociare + -able (able to)","meaning":"fond of company","meaningCN":"合群的；善于交往的"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"societas","structure":"societas, societatis (f., third declension)","meaning":"association, partnership, community","meaningCN":"联合；合伙；共同体"},{"word":"sociare","structure":"sociare, sociavi, sociatum (verb, first conjugation)","meaning":"to join, to associate","meaningCN":"使结合；使结伴"}]}},{"word":"societal","ipa_uk":"/səˈsaɪətəl/","ipa_us":"/səˈsaɪətəl/","definition_zh":"社会的；整个社会层面的；涉及社会结构与集体规范的","definition_en":"relating to society as a whole, especially to its structures, norms and collective effects","core_image":"一条新地铁穿过老城区，房租、通勤与邻里关系一起变动，个人的搬迁汇成一张只有俯瞰才看得见的整体图","scene":"The new subway line created societal pressure on housing and on the old neighbourhoods near the station.","sceneCN":"此处指「影响整个社会层面、而非只落在个别人身上的压力」（第 1 个义项：属于社会整体而非个体的）；句意是新地铁线给车站周边的住房与老街坊带来了整体性的压力。可辨识物件：地铁入口、施工围挡、租房广告、居委会窗口。","pos":[{"tag":"adj.","zh":"社会的；整个社会层面的（正式、学术语域）"},{"tag":"adj.","zh":"涉及社会结构或集体规范的"}],"collocations":[{"phrase":"societal norms","zh":"社会规范"},{"phrase":"societal change","zh":"社会层面的变化"},{"phrase":"societal pressure","zh":"社会压力"},{"phrase":"societal values","zh":"社会价值观"},{"phrase":"societal impact","zh":"社会影响"},{"phrase":"societal expectations","zh":"社会期待"}],"forms":[{"label":"原级","form":"societal"},{"label":"副词（社会层面地）","form":"societally"},{"label":"名词（社会）","form":"society"},{"label":"形容词（社会的，日常）","form":"social"},{"label":"名词（社会化）","form":"socialization"}],"derivatives":[{"word":"society","pos":"n.","zh":"社会"},{"word":"societally","pos":"adv.","zh":"在社会层面上"},{"word":"social","pos":"adj.","zh":"社会的；社交的"},{"word":"socialization","pos":"n.","zh":"社会化"},{"word":"sociologist","pos":"n.","zh":"社会学家"}],"senses":[{"no":"01","title":"Relating to society as a whole","titleCN":"整个社会层面的","definition":"relating to society considered as one whole rather than to any single person in it","definitionCN":"把社会视为一个整体而非其中任何个人","example":"The new subway line created societal pressure on housing and on the old neighbourhoods near the station.","exampleCN":"新地铁线给车站周边的住房与老街坊带来了整体性的压力。","why":"The suffix -al turns the noun society into an adjective, and the whole-society reading is what distinguishes it from social.","whyCN":"词尾 -al 把名词 society 变成形容词，而「整体社会」这一读法正是它与 social 的区别。"},{"no":"02","title":"Relating to social structure","titleCN":"涉及社会结构的","definition":"concerning the way a society is divided into classes, roles and institutions","definitionCN":"涉及社会如何划分为阶层、角色与制度","example":"Societal divisions along income lines shaped who could buy into the new district.","exampleCN":"按收入划出的社会分层决定了谁买得起新城区。","why":"When writers needed to point at structure rather than at friendly interaction, they reached for this more formal adjective.","whyCN":"当作者要指结构而非友好交往时，就会用这个更正式的形容词。"},{"no":"03","title":"Relating to shared norms","titleCN":"涉及共同规范的","definition":"concerning the rules and expectations that a community holds in common","definitionCN":"涉及一个共同体共同持有的规则与期待","example":"Changing societal norms made it normal for fathers to take parental leave.","exampleCN":"社会规范的变化使父亲休育儿假成为常态。","why":"Norms belong to no single individual, so the adjective naturally describes what is held collectively.","whyCN":"规范不属于任何个人，因此这个形容词自然用来描述集体持有的东西。"},{"no":"04","title":"Relating to public consequences","titleCN":"涉及公共后果的","definition":"concerning effects that spread beyond one household to the public at large","definitionCN":"涉及超出单个家庭、扩散到公众的影响","example":"The factory closure had societal costs that no single owner had to pay.","exampleCN":"工厂关闭带来的社会代价，没有任何一个业主需要独自承担。","why":"The word is used to name costs and benefits that fall on everyone, which is why it often appears with pressure and cost.","whyCN":"这个词用来指落在所有人身上的代价与收益，因此常与「压力」「代价」一类词连用。"},{"no":"05","title":"Relating to group relations","titleCN":"涉及群体关系的","definition":"concerning relations between groups within a society, such as regions or generations","definitionCN":"涉及社会内部群体之间的关系，如地区之间或代际之间","example":"Societal tension between the coast and the inland towns shaped the election.","exampleCN":"沿海与内陆城镇之间的社会紧张影响了这次选举。","why":"Group relations are a whole-society topic, so the adjective covers what happens between groups as well as inside them.","whyCN":"群体关系属于整体社会议题，因此这个形容词既涵盖群体内部，也涵盖群体之间。"},{"no":"06","title":"Relating to collective cost","titleCN":"涉及集体负担的","definition":"concerning a burden that is shared by many households rather than carried by one","definitionCN":"涉及由许多家庭分摊而非由一家承担的负担","example":"Elder care became a societal burden once the birth rate fell.","exampleCN":"出生率下降后，养老照护成了整个社会的负担。","why":"A cost becomes societal when it is pooled, which is the same idea as the public-consequence sense seen from the budget side.","whyCN":"代价一旦被汇集分摊，就成了社会性的；这与「公共后果」义只是从预算角度看的同一件事。"},{"no":"07","title":"Relating to cultural patterns","titleCN":"涉及文化模式的","definition":"concerning the habits, rituals and values that a society transmits across generations","definitionCN":"涉及一个社会代代相传的习惯、仪式与价值","example":"Societal attitudes toward silence differ sharply between the two regions.","exampleCN":"两个地区对沉默的社会态度差别很大。","why":"Culture is carried by a whole society rather than by one speaker, so the adjective fits patterns that outlive individuals.","whyCN":"文化由整个社会承载，而非由某个说话者承载，因此这个形容词适合描述比个人活得久远的模式。"},{"no":"08","title":"Contrasted with the individual","titleCN":"与个人层面相对的","definition":"used to mark the level of analysis that stands opposite to personal or individual explanations","definitionCN":"用来标出与个人解释相对的分析层次","example":"The study moved from individual choices to societal causes without losing the thread.","exampleCN":"这项研究从个人选择转向社会成因，却没有失去线索。","why":"Much of social science works by contrast between individual and societal levels, and the adjective was coined to name the second term cleanly.","whyCN":"社会科学大量依靠「个人」与「社会」两个层次的对照，这个形容词正是为了干净地命名后一项而造出的。"}],"etymology":{"intro":{"en":"Societal is an English adjective formed from society with the Latin-derived suffix -al. It entered academic writing as a formal alternative to social. Dates are approximate.","cn":"societal 是由 society 加拉丁来源的词尾 -al 构成的英语形容词，作为 social 的正式替代形式进入学术写作。年代均为约数。"},"items":[{"era":"LATIN SOCIETAS","en":"The base noun comes from Latin societas 'association, community', itself from socius 'ally'.","cn":"基础名词来自拉丁 societas「联合、共同体」，其词根为 socius「盟友」。"},{"era":"LATIN -ALIS","en":"The suffix -alis formed adjectives of relation in Latin and reached English as -al, as in social and societal.","cn":"词尾 -alis 在拉丁语中构成表示关系的形容词，进入英语后作 -al，如 social 与 societal。"},{"era":"MODERN FORMATION","en":"Societal is a modern formation built directly on the English noun rather than inherited as a single Latin word.","cn":"societal 是直接由英语名词构成的现代形式，并非作为单一拉丁词继承而来。"},{"era":"ACADEMIC USE","en":"In the twentieth century the word spread in sociology and policy writing because it could mark the whole-society level without the everyday flavour of social.","cn":"到二十世纪，这个词在社会学与政策写作中传播开来，因为它能标出整体社会层次，又不带 social 的日常色彩。"},{"era":"STYLE NOTE","en":"Dictionaries treat societal as formal and often prefer social in ordinary speech; the two words overlap but are not freely interchangeable.","cn":"词典把 societal 标为正式用语，日常口语常更倾向 social；两者有重叠，却不能随意互换。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest printed use of societal is not precisely established, and estimates for it vary, so no exact year is claimed here.","cn":"来源不确定（首见年代）：societal 最早的印刷用例缺乏精确考证，各家估计不一，因此这里不给出确切年份。"}]},"similar":{"note":{"en":"Group one holds adjectives that look alike or share the root but point at different levels; group two holds words for what is shared by a group.","cn":"第一组是外形相近或同根、但指向不同层次的形容词；第二组是指由群体共享之物的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"social","ipa":"/ˈsəʊʃəl/","tag":"everyday adjective","definition":"The ordinary adjective for interaction, status or public life; it is broader and less formal than societal.","definitionCN":"描述交往、地位或公共生活的日常形容词；比 societal 更宽、更不正式。"},{"word":"sociable","ipa":"/ˈsəʊsiəbl/","tag":"personality","definition":"Describes a person who enjoys company; it never describes a whole society.","definitionCN":"描述喜欢与人相伴的人，不能描述整个社会。"},{"word":"societal","ipa":"/səˈsaɪətəl/","tag":"this word","definition":"The formal adjective for society as a whole, especially structures and collective effects.","definitionCN":"指整个社会、尤指结构与集体效应的正式形容词。"},{"word":"socialized","ipa":"/ˈsəʊʃəlaɪzd/","tag":"past participle","definition":"Describes someone trained into social norms, or something made public; it is a verb form, not a level label.","definitionCN":"描述受过社会规范训练的人或被公有化的事物；它是动词形式，不是层次标签。"}]},{"heading":"NEAR MEANING","entries":[{"word":"communal","ipa":"/kəˈmjuːnəl/","tag":"shared within a group","definition":"Stresses common use or common identity inside a smaller community; societal points at the whole-society level.","definitionCN":"强调较小共同体内部的共用或共同身份；societal 指向整个社会层次。"},{"word":"collective","ipa":"/kəˈlektɪv/","tag":"done by all","definition":"Means performed or held by a group as a unit; it can apply to a team as easily as to a nation.","definitionCN":"指由群体作为一个单位完成或持有，既可用于团队，也可用于国家。"},{"word":"public","ipa":"/ˈpʌblɪk/","tag":"state and citizens","definition":"Relates to the state, services or open access; societal relates to society's structure and norms.","definitionCN":"与国家、公共服务或公开性有关；societal 则与社会结构与规范有关。"},{"word":"structural","ipa":"/ˈstrʌktʃərəl/","tag":"about arrangement","definition":"Names the arrangement of parts, often economic or institutional; societal is wider and includes norms and culture.","definitionCN":"指各部分的排列，常偏经济或制度；societal 更宽，含规范与文化。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Society plus -al: the adjective simply means 'of society', with a formal, academic tone.","cn":"society 加 -al：这个形容词就是「社会的」，带正式学术语气。"},{"en":"Fixed phrases mark the level: societal norms, societal pressure, societal change, societal impact.","cn":"固定搭配标出层次：社会规范、社会压力、社会变化、社会影响。"},{"en":"The word is common in sociology and policy writing, where the whole-society level must be named precisely.","cn":"这个词常见于社会学与政策写作，因为那里需要精确命名整体社会层次。"},{"en":"It contrasts with individual: individual choices on one side, societal causes on the other.","cn":"它与「个人」相对：一边是个人选择，一边是社会成因。"},{"en":"The family runs society, social, socialization and sociologist, all from the same Latin stock.","cn":"同族词包括 society、social、socialization 与 sociologist，均出同一拉丁来源。"}],"abstract":[{"en":"Picture a city seen from a tower: the streets are individual lives, the pattern is the societal level.","cn":"想象从塔上俯瞰城市：街道是个人生活，图案才是社会层次。"},{"en":"Picture a pressure gauge attached not to one pipe but to the whole water system.","cn":"想象压力表不是接在一根管子上，而是接在整个供水系统上。"},{"en":"Picture a rule that nobody wrote down but every household follows at dinner.","cn":"想象一条没人写下、却在家家户户饭桌上被遵守的规则。"}]},"examples":[{"en":"Societal expectations still push young couples toward a house before a child.","cn":"社会期待仍推动年轻夫妇先买房再要孩子。"},{"en":"The report separated individual habits from societal causes.","cn":"这份报告把个人习惯与社会成因区分开来。"},{"en":"Rising rents became a societal issue rather than a private complaint.","cn":"租金上涨成了社会议题，而不只是私人抱怨。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「social（社会的）+ tal（整体）」——把整个社会当成一个整体来看 → 社会层面的","word":"societal"},"root":"societal 由英语名词 society 加拉丁来源词尾 -al 构成；society 经古法语来自拉丁 societas，词根 socius「盟友」。这是现代英语形容词，不是拉丁语固有单词；最早书证年代不确定。","sensesIntro":{"en":"Eight senses describe one shift of viewpoint: the same town is seen first as a whole, then as structure, norms, public cost, group tension, shared burden, culture and finally as the level opposed to the individual.","cn":"八个义项描述同一次视角转换：同一座城镇先被看作整体，再被看作结构、规范、公共代价、群体紧张、共同负担、文化，最后被看作与个人相对的层次。"},"semanticMap":{"core":{"en":"CORE IMAGE: a city seen from a tower, where individual streets add up to one visible pattern.","cn":"核心意象：从塔上俯瞰的城市，一条条街道汇成一张可见的图案。"},"chain":["SOCIETY","WHOLE LEVEL","STRUCTURE","NORMS","PUBLIC COST","LEVEL CONTRAST"],"branches":[{"senses":"01","en":"WHOLE LEVEL: the adjective starts by naming society as one unit.","cn":"整体层次：这个形容词首先把社会当作一个单位来命名。"},{"senses":"02","en":"STRUCTURE: divisions of class, role and institution are the skeleton of that unit.","cn":"结构：阶层、角色与制度的划分是这个单位的骨架。"},{"senses":"03 · 05","en":"NORMS AND TENSION: shared rules hold groups together and also set them against one another.","cn":"规范与紧张：共同规则既把群体维系在一起，也使群体彼此对立。"},{"senses":"04 · 06","en":"PUBLIC COST: effects and burdens that no single household can carry alone.","cn":"公共代价：没有任何单个家庭能独自承担的影响与负担。"},{"senses":"07 · 08","en":"CULTURE AND CONTRAST: transmitted patterns outlive individuals, which is why the level is set against the person.","cn":"文化与对照：代代相传的模式比个人活得久，因此这一层次被拿来与个人对照。"}]},"affixes":{"intro":{"en":"The adjective is an English noun plus a Latin-derived ending, and its parts are shared with the rest of the society family.","cn":"这个形容词是英语名词加拉丁来源词尾构成，其成分与社会词族其他成员共享。"},"latinIntro":{"en":"Latin societas and the suffix -alis are the two ingredients; English supplied the modern noun base.","cn":"拉丁 societas 与词尾 -alis 是两个原料，现代英语提供了名词基础。"},"items":[{"word":"soci-","structure":"socius (Latin noun, 'ally, companion')","meaning":"companion; ally","meaningCN":"同伴；盟友","example":"The root names the associated people.","exampleCN":"这个词根指联合起来的人。"},{"word":"-ety","structure":"-etas (Latin noun ending)","meaning":"state, body","meaningCN":"状态；群体","example":"The ending makes the noun society.","exampleCN":"这个词尾构成名词 society。"},{"word":"-al","structure":"-alis (Latin adjectival suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix makes the adjective.","exampleCN":"这个词尾构成形容词。"},{"word":"societal","structure":"society + -al","meaning":"of society as a whole","meaningCN":"整个社会层面的","example":"Societal change came slowly.","exampleCN":"社会层面的变化来得很慢。"},{"word":"societally","structure":"societal + -ly (adverbial)","meaning":"at the society level","meaningCN":"在社会层面上","example":"The problem is societally rooted.","exampleCN":"这个问题根在社会层面。"},{"word":"society","structure":"soci- + -ety","meaning":"an associated body of people","meaningCN":"联合起来的人群","example":"Society grew more urban.","exampleCN":"社会变得更加城市化。"},{"word":"social","structure":"socius + -alis","meaning":"of interaction or status","meaningCN":"交往或地位的","example":"Social ties weakened.","exampleCN":"社会联系变弱了。"},{"word":"socialization","structure":"social + -ization (process)","meaning":"the process of becoming social","meaningCN":"社会化过程","example":"Socialization starts early.","exampleCN":"社会化很早就开始。"},{"word":"sociologist","structure":"soci- + -logist (studier)","meaning":"one who studies society","meaningCN":"研究社会的人","example":"A sociologist ran the survey.","exampleCN":"一位社会学家主持了这项调查。"}],"derivatives":[{"word":"societally","structure":"societal + -ly (adverbial)","meaning":"at the level of society","meaningCN":"在社会层面上"},{"word":"society","structure":"soci- + -ety (noun of state)","meaning":"an associated body of people","meaningCN":"社会；社团"},{"word":"social","structure":"socius + -alis (relating to)","meaning":"of interaction or status","meaningCN":"社会的；社交的"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"societas","structure":"societas, societatis (f., third declension)","meaning":"association, community","meaningCN":"联合；共同体"},{"word":"societalis","structure":"societalis, -e (adjective, modern Latin)","meaning":"of society","meaningCN":"社会的"}]}},{"word":"socialization","ipa_uk":"/ˌsəʊʃəlaɪˈzeɪʃən/","ipa_us":"/ˌsoʊʃələˈzeɪʃən/","definition_zh":"社会化；使人学会群体规范与角色的过程；交往活动；公有化","definition_en":"the process by which a person learns the norms, roles and behaviour expected in a group or society","core_image":"孩子在餐桌上学让菜、在学校学排队、在球场学合作，零散的训练连成一条把他带进群体的长线","scene":"Table manners at home and turn-taking at school are early forms of socialization.","sceneCN":"此处指「人通过家庭与学校学会群体规范与角色的过程」（第 1 个义项：学会在社会中如何行事的长期过程）；句意为家里的餐桌礼仪与学校的轮流训练都是社会化的早期形式。可辨识物件：餐桌、教室座位、球场、家长与老师。","pos":[{"tag":"n.","zh":"社会化（过程，常作不可数）"},{"tag":"n.","zh":"交往；社交活动（不可数）"},{"tag":"n.","zh":"公有化；集体化（经济义）"}],"collocations":[{"phrase":"early socialization","zh":"早期社会化"},{"phrase":"primary socialization","zh":"初级社会化"},{"phrase":"political socialization","zh":"政治社会化"},{"phrase":"occupational socialization","zh":"职业社会化"},{"phrase":"peer socialization","zh":"同伴群体社会化"},{"phrase":"socialization process","zh":"社会化过程"}],"forms":[{"label":"不可数用法（整体过程）","form":"socialization"},{"label":"可数复数（具体过程或案例）","form":"socializations"},{"label":"动词（交往；使社会化）","form":"socialize"},{"label":"过去分词/形容词（已社会化的）","form":"socialized"},{"label":"名词（社会）","form":"society"}],"derivatives":[{"word":"socialize","pos":"v.","zh":"交往；使适应社会；使公有化"},{"word":"socialized","pos":"adj.","zh":"已适应社会规范的；公有化的"},{"word":"socializing","pos":"n.","zh":"交往活动"},{"word":"social","pos":"adj.","zh":"社会的；社交的"},{"word":"societal","pos":"adj.","zh":"整个社会层面的"},{"word":"sociologist","pos":"n.","zh":"社会学家"}],"senses":[{"no":"01","title":"Learning a group's norms","titleCN":"学习群体规范的过程","definition":"the long process through which a child or newcomer learns what a group expects, from table manners to ways of speaking","definitionCN":"儿童或新成员学习群体期待的长过程，从餐桌礼仪到说话方式","example":"Table manners at home and turn-taking at school are early forms of socialization.","exampleCN":"家里的餐桌礼仪与学校的轮流训练都是社会化的早期形式。","why":"The word is social plus the noun ending -ization, which names a process; the base sense is therefore the process of becoming social.","whyCN":"这个词由 social 加名词词尾 -ization 构成，该词尾表示过程，因此基础义就是「变得合乎社会」的过程。"},{"no":"02","title":"Training inside institutions","titleCN":"在机构中接受训练","definition":"the part of the process carried out by schools, armies, hospitals or workplaces with explicit rules","definitionCN":"由学校、军队、医院或职场以明文规则执行的那部分过程","example":"Military socialization turns recruits into people who salute before they ask why.","exampleCN":"军队的社会化把新兵变成先敬礼再问为什么的人。","why":"Institutions take over part of the family's work, so the same noun covers formal training with written rules.","whyCN":"机构接替了家庭的一部分工作，因此同一个名词也涵盖带明文规定的正式训练。"},{"no":"03","title":"Political socialization","titleCN":"政治社会化","definition":"the process by which people acquire political attitudes, party loyalties and ideas about authority","definitionCN":"人们获得政治态度、政党倾向与权威观念的过程","example":"Political socialization in the village began with the way elders talked about the council.","exampleCN":"村里的政治社会化始于长辈谈论议会的方式。","why":"Politics is learned like any other norm, so the general process was given a field-specific label.","whyCN":"政治像其他规范一样被学会，因此这个一般过程又被加上领域标签。"},{"no":"04","title":"Occupational socialization","titleCN":"职业社会化","definition":"the process of learning the values, vocabulary and habits of a profession during training and early work","definitionCN":"在培训与入职初期学习某一职业的价值观、术语与习惯的过程","example":"Occupational socialization teaches young nurses how much silence is allowed at a bedside.","exampleCN":"职业社会化教会年轻护士在病床边可以保持多少沉默。","why":"Every trade has its own unwritten rules, so the same process was named for the workplace.","whyCN":"每个行业都有自己的不成文规则，于是同一过程又被加上职场的名目。"},{"no":"05","title":"Peer-group socialization","titleCN":"同伴群体社会化","definition":"learning that happens among equals, such as children teaching one another playground rules","definitionCN":"在同龄人之间发生的学习，如孩子互相传授操场规则","example":"Peer socialization taught him which jokes were safe in the schoolyard.","exampleCN":"同伴社会化教会他哪些玩笑在校园里可以开。","why":"Adults are not the only teachers; equals also shape one another, which is why the process needed a peer variant.","whyCN":"成年人并非唯一的教导者，同龄人也会互相塑造，因此这一过程又有同伴变体。"},{"no":"06","title":"Making something collective","titleCN":"使某事物集体化","definition":"the act of bringing property or services under shared or state control","definitionCN":"把财产或服务转为共同或国家控制的行为","example":"The socialization of the mines followed the war, and the pits passed to public boards.","exampleCN":"战后矿井被公有化，矿区转由公共机构管理。","why":"The same word for 'making social' was applied to ownership, so the economic sense grew directly from the base meaning.","whyCN":"「使成为社会所有」的同一构词被用于所有权，因此经济义直接由基础义长出。"},{"no":"07","title":"Shaping behaviour through contact","titleCN":"通过接触塑造行为","definition":"in psychology, the shaping of behaviour by repeated interaction with other people rather than by instruction alone","definitionCN":"心理学中，通过与他人反复互动而非单纯教导来塑造行为","example":"The researchers studied socialization in toddlers by watching how they copied one another.","exampleCN":"研究者通过观察幼儿如何互相模仿来研究他们的社会化。","why":"Contact with others, not instruction alone, is the engine here, which is why the word can name a psychological mechanism as well as a social process.","whyCN":"这里的动力是与他人的接触而非单纯教导，因此这个词既能指社会过程，也能指心理机制。"},{"no":"08","title":"The act of mingling","titleCN":"交往活动本身","definition":"the everyday activity of meeting people and taking part in group life","definitionCN":"与人见面并参与群体生活的日常活动","example":"The weekly dinner is less a lesson than a chance for socialization.","exampleCN":"每周的聚餐与其说是课程，不如说是交往的机会。","why":"The mass noun also names the activity itself, so the word can mean both the long process and tonight's gathering.","whyCN":"这个不可数名词也指活动本身，因此既可指长过程，也可指今晚的聚会。"}],"etymology":{"intro":{"en":"Socialization is formed in English from social plus -ization, a noun ending that names a process. Social itself goes back to Latin socialis and socius 'ally'. Dates are approximate.","cn":"socialization 是英语用 social 加 -ization 构成的，后者是表示过程的名词词尾。social 本身可追溯到拉丁 socialis 与 socius「盟友」。年代均为约数。"},"items":[{"era":"LATIN SOCIUS","en":"Socius meant 'ally, companion'. From it came socialis 'of companionship or alliance'.","cn":"socius 意为「盟友、同伴」，由它构成 socialis「与结伴或联盟有关的」。"},{"era":"ENGLISH SOCIAL","en":"English social entered through Old French and named what belongs to companionship or to organized society.","cn":"英语 social 经古法语进入，指与结伴或与有组织社会有关的事物。"},{"era":"GREEK -IZEIN","en":"The verb ending -ize comes from Greek -izein, 'to make or to act', which English attached to nouns to form verbs such as socialize.","cn":"动词词尾 -ize 来自希腊 -izein「使……或做……」，英语把它接在名词后构成 socialize 一类动词。"},{"era":"LATIN -ATIO","en":"The noun ending -ation comes from Latin -atio, which names an action or a process, so socialize plus -ation yields the name of the process.","cn":"名词词尾 -ation 来自拉丁 -atio，表示动作或过程，因此 socialize 加 -ation 就得到过程的名称。"},{"era":"SOCIOLOGY","en":"Sociology adopted the term around the turn of the twentieth century to name how children acquire the ways of their group.","cn":"社会学在二十世纪之交采用这个词，用来命名儿童习得群体行事方式的过程。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest English use of socialization in the technical sense is not precisely dated, and estimates differ, so no exact year is claimed.","cn":"来源不确定（首见年代）：socialization 在术语意义上的最早英语用例缺乏精确考证，各家估计不一，因此不给出确切年份。"}]},"similar":{"note":{"en":"Group one holds words built on the same social root; group two holds processes of learning or absorbing a culture that are often confused with it.","cn":"第一组是同出 social 词根的词；第二组是常与社会化混淆的学习或文化吸收过程。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"socialize","ipa":"/ˈsəʊʃəlaɪz/","tag":"the verb","definition":"The verb meaning to mix or to train into norms; socialization is the noun for the process.","definitionCN":"意为交往或使人适应规范的动词；socialization 是表示过程的名词。"},{"word":"social","ipa":"/ˈsəʊʃəl/","tag":"the adjective","definition":"Means of interaction or society; it describes a quality, not a process.","definitionCN":"意为交往或社会的，描述性质而非过程。"},{"word":"societal","ipa":"/səˈsaɪətəl/","tag":"whole-society adjective","definition":"Describes the level of society as a whole; it does not name a learning process.","definitionCN":"描述整体社会层次，不指学习过程。"},{"word":"socialized","ipa":"/ˈsəʊʃəlaɪzd/","tag":"the participle","definition":"Describes a person already trained or a resource already made public; the noun names the training itself.","definitionCN":"描述已受训练的人或已公有化的资源；名词则指训练本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"enculturation","ipa":"/ˌenˌkʌltʃəˈreɪʃən/","tag":"learning a culture","definition":"The process of acquiring one's own culture, often used by anthropologists; socialization is the broader sociological term.","definitionCN":"习得自身文化的过程，人类学者常用；socialization 是更宽的社会学术语。"},{"word":"acculturation","ipa":"/əˌkʌltʃəˈreɪʃən/","tag":"contact between cultures","definition":"Change that occurs when two cultures meet; it need not involve growing up in one group.","definitionCN":"两种文化接触时发生的变化；不一定涉及在某一群体中成长。"},{"word":"assimilation","ipa":"/əˌsɪmɪˈleɪʃən/","tag":"absorption into the majority","definition":"The fuller absorption of a minority into a majority culture; socialization can occur without any such absorption.","definitionCN":"少数群体被主流文化较完整地吸收；社会化未必包含这种吸收。"},{"word":"upbringing","ipa":"/ˈʌpbrɪŋɪŋ/","tag":"family care","definition":"The way parents raise a child; socialization also happens outside the home, in schools, media and peer groups.","definitionCN":"父母养育孩子的方式；社会化还发生在家庭之外，如学校、媒体与同伴群体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Social plus -ization: the ending turns an adjective into the name of a process.","cn":"social 加 -ization：这个词尾把形容词变成过程的名称。"},{"en":"Fixed phrases mark the stage: early socialization, primary socialization, occupational socialization.","cn":"固定搭配标出阶段：早期社会化、初级社会化、职业社会化。"},{"en":"The family runs socialize, socialized, socializing, social and society.","cn":"同族词包括 socialize、socialized、socializing、social 与 society。"},{"en":"The verb ending is Greek and the noun ending is Latin, so the word is another hybrid of the learned vocabulary.","cn":"动词词尾来自希腊语，名词词尾来自拉丁语，因此这个词也是学术词汇中的混合体。"},{"en":"The economic sense uses the same shape: the socialization of the mines means their transfer to public ownership.","cn":"经济义沿用同一词形：矿井的公有化即转归公共所有。"}],"abstract":[{"en":"Picture a child slowly learning the unspoken rules of a room without ever being told them aloud.","cn":"想象一个孩子从未被明说，却慢慢学会一间屋子里的不成文规则。"},{"en":"Picture a river that carries each new arrival into the same current as everyone else.","cn":"想象一条河，把每个新来者带进与众人相同的水流。"},{"en":"Picture a private road being opened at once to every family on the hill.","cn":"想象一条私家路突然向山上每户人家开放。"}]},"examples":[{"en":"Socialization at home taught her to wait until the eldest had spoken.","cn":"家庭的社会化教会她等长辈开口后再说话。"},{"en":"The school's hidden curriculum is part of socialization, not part of the syllabus.","cn":"学校的隐性课程属于社会化的一部分，而不在教学大纲里。"},{"en":"The socialization of the railway network took a decade of legislation.","cn":"铁路网的公有化花了十年立法。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「social（社会的）+ ization（过程）」——把人带进社会的过程 → 社会化","word":"socialization"},"root":"socialization 由 social 加 -ization 构成；social 来自拉丁 socialis，词根 socius「盟友」；-ize 来自希腊 -izein，-ation 来自拉丁 -atio。该词作为社会学概念在二十世纪之交普及，最早书证年代不确定。","sensesIntro":{"en":"Eight senses trace one process outward: learning norms at home, then in institutions, politics and work, then among peers, then the collective and psychological readings, and finally the everyday activity itself.","cn":"八个义项沿同一过程向外展开：先在家里学规范，再在学校、政治与职场中学，随后在同伴间学，继而分出集体义与心理义，最后落到日常交往活动本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long table where each newcomer is quietly shown how to pass, wait and speak.","cn":"核心意象：一张长桌，每个新来者都被安静地示范怎样递菜、等待与开口。"},"chain":["SOCIAL","PROCESS","FAMILY NORMS","INSTITUTIONS","PEERS","COLLECTIVE FORM"],"branches":[{"senses":"01","en":"BASE PROCESS: the noun names the long becoming-social of a person.","cn":"基础过程：这个名词指一个人逐渐变得合乎社会的长过程。"},{"senses":"02 · 03","en":"INSTITUTIONS AND POLITICS: schools, armies and parties take over part of the teaching.","cn":"机构与政治：学校、军队与政党接替了一部分教导工作。"},{"senses":"04","en":"OCCUPATION: a trade adds its own unwritten rules to the general ones.","cn":"职业：行业在一般规则之上再加自己的不成文规则。"},{"senses":"05 · 07","en":"PEERS AND CONTACT: equals and repeated interaction shape behaviour without formal instruction.","cn":"同伴与接触：同龄人与反复互动在无正式教导的情况下塑造行为。"},{"senses":"06 · 08","en":"COLLECTIVE AND ACTIVITY: the same word covers shared ownership and the plain act of mingling.","cn":"集体与活动：同一个词既指共同所有，也指单纯的交往行为。"}]},"affixes":{"intro":{"en":"The word is assembled from an English adjective and two endings of Greek and Latin origin, one for the verb and one for the noun.","cn":"这个词由英语形容词加两个来源分别为希腊与拉丁的词尾装配而成，一个构成动词，一个构成名词。"},"latinIntro":{"en":"Latin socius supplies the root; Greek -izein supplies the verb ending; Latin -atio supplies the noun ending.","cn":"拉丁 socius 提供词根；希腊 -izein 提供动词词尾；拉丁 -atio 提供名词词尾。"},"items":[{"word":"social","structure":"socius + -alis (relating to)","meaning":"of companionship or society","meaningCN":"交往或社会的","example":"Social rules are learned.","exampleCN":"社会规则是学来的。"},{"word":"-ize","structure":"-izein (Greek verb ending, 'to make or act')","meaning":"to make or become","meaningCN":"使……；变得……","example":"The verb socialize is built with this ending.","exampleCN":"动词 socialize 由这个词尾构成。"},{"word":"-ation","structure":"-atio (Latin noun ending, action or process)","meaning":"action or process","meaningCN":"动作或过程","example":"The ending names the process.","exampleCN":"这个词尾命名过程。"},{"word":"socialization","structure":"social + -ize + -ation","meaning":"the process of becoming social","meaningCN":"社会化的过程","example":"Socialization begins at home.","exampleCN":"社会化从家庭开始。"},{"word":"socialize","structure":"social + -ize","meaning":"to mix or to train into norms","meaningCN":"交往；使适应规范","example":"Children socialize at school.","exampleCN":"孩子在学校交往。"},{"word":"socialized","structure":"socialize + -ed (past participle)","meaning":"already trained or made public","meaningCN":"已社会化的；已公有化的","example":"The pupils were socialized into the routine.","exampleCN":"学生们已被训练适应这套作息。"},{"word":"socializing","structure":"socialize + -ing (present participle or gerund)","meaning":"the act of mixing","meaningCN":"交往活动","example":"The club encourages socializing.","exampleCN":"俱乐部鼓励交往。"},{"word":"society","structure":"soci- + -ety (noun of state)","meaning":"a body of associated people","meaningCN":"联合起来的人群","example":"Society shapes the child.","exampleCN":"社会塑造孩子。"},{"word":"societal","structure":"society + -al (relating to)","meaning":"of society as a whole","meaningCN":"整个社会层面的","example":"The effects are societal.","exampleCN":"这些影响属于社会层面。"}],"derivatives":[{"word":"socialize","structure":"social + -ize (to make or become)","meaning":"to mix socially or to train into norms","meaningCN":"交往；使适应社会规范"},{"word":"socialized","structure":"socialize + -ed (past participle)","meaning":"already trained or made public","meaningCN":"已社会化的；已公有化的"},{"word":"socializing","structure":"socialize + -ing (noun of activity)","meaning":"the act of meeting people","meaningCN":"交往活动"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"socialis","structure":"socialis, -e (adjective)","meaning":"of companionship, allied","meaningCN":"结伴的；联盟的"},{"word":"socialisatio","structure":"socialisatio, socialisationis (f., modern Latin)","meaning":"a making social","meaningCN":"使社会化"}]}},{"word":"socialize","ipa_uk":"/ˈsəʊʃəlaɪz/","ipa_us":"/ˈsoʊʃəlaɪz/","definition_zh":"交往；与人相处；使适应社会规范；使公有化、集体化","definition_en":"to meet and spend time with other people in a friendly way, or to train someone to fit into a group","core_image":"一个人先被带去吃午饭，再被拉去周末清扫，点头逐渐变成熟识，最后能与整条街的人自然打招呼","scene":"New employees socialize over lunch and weekend clean-ups until the whole block knows them.","sceneCN":"此处指「在工作之外与人相处、逐渐熟识」（第 1 个义项：以轻松方式与他人交往）；句意为新员工借午餐与周末清扫同大家交往，直到整条街都认识他们。可辨识物件：长餐桌、清扫工具、街区巷道、门牌与笑脸。","pos":[{"tag":"v.","zh":"交往；参加社交活动（不及物）"},{"tag":"v.","zh":"使适应社会规范；使学会群体生活（及物）"},{"tag":"v.","zh":"使公有化；使集体化（及物）"}],"collocations":[{"phrase":"socialize with colleagues","zh":"与同事交往"},{"phrase":"socialize children","zh":"使孩子适应社会"},{"phrase":"socialize the costs","zh":"使成本社会化"},{"phrase":"socialize at work","zh":"在工作中社交"},{"phrase":"socialize an industry","zh":"使某行业公有化"},{"phrase":"socialize new members","zh":"使新成员融入"}],"forms":[{"label":"三单（he/she/it）","form":"socializes"},{"label":"过去式","form":"socialized"},{"label":"过去分词","form":"socialized"},{"label":"现在分词","form":"socializing"},{"label":"名词（社会化）","form":"socialization"},{"label":"形容词（社会的）","form":"social"}],"derivatives":[{"word":"socialization","pos":"n.","zh":"社会化"},{"word":"socialized","pos":"adj.","zh":"已社会化的；公有化的"},{"word":"socializing","pos":"n.","zh":"交往活动"},{"word":"social","pos":"adj.","zh":"社会的；社交的"},{"word":"society","pos":"n.","zh":"社会"},{"word":"sociable","pos":"adj.","zh":"合群的；善于交往的"}],"senses":[{"no":"01","title":"To meet people socially","titleCN":"与人交往、参加社交活动","definition":"to spend time with other people in a relaxed, friendly way, especially outside work","definitionCN":"在工作之外以轻松友好的方式与他人共度时光","example":"New employees socialize over lunch and weekend clean-ups until the whole block knows them.","exampleCN":"新员工借午餐与周末清扫同大家交往，直到整条街都认识他们。","why":"Social plus the verb ending -ize gives 'to make social' or 'to act socially'; the everyday sense is simply to take part in company.","whyCN":"social 加动词词尾 -ize 表示「使成为社会的」或「做社会性的事」，日常义就是参与交往。"},{"no":"02","title":"To train someone into a group","titleCN":"使某人适应群体规范","definition":"to bring a child or newcomer into the expected ways of a group through repeated guidance","definitionCN":"通过反复引导，使儿童或新成员学会群体的期待行事方式","example":"The school socializes pupils into queues, bells and shared desks.","exampleCN":"学校把学生训练成习惯排队、听铃声与共用课桌的人。","why":"The causative reading 'to make social' turned into 'to make fit for society', which is the base of the sociological noun.","whyCN":"「使成为社会的」这一使动义转为「使适应社会」，这正是社会学名词的基础。"},{"no":"03","title":"To bring under collective ownership","titleCN":"使公有化、集体化","definition":"to transfer land, industry or costs from private owners to public or shared control","definitionCN":"把土地、产业或成本从私人所有者转归公共或共同控制","example":"The new government moved to socialize the railways within a year.","exampleCN":"新政府上台一年内就着手把铁路公有化。","why":"If social means belonging to a community, then to socialize property means to make it belong to the community, a political extension of 'make social'.","whyCN":"如果 social 指属于共同体，那么使财产社会化就是使其归共同体所有，这是「使成为社会的」在政治上的延伸。"},{"no":"04","title":"To introduce a newcomer","titleCN":"把新来者带进群体","definition":"to help a new person enter a group by arranging introductions and shared activities","definitionCN":"通过安排介绍与共同活动，帮助新来者进入群体","example":"A neighbour socialized the family by inviting them to the block party.","exampleCN":"一位邻居邀请这家人参加街区聚会，使他们融入社区。","why":"Mixing is not only pleasure; it is also the act of bringing someone in, so the verb takes on this welcoming sense.","whyCN":"交往不只是消遣，也是把某人带进来的动作，因此这个动词又带上迎接新人的意思。"},{"no":"05","title":"To turn an event into a social occasion","titleCN":"使某项活动成为社交场合","definition":"to give an activity a friendly, conversational character rather than a purely practical one","definitionCN":"使某项活动带上友好交谈的性质，而非纯务实性质","example":"They socialized the dull committee meeting with coffee and introductions.","exampleCN":"他们用咖啡与自我介绍把沉闷的委员会会议变得像社交聚会。","why":"Because the verb means to make something social, it can describe changing the tone of an event, not only attending it.","whyCN":"由于这个动词意为「使某事物具有社会性」，它可以描述改变活动气氛，而不只是出席。"},{"no":"06","title":"To shape behaviour through interaction","titleCN":"通过交往塑造行为","definition":"to shape a person's habits gradually through repeated contact with others","definitionCN":"通过与他人的反复接触逐步塑造一个人的习惯","example":"Playground games socialize children into sharing rules without any formal lesson.","exampleCN":"操场游戏不需要正式课程，就把孩子训练成懂得分享规则的人。","why":"This is the psychological side of training: behaviour is shaped by contact, not only by instruction.","whyCN":"这是训练的心理侧面：行为由接触塑造，而不只由教导塑造。"},{"no":"07","title":"To make socially acceptable","titleCN":"使合乎社会规范","definition":"to adjust a practice so that it fits accepted social norms","definitionCN":"调整某项做法，使其符合被接受的社会规范","example":"The old ceremony was socialized into a public holiday rather than abandoned.","exampleCN":"旧仪式被改造成公共节日而保留下来，并没有被废弃。","why":"Things as well as people can be made social, which is why the verb sometimes means bringing a practice into line with public norms.","whyCN":"不只是人能社会化，事物也能，因此这个动词有时指使某项做法符合公共规范。"},{"no":"08","title":"To join group leisure","titleCN":"参加群体休闲活动","definition":"to take part in the leisure life of a group, such as dinners, games or outings","definitionCN":"参加群体的休闲生活，如聚餐、游戏或郊游","example":"On Sundays the whole yard socializes around a long table of fruit and tea.","exampleCN":"每逢星期天，整个院子都围着长桌吃水果喝茶，彼此交往。","why":"The narrow everyday reading focuses on leisure rather than training, and it is the sense most common in speech.","whyCN":"这一窄化的日常义聚焦休闲而非训练，是口语中最常见的用法。"}],"etymology":{"intro":{"en":"Socialize is social plus the Greek-derived verb ending -ize. The verb was formed in English and later split into a friendly sense and a technical sense of training or public ownership. Dates are approximate.","cn":"socialize 由 social 加希腊来源的动词词尾 -ize 构成。这个动词在英语中形成，后来分出「友好交往」与「训练或公有化」两类技术义。年代均为约数。"},"items":[{"era":"LATIN SOCIALIS","en":"Socialis meant 'of companionship or alliance', from socius 'ally'. It reached English as social through Old French.","cn":"socialis 意为「结伴或联盟的」，源于 socius「盟友」，经古法语进入英语作 social。"},{"era":"GREEK -IZEIN","en":"Greek -izein meant 'to make, to act, to cause'. English took it as -ize and used it freely with nouns and adjectives.","cn":"希腊 -izein 意为「使、做、造成」，英语借作 -ize，广泛接在名词与形容词后构词。"},{"era":"VERB FORMATION","en":"Socialize was formed in English on the adjective social, with the literal sense 'to make social'.","cn":"socialize 是英语在形容词 social 基础上构成的，字面义为「使成为社会的」。"},{"era":"TRAINING SENSE","en":"The literal sense developed into 'to make fit for society', which became the standard term in sociology and education.","cn":"字面义发展为「使适应社会」，并成为社会学与教育学的标准术语。"},{"era":"POLITICAL SENSE","en":"In the nineteenth and twentieth centuries the same verb was applied to property, giving 'to bring into public ownership'.","cn":"在十九与二十世纪，同一个动词被用于财产，产生「转为公有」的意思。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest English citation of socialize is not precisely dated, and the order in which its senses appeared is reconstructed from later records.","cn":"来源不确定（首见年代）：socialize 的最早英语书证缺乏精确年代，各义项出现的先后顺序是根据较晚记录推定的。"}]},"similar":{"note":{"en":"Group one holds verbs built on the same social root or the same ending; group two holds verbs of joining that differ in tone or in purpose.","cn":"第一组是同出 social 词根或同带 -ize 词尾的动词；第二组是语气或目的不同的「加入」类动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"social","ipa":"/ˈsəʊʃəl/","tag":"the adjective","definition":"The adjective for interaction or society; socialize is the verb formed from it.","definitionCN":"表示交往或社会的形容词；socialize 是由它构成的动词。"},{"word":"socialization","ipa":"/ˌsəʊʃəlaɪˈzeɪʃən/","tag":"the noun","definition":"Names the process that socialize describes in action.","definitionCN":"指 socialize 所述动作的过程名词。"},{"word":"sociable","ipa":"/ˈsəʊsiəbl/","tag":"the temperament","definition":"An adjective for a person who easily joins others; it cannot replace the verb in 'socialize with'.","definitionCN":"描述乐于与人相处的形容词，不能替换「与……交往」中的动词。"},{"word":"publicize","ipa":"/ˈpʌblɪsaɪz/","tag":"same ending, different base","definition":"Means to make widely known; the ending is the same but the base is public, so the meaning is not shared.","definitionCN":"意为使广为人知；词尾相同但词基是 public，因此词义并不相通。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mingle","ipa":"/ˈmɪŋɡl/","tag":"move among people","definition":"To circulate among guests; it stresses movement and casual talk rather than becoming part of a group.","definitionCN":"在宾客间走动交谈；强调走动与闲聊，而非融入群体。"},{"word":"mix","ipa":"/mɪks/","tag":"the plain verb","definition":"A general verb for combining or associating; socialize adds the friendly, group-life flavour.","definitionCN":"结合或往来的通称；socialize 多一层友好群体生活的意味。"},{"word":"interact","ipa":"/ˌɪntərˈækt/","tag":"two-way action","definition":"To act on one another, often in a studied or formal way; it need not be friendly leisure.","definitionCN":"彼此施加作用，常用于研究或正式语境，不必是友好休闲。"},{"word":"associate","ipa":"/əˈsəʊʃieɪt/","tag":"formal connection","definition":"To keep company with or connect oneself to a group, often with a formal or professional tone.","definitionCN":"与某群体来往或建立联系，常带正式或职业语气。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Social plus -ize: the verb literally means to make social or to act in company.","cn":"social 加 -ize：动词字面义是「使成为社会的」或在人群中行动。"},{"en":"Fixed phrases mark the sense: socialize with colleagues, socialize children, socialize costs.","cn":"固定搭配标出词义：与同事交往、使孩子适应社会、使成本社会化。"},{"en":"The family runs socialization, socialized, socializing, social and society.","cn":"同族词包括 socialization、socialized、socializing、social 与 society。"},{"en":"The same ending appears in organize, realize and publicize, but each base word sets its own meaning.","cn":"同一词尾也见于 organize、realize 与 publicize，但每个词基决定各自的词义。"},{"en":"The technical senses are marked by objects: you socialize children into rules, and you socialize an industry into public hands.","cn":"技术义靠宾语分辨：使孩子学会规则，或使某行业转为公有。"}],"abstract":[{"en":"Picture a newcomer standing at the edge of a room until someone pulls out the next chair.","cn":"想象一个新人站在屋子边缘，直到有人拉出旁边的椅子。"},{"en":"Picture a private gate being opened so that the whole lane may walk through it.","cn":"想象一扇私人的门被打开，让整条巷子的人都能穿行。"},{"en":"Picture two strangers slowly turning the same dull task into a conversation.","cn":"想象两个陌生人慢慢把同一件枯燥的事变成一场谈话。"}]},"examples":[{"en":"The department socializes on Friday afternoons, and nobody talks about work.","cn":"这个部门每周五下午聚会交往，没人谈工作。"},{"en":"Board games socialize children into waiting their turn.","cn":"棋盘游戏让孩子学会轮流等待。"},{"en":"The council moved to socialize waste collection across the district.","cn":"议会着手把全区的垃圾收集转为公共管理。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「social（社会的）+ ize（使……）」——使彼此变成熟人 → 交往；使适应社会 → 社会化","word":"socialize"},"root":"socialize 由 social 加希腊来源词尾 -ize 构成；social 出自拉丁 socialis，词根 socius「盟友」；-ize 出自希腊 -izein「使、做」。该动词在英语中形成，最早书证年代不确定。","sensesIntro":{"en":"Eight senses split one verb in two directions: outward into friendly company and inward into training, then into ownership, welcome, tone, shaping, norms and plain leisure.","cn":"八个义项把这个动词分成两个方向：向外是友好交往，向内是训练，再分出公有化、迎接、气氛、塑造、规范与单纯休闲。"},"semanticMap":{"core":{"en":"CORE IMAGE: a newcomer at the edge of a room, gradually pulled into its circle.","cn":"核心意象：一个新人站在屋子边缘，逐渐被拉进圈子。"},"chain":["SOCIAL","MAKE SOCIAL","MIX FREELY","TRAIN INTO NORMS","PUBLIC OWNERSHIP","GROUP LIFE"],"branches":[{"senses":"01 · 08","en":"FREE MIXING: the everyday sense is simply friendly company and group leisure.","cn":"自由交往：日常义就是友好结伴与群体休闲。"},{"senses":"02 · 06","en":"TRAINING: repeated contact and guidance turn a newcomer into a member.","cn":"训练：反复接触与引导把新人变成成员。"},{"senses":"03","en":"OWNERSHIP: making something social becomes making it publicly held.","cn":"所有权：使某物具有社会性，转为使其归公共所有。"},{"senses":"04 · 05","en":"WELCOME AND TONE: one can bring a person in and can also change an event's mood.","cn":"迎接与气氛：既能带人进来，也能改变活动的气氛。"},{"senses":"07","en":"NORMATIVE FIT: even a practice can be adjusted to accepted public rules.","cn":"规范适配：连一项做法也能被调整到符合公共规则。"}]},"affixes":{"intro":{"en":"The verb joins an English adjective to a Greek verb ending, and its derived words keep the same -iz- spine.","cn":"这个动词把英语形容词接到希腊动词词尾上，其派生词延续同一条 -iz- 词干。"},"latinIntro":{"en":"Latin socius and socialis supply the base; Greek -izein supplies the ending that makes it a verb.","cn":"拉丁 socius 与 socialis 提供词基；希腊 -izein 提供使其成为动词的词尾。"},"items":[{"word":"soci-","structure":"socius (Latin noun, 'ally')","meaning":"companion; ally","meaningCN":"同伴；盟友","example":"The root names the people one joins.","exampleCN":"这个词根指人所加入的人群。"},{"word":"-al","structure":"-alis (Latin adjectival suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix forms social.","exampleCN":"这个词尾构成 social。"},{"word":"-ize","structure":"-izein (Greek verb ending)","meaning":"to make or to act","meaningCN":"使……；做……","example":"The ending forms the verb.","exampleCN":"这个词尾构成动词。"},{"word":"socialize","structure":"social + -ize","meaning":"to make social; to mix","meaningCN":"使社会化；交往","example":"Newcomers socialize quickly.","exampleCN":"新来者很快开始交往。"},{"word":"socialized","structure":"socialize + -ed","meaning":"already trained or made public","meaningCN":"已社会化的；公有化的","example":"The children were socialized early.","exampleCN":"孩子们很早就完成社会化。"},{"word":"socializing","structure":"socialize + -ing","meaning":"the activity of mixing","meaningCN":"交往活动","example":"Socializing takes little time here.","exampleCN":"这里的交往不占太多时间。"},{"word":"socialization","structure":"socialize + -ation","meaning":"the process of becoming social","meaningCN":"社会化过程","example":"Socialization is studied in schools.","exampleCN":"社会化在学校里被研究。"},{"word":"society","structure":"soci- + -ety","meaning":"a body of associated people","meaningCN":"联合起来的人群","example":"Society sets the rules.","exampleCN":"社会设定规则。"},{"word":"sociable","structure":"sociare + -able","meaning":"ready to join others","meaningCN":"乐于与人相处的","example":"She is sociable by nature.","exampleCN":"她天性合群。"}],"derivatives":[{"word":"socialization","structure":"socialize + -ation (process)","meaning":"the process of becoming social","meaningCN":"社会化过程"},{"word":"socialized","structure":"socialize + -ed (past participle)","meaning":"already trained or made public","meaningCN":"已社会化的；已公有化的"},{"word":"socializing","structure":"socialize + -ing (gerund)","meaning":"the activity of meeting people","meaningCN":"交往活动"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"socialis","structure":"socialis, -e (adjective)","meaning":"of companionship, allied","meaningCN":"结伴的；联盟的"},{"word":"socializare","structure":"socializare (verb, modern Latin)","meaning":"to make social","meaningCN":"使社会化"}]}},{"word":"social","ipa_uk":"/ˈsəʊʃəl/","ipa_us":"/ˈsoʊʃəl/","definition_zh":"社会的；社交的；与社会地位有关的；群居的；社交聚会","definition_en":"relating to society, to interaction between people, or to the way people are grouped by status","core_image":"一群人围坐长桌，让菜、传话、照看孩子，饭桌本身成了人与人彼此连接的场所","scene":"The long table turned a plain meal into a social occasion for the whole street.","sceneCN":"此处指「使一顿饭变成人与人往来的社交场合」（第 4 个义项：属于聚会与交往的）；句意为这张长桌把普通的饭食变成了整条街的社交场合。可辨识物件：长桌、传递的菜盘、孩子、门口招呼的邻居。","pos":[{"tag":"adj.","zh":"社会的；社会性的"},{"tag":"adj.","zh":"社交的；交际的"},{"tag":"adj.","zh":"社会地位的；阶层的"},{"tag":"n.","zh":"社交聚会（非正式，英式）"}],"collocations":[{"phrase":"social media","zh":"社交媒体"},{"phrase":"social class","zh":"社会阶层"},{"phrase":"social network","zh":"社交网络"},{"phrase":"social unrest","zh":"社会动荡"},{"phrase":"social welfare","zh":"社会福利"},{"phrase":"social skills","zh":"社交技能"},{"phrase":"social life","zh":"社交生活"}],"forms":[{"label":"原级","form":"social"},{"label":"比较级","form":"more social"},{"label":"最高级","form":"most social"},{"label":"副词","form":"socially"},{"label":"名词（社会）","form":"society"},{"label":"名词（社交聚会）","form":"social"}],"derivatives":[{"word":"society","pos":"n.","zh":"社会"},{"word":"socially","pos":"adv.","zh":"在社交上；在社会层面"},{"word":"societal","pos":"adj.","zh":"整个社会层面的"},{"word":"socialize","pos":"v.","zh":"交往；使社会化"},{"word":"socialization","pos":"n.","zh":"社会化"},{"word":"sociable","pos":"adj.","zh":"合群的"},{"word":"socialist","pos":"n./adj.","zh":"社会主义者；社会主义的"}],"senses":[{"no":"01","title":"Relating to society","titleCN":"与社会有关的","definition":"relating to society as an organized body of people, its institutions and its arrangements","definitionCN":"与作为有组织人群的社会、其制度与安排有关","example":"Housing policy is a social question, not only an economic one.","exampleCN":"住房政策是社会问题，不只是经济问题。","why":"Social comes from Latin socialis 'of alliance or companionship', so its first duty is to describe what belongs to organized human life.","whyCN":"social 来自拉丁 socialis「结伴或联盟的」，因此首要任务是描述属于有组织人类生活的事物。"},{"no":"02","title":"Relating to interaction","titleCN":"涉及人与人交往的","definition":"relating to contact, conversation and shared activity between people","definitionCN":"涉及人与人之间的接触、交谈与共同活动","example":"Social contact with neighbours reduced the isolation of the elderly.","exampleCN":"与邻居的社交接触减轻了老人的孤立感。","why":"The same root names allies and companions, so the adjective naturally covers what happens between people rather than inside one person.","whyCN":"同一词根指盟友与同伴，因此这个形容词自然涵盖人与人之间发生的事，而非个人内心。"},{"no":"03","title":"Relating to status and class","titleCN":"涉及社会地位与阶层的","definition":"relating to a person's rank, class or standing in a society","definitionCN":"涉及一个人在社会中的等级、阶层或地位","example":"Social background still predicts which university a student reaches.","exampleCN":"社会背景仍能预测一名学生能进入哪所大学。","why":"Once society was seen as layered, the adjective was used for the layers, giving the class sense.","whyCN":"当社会被视为分层结构，这个形容词就被用于指各层，从而产生阶层义。"},{"no":"04","title":"Of a friendly gathering","titleCN":"属于社交聚会的","definition":"describing an occasion whose purpose is to meet and talk rather than to work","definitionCN":"描述以见面交谈而非工作为目的的场合","example":"The long table turned a plain meal into a social occasion for the whole street.","exampleCN":"这张长桌把普通的饭食变成了整条街的社交场合。","why":"Interaction is the point of some events and not others, so the adjective came to label the friendly kind of gathering.","whyCN":"有些场合以交往为目的，有些则不是，因此这个形容词被用来标记友好的聚会。"},{"no":"05","title":"Of group-living animals","titleCN":"群居动物的","definition":"describing animals that live in organized groups rather than alone","definitionCN":"描述以有组织群体而非独居方式生活的动物","example":"Bees and termites are social insects with clear divisions of labour.","exampleCN":"蜜蜂与白蚁是分工明确的群居昆虫。","why":"Biology borrowed the word because such animals form something like a society with roles and exchanges.","whyCN":"生物学借用这个词，因为这类动物会形成类似有角色与交换的社会。"},{"no":"06","title":"Of shared provision","titleCN":"公共供给的","definition":"relating to services or costs provided collectively rather than by each household alone","definitionCN":"涉及由集体而非各家独自提供的服务或费用","example":"Social housing and social insurance spread the cost across the whole population.","exampleCN":"社会住房与社会保险把成本分摊到全体人口身上。","why":"The collective reading of society produced a policy sense: what is social is paid for and used together.","whyCN":"社会的集体义产生出政策义：社会性的事物由众人共同支付与使用。"},{"no":"07","title":"Of social media","titleCN":"社交媒体的","definition":"relating to online platforms where users publish and respond to one another","definitionCN":"涉及用户彼此发布与回应的网络平台","example":"The campaign spread through social media before any newspaper noticed.","exampleCN":"这场运动先是在社交媒体上扩散，报纸才注意到。","why":"The newest sense simply applies the old word for interaction to a new place where interaction happens.","whyCN":"最新的义项只是把指交往的旧词用到交往发生的新场所。"},{"no":"08","title":"A social gathering","titleCN":"社交聚会","definition":"a friendly meeting organized for members of a club or group","definitionCN":"为社团或群体成员组织的友好聚会","example":"The history society holds a social every spring.","exampleCN":"历史学会每年春天举办一次社交聚会。","why":"English often turns an adjective into a noun by leaving out the noun it modified, so social came to stand for a social event.","whyCN":"英语常省略被修饰的名词，使形容词转作名词，因此 social 就代表社交活动。"}],"etymology":{"intro":{"en":"Social comes from Latin socialis 'of companionship or alliance', from socius 'ally', through Old French. Its range covers society, interaction, class, gatherings, group-living animals and public provision. Dates are approximate.","cn":"social 经古法语来自拉丁 socialis「结伴或联盟的」，词根 socius「盟友」。其范围涵盖社会、交往、阶层、聚会、群居动物与公共供给。年代均为约数。"},"items":[{"era":"LATIN SOCIUS","en":"Socius meant 'companion, ally'. Its deeper origin is not established, and a proposed link to sequi 'to follow' remains a hypothesis.","cn":"socius 意为「同伴、盟友」。其更深来源未得到证明，有人提出它与 sequi「跟随」有关，仍属假说。"},{"era":"LATIN SOCIALIS","en":"Socialis meant 'of companionship, of alliance', formed from socius with the relational suffix -alis.","cn":"socialis 意为「结伴的、联盟的」，由 socius 加关系词尾 -alis 构成。"},{"era":"OLD FRENCH","en":"Old French social carried the adjective into English, where it first described companionship and later organized society.","cn":"古法语 social 把这个形容词带入英语，先描述结伴关系，后描述有组织的社会。"},{"era":"CLASS SENSE","en":"In the nineteenth century, with the rise of class analysis, the adjective was applied to rank and background.","cn":"到十九世纪，随着阶级分析的兴起，这个形容词被用于等级与出身。"},{"era":"NEW PLATFORMS","en":"In the twenty-first century social was attached to online platforms, extending the interaction sense to a new medium.","cn":"到二十一世纪，social 被接到网络平台上，把交往义延伸到新媒介。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin and first date): the pre-Latin origin of socius is unsettled, and the earliest English use of social is not precisely dated, so any older form is a reconstruction.","cn":"来源不确定（更深词源与首见年代）：socius 在拉丁语之前的来源无定论，social 的最早英语用例也缺乏精确年代，凡给出更早形态均属重构。"}]},"similar":{"note":{"en":"Group one holds look-alikes built on the same root; group two holds adjectives for what is shared, public or friendly, each with a different emphasis.","cn":"第一组是同根外形相近的词；第二组是表示共享、公共或友好的形容词，各自侧重不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"societal","ipa":"/səˈsaɪətəl/","tag":"whole-society adjective","definition":"A formal adjective for society as a whole, especially structures; social is broader and more everyday.","definitionCN":"指整个社会、尤指结构的正式形容词；social 更宽、更日常。"},{"word":"sociable","ipa":"/ˈsəʊsiəbl/","tag":"a person's temperament","definition":"Means fond of company; it describes people, not policies or classes.","definitionCN":"意为喜欢与人相处，描述人，不描述政策或阶层。"},{"word":"socialist","ipa":"/ˈsəʊʃəlɪst/","tag":"political label","definition":"Names a supporter of a political order; it shares the root but adds a doctrine, not a quality.","definitionCN":"指某种政治秩序的支持者，同根但加上的是主义而非性质。"},{"word":"society","ipa":"/səˈsaɪəti/","tag":"the noun","definition":"The body of people itself; social is the adjective describing it or its interactions.","definitionCN":"指人群本身；social 是描述它或其交往的形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"communal","ipa":"/kəˈmjuːnəl/","tag":"shared inside a group","definition":"Stresses common use or common identity within a smaller community; social can also mean state-level or class-level.","definitionCN":"强调较小共同体内部的共用或共同身份；social 还可指国家或阶层层面。"},{"word":"public","ipa":"/ˈpʌblɪk/","tag":"state and open access","definition":"Relates to the state, official services or open access; it does not carry the companionship flavour of social.","definitionCN":"与国家、官方服务或公开性有关，不带 social 的结伴意味。"},{"word":"collective","ipa":"/kəˈlektɪv/","tag":"group as one actor","definition":"Means held or done by a group as a single unit; social is wider and can describe tone as well as ownership.","definitionCN":"指由群体作为单一单位持有或完成；social 更宽，还能描述气氛。"},{"word":"civic","ipa":"/ˈsɪvɪk/","tag":"city and citizenship","definition":"Relates to a city and the duties of citizens; it is narrower than social and more official in tone.","definitionCN":"与城市及公民义务有关，比 social 窄，语气更官方。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin socius 'ally' plus -alis: the adjective of companionship, hence of society and interaction.","cn":"拉丁 socius「盟友」加 -alis：结伴的形容词，进而指社会与交往。"},{"en":"Fixed phrases mark the range: social class, social media, social welfare, social skills.","cn":"固定搭配标出范围：社会阶层、社交媒体、社会福利、社交技能。"},{"en":"The family runs society, societal, socialize, socialization and sociable.","cn":"同族词包括 society、societal、socialize、socialization 与 sociable。"},{"en":"The noun use is an ellipsis: a social event becomes simply a social.","cn":"名词用法是省略而来：社交活动被简称为 social。"},{"en":"The word covers both the friendly and the structural, which is why it appears with both media and class.","cn":"这个词既覆盖友好交往也覆盖结构，因此既能与媒体搭配，也能与阶层搭配。"}],"abstract":[{"en":"Picture a long table where nobody is a stranger by the second cup of tea.","cn":"想象一张长桌，第二杯茶下肚时已没有陌生人。"},{"en":"Picture a ladder of floors in one building, each floor a different school district.","cn":"想象一栋楼里层层叠起的楼层，每层对应不同的学区。"},{"en":"Picture a bee garden where every insect has a task and none is idle.","cn":"想象一座蜂园，每只昆虫都有任务，没有谁闲着。"}]},"examples":[{"en":"Social ties in the block grew stronger after the shared garden opened.","cn":"共用花园开放后，街区里的社会联系更紧密了。"},{"en":"The report measured social mobility across three generations.","cn":"这份报告测量了三代人的社会流动。"},{"en":"She belongs to a social club that meets above the bakery.","cn":"她参加一个在面包店楼上聚会的社交俱乐部。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「so（如此）+ cial（相处）」——如此多人相处 → 社会的、社交的","word":"social"},"root":"social 经古法语来自拉丁 socialis「结伴或联盟的」，由 socius「盟友」加关系词尾 -alis 构成；socius 更深来源不确定，与 sequi「跟随」的联系仅为假说。","sensesIntro":{"en":"Eight senses branch from companionship: the organized society, plain interaction, class standing, a friendly event, group-living animals, public provision, online platforms and the gathering itself.","cn":"八个义项从「结伴」向四周分叉：有组织的社会、单纯交往、阶层地位、友好聚会、群居动物、公共供给、网络平台与聚会本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long table with one empty chair that someone is always about to fill.","cn":"核心意象：一张长桌，总有一把空椅子等着有人坐下。"},"chain":["ALLY","INTERACTION","ORGANIZED SOCIETY","CLASS LAYER","SHARED COST","NEW PLATFORMS"],"branches":[{"senses":"01 · 02","en":"SOCIETY AND CONTACT: organized life and plain person-to-person contact are the two base readings.","cn":"社会与接触：有组织的生活与单纯的人与人接触是两个基础读法。"},{"senses":"03","en":"CLASS LAYER: society seen as stacked floors rather than a flat table.","cn":"阶层：社会被看作层层叠起的楼层，而非平桌。"},{"senses":"04 · 08","en":"GATHERING: a friendly event and the event noun are the same social occasion.","cn":"聚会：友好场合与指该场合的名词，是同一个社交活动。"},{"senses":"05","en":"GROUP LIFE: animals with roles and exchanges extend the table image beyond humans.","cn":"群体生活：有角色与交换的动物把长桌意象延伸到人类之外。"},{"senses":"06 · 07","en":"SHARED AND ONLINE: pooled provision and online platforms are two new places for interaction.","cn":"共享与线上：共同供给与网络平台是交往的两个新场所。"}]},"affixes":{"intro":{"en":"The adjective is a Latin relational form whose endings also build the noun and the verb of the family.","cn":"这个形容词是拉丁关系形式，其词尾也构成该词族的名词与动词。"},"latinIntro":{"en":"Latin socius and socialis supply the base; -alis supplies the adjective and -izein supplies the verb ending used in English.","cn":"拉丁 socius 与 socialis 提供词基；-alis 提供形容词词尾，希腊 -izein 提供英语动词词尾。"},"items":[{"word":"soci-","structure":"socius (Latin noun, 'ally')","meaning":"companion; ally","meaningCN":"同伴；盟友","example":"The root supplies the idea of association.","exampleCN":"这个词根提供「联合」的意思。"},{"word":"-al","structure":"-alis (Latin adjectival suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix makes the adjective.","exampleCN":"这个词尾构成形容词。"},{"word":"social","structure":"socius + -alis","meaning":"of companionship or society","meaningCN":"结伴的；社会的","example":"Social life changed quickly.","exampleCN":"社交生活变化很快。"},{"word":"society","structure":"soci- + -ety (noun of state)","meaning":"a body of associated people","meaningCN":"联合起来的人群","example":"Society pressed for reform.","exampleCN":"社会要求改革。"},{"word":"socially","structure":"social + -ly (adverbial)","meaning":"in social terms","meaningCN":"在社交上；在社会层面","example":"The rule was socially accepted.","exampleCN":"这条规则被社会接受。"},{"word":"societal","structure":"society + -al","meaning":"of society as a whole","meaningCN":"整个社会层面的","example":"Societal costs were ignored.","exampleCN":"社会成本被忽视。"},{"word":"socialize","structure":"social + -ize","meaning":"to mix or make social","meaningCN":"交往；使社会化","example":"Children socialize in groups.","exampleCN":"孩子在群体中交往。"},{"word":"socialization","structure":"socialize + -ation","meaning":"the process of becoming social","meaningCN":"社会化过程","example":"Socialization takes years.","exampleCN":"社会化需要多年。"},{"word":"sociable","structure":"sociare + -able","meaning":"ready to join others","meaningCN":"乐于与人相处的","example":"He is a sociable neighbour.","exampleCN":"他是个好相处的邻居。"}],"derivatives":[{"word":"society","structure":"soci- + -ety (noun of state)","meaning":"a body of associated people","meaningCN":"社会；社团"},{"word":"socially","structure":"social + -ly (adverbial)","meaning":"in social terms","meaningCN":"在社交上；在社会层面"},{"word":"socialize","structure":"social + -ize (to make or become)","meaning":"to mix or to train into norms","meaningCN":"交往；使社会化"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"socialis","structure":"socialis, -e (adjective)","meaning":"of companionship, allied","meaningCN":"结伴的；联盟的"},{"word":"societas","structure":"societas, societatis (f., third declension)","meaning":"association, community","meaningCN":"联合；共同体"}]}},{"word":"social system","ipa_uk":"/ˈsəʊʃəl ˈsɪstəm/","ipa_us":"/ˈsoʊʃəl ˈsɪstəm/","definition_zh":"社会制度体系；一个社会中相互配合的角色、规范与机构的总和；社会系统","definition_en":"the whole set of institutions, roles and norms by which a society organizes itself and keeps running","core_image":"一座城镇里，学校、医院、警局与工会各自负责一段，明文规定把彼此接口接上，整套安排像一部持续运转的机器","scene":"The town's social system ties schools, clinics and unions into one set of written rules.","sceneCN":"此处指「学校、医院、工会等机构相互配合而成的整套制度安排」（第 1 个义项：一个社会中互相衔接的制度总和）；句意为这座城镇的社会制度把学校、诊所与工会编进同一套明文规则。可辨识物件：校门、诊所招牌、工会公告栏、市政厅窗口。","pos":[{"tag":"n.","zh":"社会制度体系（可数或不可数）"},{"tag":"n.","zh":"社会系统（系统论意义上的整体）"}],"collocations":[{"phrase":"traditional social system","zh":"传统社会制度"},{"phrase":"colonial social system","zh":"殖民时期的社会制度"},{"phrase":"social system theory","zh":"社会系统理论"},{"phrase":"reform the social system","zh":"改革社会制度"},{"phrase":"social system of a town","zh":"一座城镇的社会系统"},{"phrase":"stable social system","zh":"稳定的社会制度"}],"forms":[{"label":"单数","form":"social system"},{"label":"复数","form":"social systems"},{"label":"形容词（社会的）","form":"social"},{"label":"名词（制度）","form":"system"},{"label":"形容词（系统的）","form":"systemic"}],"derivatives":[{"word":"social","pos":"adj.","zh":"社会的；社交的"},{"word":"system","pos":"n.","zh":"系统；制度"},{"word":"systemic","pos":"adj.","zh":"系统性的；全身的"},{"word":"systematic","pos":"adj.","zh":"有条理的；系统的"},{"word":"systematize","pos":"v.","zh":"使系统化"}],"senses":[{"no":"01","title":"The whole arrangement of institutions","titleCN":"制度总体安排","definition":"the combined set of schools, courts, clinics, firms and agencies through which a society carries out its daily business","definitionCN":"一个社会借以处理日常事务的学校、法院、诊所、公司与机构的总合","example":"The town's social system ties schools, clinics and unions into one set of written rules.","exampleCN":"这座城镇的社会制度把学校、诊所与工会编进同一套明文规则。","why":"Social names the body of people and system names an arranged whole, so together they name the arranged whole of a society.","whyCN":"social 指人群，system 指有安排的总体，两者合起来就指一个社会有安排的整体。"},{"no":"02","title":"A set of roles and norms","titleCN":"角色与规范体系","definition":"the pattern of expected roles, rights and duties that tells people how to act toward one another","definitionCN":"规定人们如何相互行事的角色、权利与义务的期待模式","example":"In the village social system, every funeral has a named person in charge of each task.","exampleCN":"在这个村庄的社会系统里，每场葬礼的每项事务都有指定负责人。","why":"A system is not only buildings; it is also the expectations that assign tasks, which is why the term covers norms as well as offices.","whyCN":"系统不只是建筑，还包括分派任务的期待，因此这个术语既涵盖规范，也涵盖职位。"},{"no":"03","title":"A subsystem such as education","titleCN":"教育等子系统","definition":"one part of the larger arrangement, such as the school system or the health system, considered in its links to the rest","definitionCN":"较大安排中的一个部分，如学校系统或卫生系统，并考虑其与其余部分的连接","example":"The education social system supplied the factories with clerks and foremen.","exampleCN":"教育这一社会子系统为工厂提供了文书与工头。","why":"Large arrangements are studied part by part, so the phrase is used for a subsystem that still counts as social in kind.","whyCN":"庞大的安排常被分部分研究，因此这个说法也用于仍属社会性质的子系统。"},{"no":"04","title":"A pattern of relationships","titleCN":"关系模式","definition":"the regular web of who reports to whom, who marries whom and who helps whom in a community","definitionCN":"一个共同体中谁向谁汇报、谁与谁联姻、谁帮谁的稳定关系网","example":"The social system of the island kept cousins on the same fishing crew.","exampleCN":"岛上的社会系统让表亲们留在同一条渔船上。","why":"Systems theory shifted attention from institutions to relations, and the phrase followed, naming the web rather than the buildings.","whyCN":"系统论把注意力从机构转向关系，这个说法也随之用来指关系网而非建筑。"},{"no":"05","title":"A welfare and redistribution arrangement","titleCN":"福利与再分配安排","definition":"the rules by which a society collects contributions and supports those who cannot work","definitionCN":"一个社会征收分摊并扶助无法工作者的规则","example":"The post-war social system paid pensions to miners who could no longer descend the shaft.","exampleCN":"战后的社会制度向再也不能下井的矿工发放养老金。","why":"When the state took over welfare, the phrase came to name the redistributive part of the arrangement.","whyCN":"当国家接手福利事务，这个说法也用来指安排中的再分配部分。"},{"no":"06","title":"Interdependent parts in systems theory","titleCN":"系统论中的互依部分","definition":"in social theory, a set of parts whose changes force one another to adjust so that the whole stays in balance","definitionCN":"社会理论中，各部分的变化迫使彼此调整、使整体保持平衡的一组部分","example":"Talcott Parsons treated the family and the economy as parts of one social system.","exampleCN":"帕森斯把家庭与经济视为同一个社会系统的组成部分。","why":"Twentieth-century theory gave the phrase a technical reading: parts are defined by their function in keeping the whole going.","whyCN":"二十世纪的理论赋予这个说法一个技术义：部分由其在维持整体运转中的功能来定义。"},{"no":"07","title":"A national order","titleCN":"国家层面的秩序","definition":"the national arrangement of law, government and economy considered as one durable order","definitionCN":"把法律、政府与经济视为一个持久秩序的国家安排","example":"The new constitution tried to build a social system that could outlast the founding generation.","exampleCN":"新宪法试图建立一套能比开国一代更长久的社会制度。","why":"At the largest scale the phrase names a state's durable order, which is the same arrangement seen from the capital rather than from the village.","whyCN":"在最大尺度上，这个短语指一个国家持久的秩序，也就是同一安排从首都而非村庄看去的样貌。"},{"no":"08","title":"The culture of an organization","titleCN":"组织内部的社会系统","definition":"the informal rules, alliances and habits that govern a workplace or school alongside its official chart","definitionCN":"在正式组织图之外支配一个职场或学校的非正式规则、联盟与习惯","example":"The factory's social system decided who was told about the shutdown before the notice went up.","exampleCN":"工厂的社会系统决定了谁在公告贴出前就得知停产消息。","why":"Every organization has an official chart and an unofficial web, and the phrase is borrowed for the second one.","whyCN":"每个组织都有一张正式组织图与一张非正式关系网，这个说法被借来指后者。"}],"etymology":{"intro":{"en":"Social system joins the Latin-derived adjective social with system, from Greek systema 'an organized whole'. The phrase is a modern social-science term. Dates are approximate.","cn":"这个短语由拉丁来源的形容词「社会的」与名词「系统」组合而成，后者来自希腊 systema「有组织的整体」。这个短语是现代社会科学的术语。年代均为约数。"},"items":[{"era":"LATIN SOCIUS","en":"Social goes back to Latin socius 'ally' and socialis 'of alliance'.","cn":"social 可追溯到拉丁 socius「盟友」与 socialis「联盟的」。"},{"era":"GREEK SYSTEMA","en":"Greek systema meant 'a whole made of several parts', from syn- 'together' plus histanai 'to set, to stand'.","cn":"希腊 systema 意为「由若干部分构成的整体」，由 syn-「一起」加 histanai「放置、站立」构成。"},{"era":"ENGLISH SYSTEM","en":"English system entered through Late Latin systema and named an ordered set of parts, later also a method.","cn":"英语 system 经晚期拉丁 systema 进入，指有序的部分组合，后来也指方法。"},{"era":"SOCIAL SCIENCE","en":"The full phrase was developed in nineteenth and twentieth-century sociology to name the ordered whole of institutions and roles.","cn":"这个完整短语在十九与二十世纪的社会学中发展起来，用来指制度与角色的有序整体。"},{"era":"SYSTEMS THEORY","en":"Mid-twentieth-century systems theory narrowed the phrase to interdependent parts defined by their functions.","cn":"二十世纪中期的系统论把这个短语收窄为按功能定义、彼此互依的部分。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest use of the exact phrase is not precisely dated, and the deeper origin of Greek histanai is reconstructed rather than directly attested.","cn":"来源不确定（首见年代）：这个确切短语的最早用例缺乏精确年代，希腊 histanai 的更早来源属重构而非直接书证。"}]},"similar":{"note":{"en":"Group one holds phrases that name a whole arrangement; group two holds terms for one part or for a related idea, and the difference lies in scope.","cn":"第一组是命名整体安排的短语；第二组是命名其中一部分或相近概念的术语，差别在范围。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"social structure","ipa":"/ˈsəʊʃəl ˈstrʌktʃə/","tag":"the skeleton only","definition":"Names the divisions of class, role and group, not the working institutions; system is wider and includes functions.","definitionCN":"只指阶层、角色与群体的划分，不含运转中的机构；system 更宽，含功能。"},{"word":"social order","ipa":"/ˈsəʊʃəl ˈɔːdə/","tag":"stability and peace","definition":"Stresses the maintenance of peace and accepted rules; a system can persist while order breaks down.","definitionCN":"强调和平与公认规则的维持；制度可以存续，而秩序已经崩坏。"},{"word":"social organization","ipa":"/ˈsəʊʃəl ˌɔːɡənaɪˈzeɪʃən/","tag":"how people group themselves","definition":"Names the way people form groups and coordinate; it may describe one body rather than a whole society.","definitionCN":"指人们结成群体并协调的方式，可描述单个团体而非整个社会。"},{"word":"social institution","ipa":"/ˈsəʊʃəl ˌɪnstɪˈtjuːʃən/","tag":"one building block","definition":"One established body such as the family or the court; a system is the assembly of such blocks.","definitionCN":"指家庭或法院这样的单个既定机构；system 是这些板块的装配。"}]},{"heading":"NEAR MEANING","entries":[{"word":"regime","ipa":"/reɪˈʒiːm/","tag":"political rule","definition":"Names a government and its rules, usually with a political tone; it is narrower than social system.","definitionCN":"指一个政府及其规则，通常带政治语气，比社会制度体系窄。"},{"word":"framework","ipa":"/ˈfreɪmwɜːk/","tag":"supporting outline","definition":"A supporting outline of rules or ideas; it need not actually run anything.","definitionCN":"指规则或思想的支撑框架，不一定真的在运转。"},{"word":"apparatus","ipa":"/ˌæpəˈreɪtəs/","tag":"machinery of the state","definition":"The machinery of officials and agencies; it stresses operation rather than norms.","definitionCN":"指官员与机构的机器，强调运作而非规范。"},{"word":"ecology","ipa":"/ɪˈkɒlədʒi/","tag":"relations with environment","definition":"The study of organisms and their surroundings; it parallels the system idea but not the social content.","definitionCN":"研究生物与环境的关系；与系统思路相似，但不含社会内容。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Social plus system: a body of people plus an arranged whole gives the ordered whole of a society.","cn":"social 加 system：人群加有安排的总体，得到社会的有序整体。"},{"en":"Fixed phrases mark the scope: traditional social system, colonial social system, social system theory.","cn":"固定搭配标出范围：传统社会制度、殖民时期的社会制度、社会系统理论。"},{"en":"The family runs social, society, systemic, systematic and systematize.","cn":"同族词包括 social、society、systemic、systematic 与 systematize。"},{"en":"Greek systema is built from syn- 'together' and histanai 'to stand', which is why a system is parts standing together.","cn":"希腊 systema 由 syn-「一起」与 histanai「站立」构成，因此系统就是共同站立的部分。"},{"en":"Sociologists distinguish the system from order: a system can keep running after the peace of an order is gone.","cn":"社会学家区分制度与秩序：秩序崩坏后，制度仍可能继续运转。"}],"abstract":[{"en":"Picture a town where every office has a hatch and every hatch opens onto another.","cn":"想象一座城镇，每个办公室都有窗口，而每个窗口都通向另一个。"},{"en":"Picture a clock whose wheels are useless alone but keep time when meshed.","cn":"想象一座钟，齿轮单独无用，咬合起来却能报时。"},{"en":"Picture an unwritten seating plan that everyone follows at a wedding.","cn":"想象一场婚礼上人人遵守、却没人写下的座次安排。"}]},"examples":[{"en":"The reform aimed at the social system rather than at any single ministry.","cn":"这项改革针对的是社会制度，而非某一个部委。"},{"en":"Parsons asked how the parts of a social system kept one another in balance.","cn":"帕森斯追问社会系统的各部分如何彼此维持平衡。"},{"en":"The school's social system rewarded silence more than questions.","cn":"这所学校的社会系统奖励沉默多于提问。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「social（社会的）+ system（系统）」——社会各部门接成一套系统 → 社会制度体系","word":"social system"},"root":"social 来自拉丁 socius「盟友」与 socialis「联盟的」；system 经晚期拉丁 systema 来自希腊 systema「由若干部分构成的整体」，由 syn-「一起」与 histanai「站立」构成。该短语为现代社会科学的合成术语，最早书证年代不确定。","sensesIntro":{"en":"Eight senses move from the whole arrangement to its parts and back: institutions, roles, subsystems, relationship webs, welfare rules, systems theory, national order and organizational culture.","cn":"八个义项从整体安排走向各部分再返回：制度、角色、子系统、关系网、福利规则、系统论、国家秩序与组织文化。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of offices whose hatches all open onto one another, so business can pass along the line.","cn":"核心意象：一排办公室的窗口彼此相通，事务可以沿着这条线传递。"},"chain":["SOCIETY","SYSTEM","INSTITUTIONS","ROLES","SUBSYSTEMS","ORGANIC WEB"],"branches":[{"senses":"01","en":"WHOLE ARRANGEMENT: the phrase first names the assembled institutions of a society.","cn":"整体安排：这个短语首先指一个社会装配起来的机构整体。"},{"senses":"02","en":"ROLES: expectations and duties are the invisible half of the arrangement.","cn":"角色：期待与义务是这套安排看不见的一半。"},{"senses":"03 · 07","en":"PARTS AND NATION: a subsystem and a national order are the same structure at two scales.","cn":"部分与国家：子系统与国家秩序是同一结构在两个尺度上。"},{"senses":"04 · 06","en":"RELATIONS: systems theory turns the focus from buildings to the web between people.","cn":"关系：系统论把焦点从建筑转向人与人之间的网。"},{"senses":"05 · 08","en":"REDISTRIBUTION AND CULTURE: welfare rules and office habits are the formal and informal edges of the same system.","cn":"再分配与文化：福利规则与办公室习惯是同一系统的正式与非正式边缘。"}]},"affixes":{"intro":{"en":"The phrase combines a Latin-derived adjective with a Greek-derived noun, and both halves bring their own derived words.","cn":"这个短语把拉丁来源的形容词与希腊来源的名词组合起来，两半各自带来派生词。"},"latinIntro":{"en":"Socialis supplies 'of society'; Greek systema supplies 'organized whole'; English added system and systemic.","cn":"socialis 提供「社会的」；希腊 systema 提供「有组织的整体」；英语又造出 system 与 systemic。"},"items":[{"word":"social","structure":"socius + -alis","meaning":"of society or alliance","meaningCN":"社会的；结伴的","example":"Social roles differ by town.","exampleCN":"社会角色因城镇而异。"},{"word":"system","structure":"Greek systema (organized whole)","meaning":"an ordered whole of parts","meaningCN":"有组织的整体","example":"The system has many parts.","exampleCN":"这个系统有许多部分。"},{"word":"social system","structure":"social + system","meaning":"the ordered whole of a society","meaningCN":"社会制度体系","example":"The social system was reformed.","exampleCN":"社会制度得到改革。"},{"word":"systemic","structure":"system + -ic (relating to)","meaning":"relating to the whole system","meaningCN":"系统性的；整体的","example":"The fault was systemic.","exampleCN":"这个毛病是系统性的。"},{"word":"systematic","structure":"system + -atic (following a method)","meaning":"done according to a method","meaningCN":"有条理的；系统的","example":"They made a systematic review.","exampleCN":"他们做了系统性的审查。"},{"word":"systematize","structure":"systematic + -ize (to make)","meaning":"to arrange into a system","meaningCN":"使系统化","example":"He systematized the records.","exampleCN":"他把记录系统化了。"},{"word":"society","structure":"soci- + -ety","meaning":"a body of associated people","meaningCN":"联合起来的人群","example":"Society changed fast.","exampleCN":"社会变化很快。"},{"word":"socially","structure":"social + -ly","meaning":"in social terms","meaningCN":"在社会层面","example":"The rule was socially enforced.","exampleCN":"这条规则靠社会压力执行。"},{"word":"sociology","structure":"soci- + -logy","meaning":"the study of society","meaningCN":"社会学","example":"Sociology studies systems.","exampleCN":"社会学研究制度体系。"}],"derivatives":[{"word":"systemic","structure":"system + -ic (relating to)","meaning":"relating to the whole system","meaningCN":"系统性的；整体的"},{"word":"systematic","structure":"system + -atic (methodical)","meaning":"done by a fixed method","meaningCN":"有条理的；系统的"},{"word":"systematize","structure":"systematic + -ize (to make)","meaning":"to arrange into a system","meaningCN":"使系统化"}],"latinEntries":[{"word":"socialis","structure":"socialis, -e (adjective)","meaning":"of companionship, allied","meaningCN":"结伴的；联盟的"},{"word":"systema","structure":"systema, systematis (n., Greek loan in Latin)","meaning":"an organized whole","meaningCN":"有组织的整体"},{"word":"societas","structure":"societas, societatis (f., third declension)","meaning":"association, community","meaningCN":"联合；共同体"}]}},{"word":"communal","ipa_uk":"/kəˈmjuːnəl/","ipa_us":"/kəˈmjuːnəl/","definition_zh":"共用的；公共的；社区的；集体生活的；族群之间的","definition_en":"shared by a group of people, especially within a village, commune or close community","core_image":"山村把水井、晒谷场与碾房放在一起，谁家要用先去登记，收益按户分摊，物件归大家而规则写在木牌上","scene":"The village keeps a communal well and a shared drying floor that every household may use.","sceneCN":"此处指「由全村共同拥有、各家都能使用的」（第 1 个义项：由群体共用而非私人独占的）；句意为村里保留一口共用的水井和一块各家都可使用的晒谷场。可辨识物件：石砌水井、晒谷场、木牌登记簿、挑水扁担。","pos":[{"tag":"adj.","zh":"共用的；公共的"},{"tag":"adj.","zh":"社区的；公社的"},{"tag":"adj.","zh":"族群之间的（常用于冲突、暴力等搭配）"}],"collocations":[{"phrase":"communal kitchen","zh":"公用厨房"},{"phrase":"communal land","zh":"公共土地"},{"phrase":"communal living","zh":"集体生活"},{"phrase":"communal conflict","zh":"族群冲突"},{"phrase":"communal garden","zh":"社区花园"},{"phrase":"communal ownership","zh":"共有产权"}],"forms":[{"label":"原级","form":"communal"},{"label":"副词（共同地）","form":"communally"},{"label":"名词（社区；公社）","form":"commune"},{"label":"名词（共同体）","form":"community"},{"label":"名词（共有主义）","form":"communalism"}],"derivatives":[{"word":"community","pos":"n.","zh":"社区；共同体"},{"word":"communally","pos":"adv.","zh":"以共同方式"},{"word":"commune","pos":"n.","zh":"公社；社区"},{"word":"communalism","pos":"n.","zh":"社群主义；教派对立"},{"word":"communion","pos":"n.","zh":"共享；圣餐；交流"}],"senses":[{"no":"01","title":"Shared by a group","titleCN":"由群体共用的","definition":"used or owned by a whole group rather than by one household or person","definitionCN":"由整个群体而非一家或一人使用或拥有","example":"The village keeps a communal well and a shared drying floor that every household may use.","exampleCN":"村里保留一口共用的水井和一块各家都可使用的晒谷场。","why":"Communal comes from Latin communis 'common, shared', so the base sense is simply what is held in common.","whyCN":"communal 来自拉丁 communis「共同的、共享的」，因此基础义就是由大家共同持有的东西。"},{"no":"02","title":"Of a commune or collective","titleCN":"公社或集体的","definition":"relating to a community in which members live and work together and hold property in common","definitionCN":"与成员共同生活、共同劳动并共有财产的共同体有关","example":"The communal farm divided the harvest by household need rather than by plot.","exampleCN":"这个集体农场按各家需要而非按地块分配收成。","why":"The commune is the most complete form of sharing, so the adjective took on this collective-living sense.","whyCN":"公社是共享最彻底的形式，因此这个形容词带上集体生活的意思。"},{"no":"03","title":"Of common land","titleCN":"公共土地的","definition":"relating to land that a village holds for common use, such as grazing or wood gathering","definitionCN":"与村庄留作共同使用的土地有关，如放牧或拾柴","example":"Communal grazing kept the hill open long after the great estates were fenced.","exampleCN":"在大庄园被圈起很久之后，公共放牧仍让这座山保持开放。","why":"Land law inherited the word for shared fields, and the sense survives in modern property disputes.","whyCN":"土地法继承了指共有田地的词，这一义仍见于现代产权纠纷。"},{"no":"04","title":"Of shared duties","titleCN":"共同承担的","definition":"describing work or cost that members divide among themselves instead of hiring others","definitionCN":"描述由成员自行分担、而非雇人完成的工作或费用","example":"The communal repair of the bridge began before the council answered the letter.","exampleCN":"议会对来信作出答复之前，村民已开始共同修桥。","why":"If property is shared, upkeep is shared too, so the adjective extends from things to obligations.","whyCN":"财产既为共有，维护也须共担，因此这个形容词从物延伸到义务。"},{"no":"05","title":"Between religious or ethnic groups","titleCN":"族群或教派之间的","definition":"relating to relations or violence between communities defined by religion, ethnicity or caste","definitionCN":"与按宗教、族群或种姓划分的群体之间的关系或暴力有关","example":"Communal tension rose after the two neighbourhoods disputed the same festival route.","exampleCN":"两个街区为同一条节庆路线起争执后，族群间的紧张加剧。","why":"In South Asian English the word specializes in relations between religious communities, a narrower political reading.","whyCN":"在南亚英语中，这个词专指宗教共同体之间的关系，是一个更窄的政治读法。"},{"no":"06","title":"Of a shared identity","titleCN":"共同身份的","definition":"describing a sense of belonging that members hold together rather than as private feeling","definitionCN":"描述成员共同持有、而非私人感受的归属感","example":"A communal memory of the flood held the scattered families together.","exampleCN":"对那场洪水共同的记忆把散居的各家维系在一起。","why":"Memory and identity can be held in common, so the adjective also names what a group feels as one.","whyCN":"记忆与身份可以为众人共有，因此这个形容词也指群体共同感受的东西。"},{"no":"07","title":"Of common ownership","titleCN":"共有产权的","definition":"describing property whose title belongs to a group, with rules for how members may use or transfer it","definitionCN":"描述产权归群体所有、并规定成员如何使用或转让的财产","example":"The apartment block has a communal roof that no single owner may sell.","exampleCN":"这栋公寓有一块共有屋顶，任何单个业主都不能出售。","why":"Property law separates the title from the use: a roof may be used by all and owned by none alone, which is the legal form of sharing.","whyCN":"物权法把产权与使用分开：屋顶可众人使用，却无人独占，这就是共享的法律形态。"},{"no":"08","title":"Of shared facilities","titleCN":"共享设施的","definition":"describing rooms or equipment provided for everyone in a building or settlement","definitionCN":"描述为楼内或聚落内所有人提供的房间或设备","example":"The communal kitchen on the ground floor is booked by a rota.","exampleCN":"底楼的公用厨房按轮值表预订。","why":"Modern housing revived the old word for facilities that no one owns alone.","whyCN":"现代住房让这个旧词重新用于无人独占的设施。"}],"etymology":{"intro":{"en":"Communal comes from Late Latin communalis, from Latin communis 'common, shared', through French. Its base sense is shared use, with later political and ethnic extensions. Dates are approximate.","cn":"communal 经法语来自晚期拉丁 communalis，其词根为拉丁 communis「共同的、共享的」。基础义是共用，后来延伸出政治与族群两类用法。年代均为约数。"},"items":[{"era":"LATIN COMMUNIS","en":"Communis meant 'common, shared, public'. It is traditionally analysed as com- 'together' plus munus 'service, duty, gift', though that analysis is a hypothesis.","cn":"communis 意为「共同的、共享的、公共的」。传统上把它分析为 com-「一起」加 munus「服务、义务、赠礼」，但这一分析属于假说。"},{"era":"LATIN COMMUNALIS","en":"Late Latin communalis meant 'of a community or of common use', formed from communis with the relational suffix -alis.","cn":"晚期拉丁 communalis 意为「共同体的或共用的」，由 communis 加关系词尾 -alis 构成。"},{"era":"FRENCH AND ENGLISH","en":"The adjective reached English through French and first described shared fields, shared meals and common duties.","cn":"这个形容词经法语进入英语，最初描述共有田地、共餐与共同义务。"},{"era":"POLITICAL SENSE","en":"In the nineteenth century communal was applied to communes and to collective property, giving it a political edge.","cn":"到十九世纪，communal 被用于公社与集体财产，带上政治色彩。"},{"era":"SOUTH ASIAN SENSE","en":"In South Asian English the word specialized to relations between religious communities, including conflict and tension.","cn":"在南亚英语中，这个词专指宗教共同体之间的关系，包括冲突与紧张。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the derivation of communis from com- plus munus is widely repeated but not proven, and the older origin of munus is itself unsettled.","cn":"来源不确定（更深词源）：把 communis 分析为 com- 加 munus 的说法流传甚广，却未获证明，而 munus 的更早来源本身也无定论。"}]},"similar":{"note":{"en":"Group one holds words built on the same common root; group two holds adjectives for what is shared or public, each with a different scope.","cn":"第一组是同出「共同」词根的词；第二组是表示共享或公共的形容词，范围各不相同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"commune","ipa":"/ˈkɒmjuːn/","tag":"the community itself","definition":"A noun for a community that shares work and property; communal is the adjective describing such sharing.","definitionCN":"指共同劳动并共有财产的共同体名词；communal 是描述这种共享的形容词。"},{"word":"community","ipa":"/kəˈmjuːnəti/","tag":"the people, not the property","definition":"Names a body of people sharing a place or interest, without saying that anything is owned in common.","definitionCN":"指共享地点或利益的人群，并不表示财产共有。"},{"word":"common","ipa":"/ˈkɒmən/","tag":"ordinary or shared","definition":"Means shared but also ordinary or frequent; communal is narrower and implies group ownership or group use.","definitionCN":"既指共享，也指普通或常见；communal 更窄，暗示群体所有或群体使用。"},{"word":"communalism","ipa":"/kəˈmjuːnəlɪzəm/","tag":"the doctrine or tension","definition":"Names either a doctrine of communal organization or politics built on religious community identity.","definitionCN":"指共同体组织的学说，或建立在宗教共同体身份上的政治。"}]},{"heading":"NEAR MEANING","entries":[{"word":"shared","ipa":"/ʃeəd/","tag":"the plain word","definition":"The everyday adjective for something used by more than one person; it says nothing about ownership.","definitionCN":"指由不止一人使用的日常形容词，不涉及所有权。"},{"word":"collective","ipa":"/kəˈlektɪv/","tag":"group as one owner","definition":"Means held or run by a group as a single unit, often in economic or political writing.","definitionCN":"指由群体作为单一单位持有或经营，常用于经济或政治论述。"},{"word":"public","ipa":"/ˈpʌblɪk/","tag":"open to all or state-run","definition":"Relates to the state or to open access; communal usually means a smaller group's common property.","definitionCN":"与国家或公开性有关；communal 通常指较小群体的共同财产。"},{"word":"cooperative","ipa":"/kəʊˈɒpərətɪv/","tag":"an organized enterprise","definition":"Names an enterprise owned by its members; it is an organizational form rather than a general adjective.","definitionCN":"指由成员所有的企业，是一种组织形式，而非一般形容词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin communis 'shared' plus -alis: the adjective of what a group holds in common.","cn":"拉丁 communis「共享的」加 -alis：指群体共同持有之物的形容词。"},{"en":"Fixed phrases mark the sense: communal kitchen, communal land, communal living, communal conflict.","cn":"固定搭配标出词义：公用厨房、公共土地、集体生活、族群冲突。"},{"en":"The family runs commune, community, communally, communalism and communion.","cn":"同族词包括 commune、community、communally、communalism 与 communion。"},{"en":"The word splits by object: things are shared, duties are shared, and in South Asia tensions are between communities.","cn":"这个词按对象分流：物件可共用，义务可共担，而在南亚紧张发生在共同体之间。"},{"en":"It contrasts with private: the same well is private for a household and communal for a village.","cn":"它与「私人」相对：同一口水井对一户是私产，对全村则是共用。"}],"abstract":[{"en":"Picture one well with many buckets, each household waiting its turn.","cn":"想象一口井前摆着许多水桶，各家依次等候。"},{"en":"Picture a roof that no single owner can carry away.","cn":"想象一块没有任何单个业主能搬走的屋顶。"},{"en":"Picture a memory told at every funeral until it belongs to everyone.","cn":"想象一段在每场葬礼上被讲述、最终属于所有人的记忆。"}]},"examples":[{"en":"The communal garden is watered by whoever is on the rota that week.","cn":"社区花园由当周轮值的人浇水。"},{"en":"Communal land above the village is protected from sale.","cn":"村子上方的公共土地受保护，不得出售。"},{"en":"The report traced the origins of communal tension to a dispute over the festival route.","cn":"报告把族群紧张的起因追溯到一场节庆路线之争。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「common（共同）+ al（的）」——大家共同的 → 共用的、社区的","word":"communal"},"root":"communal 经法语来自晚期拉丁 communalis，词根为拉丁 communis「共同的、共享的」；communis 由 com- 加 munus 的分析属假说，munus 更深来源不确定。","sensesIntro":{"en":"Eight senses keep one idea of holding in common: shared goods, collective living, common land, shared duties, group tension, shared memory, common title and shared rooms.","cn":"八个义项围绕同一个「共同持有」的观念展开：共用物品、集体生活、公共土地、共同义务、群体紧张、共同记忆、共有产权与共享房间。"},"semanticMap":{"core":{"en":"CORE IMAGE: one well with many buckets, each household waiting its turn.","cn":"核心意象：一口井前摆着许多水桶，各家依次等候。"},"chain":["COMMON","SHARED USE","COLLECTIVE LIVING","COMMON LAND","SHARED DUTY","GROUP BOUNDARY"],"branches":[{"senses":"01 · 08","en":"SHARED USE: a well and a kitchen are the plainest cases of things held in common.","cn":"共用：水井与厨房是共同持有之物最朴素的例子。"},{"senses":"02","en":"COLLECTIVE LIVING: the commune extends sharing from objects to the whole household economy.","cn":"集体生活：公社把共享从物件扩展到整个家庭经济。"},{"senses":"03 · 07","en":"LAND AND TITLE: common land and common title are the legal shape of the same idea.","cn":"土地与产权：公共土地与共有产权是同一观念的法律形态。"},{"senses":"04 · 06","en":"DUTY AND MEMORY: what a group shares includes obligations and remembered pasts.","cn":"义务与记忆：一个群体所共享的还包括义务与共同的过去。"},{"senses":"05","en":"GROUP BOUNDARY: when 'community' hardens into religious lines, sharing turns into tension.","cn":"群体边界：当「共同体」硬化为宗教界线，共享就转为紧张。"}]},"affixes":{"intro":{"en":"The adjective is built on the Latin word for 'common', and its derived words branch into community, doctrine and shared practice.","cn":"这个形容词建立在拉丁语「共同」一词上，其派生词分出共同体、学说与共享实践三条线。"},"latinIntro":{"en":"Latin communis and communalis supply the base; English added commune, community, communalism and communion.","cn":"拉丁 communis 与 communalis 提供词基；英语又造出 commune、community、communalism 与 communion。"},"items":[{"word":"com-","structure":"com- (Latin prefix, 'together')","meaning":"together, with","meaningCN":"共同；一起","example":"The prefix suggests holding together.","exampleCN":"这个前缀暗示共同持有。"},{"word":"munus","structure":"munus, muneris (n., 'service, duty, gift')","meaning":"service; duty; gift","meaningCN":"服务；义务；赠礼","example":"The second element is analysed as duty or gift, though the analysis is a hypothesis.","exampleCN":"第二个成分被分析为义务或赠礼，但这一分析属假说。"},{"word":"communal","structure":"communis + -alis","meaning":"of common use","meaningCN":"共用的；公共的","example":"The communal well serves the lane.","exampleCN":"这口公用井供整条巷子使用。"},{"word":"commune","structure":"communis + French form","meaning":"a community sharing work and property","meaningCN":"共同劳动并共有财产的共同体","example":"The commune shared the harvest.","exampleCN":"公社共同分配收成。"},{"word":"community","structure":"communis + -ity (state)","meaning":"a body sharing a place or interest","meaningCN":"共享地点或利益的群体","example":"The community met on Sunday.","exampleCN":"社区在星期天聚会。"},{"word":"communally","structure":"communal + -ly","meaning":"in a shared way","meaningCN":"以共同方式","example":"The land was communally held.","exampleCN":"这块土地由众人共同持有。"},{"word":"communalism","structure":"communal + -ism (doctrine)","meaning":"organization by community, or community-based politics","meaningCN":"共同体主义；以教派共同体为基础的政治","example":"Communalism shaped the local vote.","exampleCN":"教派共同体政治影响了地方选举。"},{"word":"communion","structure":"communis + -ion (sharing)","meaning":"shared participation","meaningCN":"共享；共同参与","example":"Communion means sharing in common.","exampleCN":"communion 意为共同分享。"},{"word":"common","structure":"communis (through French)","meaning":"shared or ordinary","meaningCN":"共同的；普通的","example":"They share a common gate.","exampleCN":"他们共用一扇大门。"}],"derivatives":[{"word":"community","structure":"communis + -ity (state)","meaning":"a body sharing a place or interest","meaningCN":"社区；共同体"},{"word":"communally","structure":"communal + -ly (adverbial)","meaning":"in a shared way","meaningCN":"以共同方式"},{"word":"communalism","structure":"communal + -ism (doctrine)","meaning":"community-based organization or politics","meaningCN":"共同体主义；教派共同体政治"}],"latinEntries":[{"word":"communis","structure":"communis, -e (adjective)","meaning":"common, shared","meaningCN":"共同的；共享的"},{"word":"communalis","structure":"communalis, -e (adjective, Late Latin)","meaning":"of a community, common","meaningCN":"共同体的；共用的"},{"word":"communio","structure":"communio, communionis (f., third declension)","meaning":"sharing, fellowship","meaningCN":"共享；团契"}]}},{"word":"demographic change","ipa_uk":"/dɪˈmɒɡræfɪk tʃeɪndʒ/","ipa_us":"/dɪˈmɑːɡræfɪk tʃeɪndʒ/","definition_zh":"人口结构变化；出生、死亡与迁移带来的年龄、家庭与地区分布变动","definition_en":"a shift over time in the size, age, distribution or composition of a population","core_image":"海边小城的年轻人外出打工，学校合并、产科关闭，老年人口比例逐年上升，统计图上的曲线明显转向","scene":"The shrinking schools and rising median age are signs of rapid demographic change in the coastal town.","sceneCN":"此处指「人口年龄与家庭结构在较短时间内明显改变」（第 1 个义项：人口构成随时间发生的整体变动）；句意为学校缩减与年龄中位数上升，是这座海边小城人口结构快速变化的迹象。可辨识物件：空荡的教室、合并的校牌、关闭的产科门口、统计折线图。","pos":[{"tag":"n.","zh":"人口结构变化（可数或不可数）"},{"tag":"n.","zh":"人口变动过程（统计与政策语境）"}],"collocations":[{"phrase":"rapid demographic change","zh":"快速的人口结构变化"},{"phrase":"demographic change in rural areas","zh":"农村地区的人口变化"},{"phrase":"the pace of demographic change","zh":"人口变化的速度"},{"phrase":"respond to demographic change","zh":"应对人口变化"},{"phrase":"demographic change and aging","zh":"人口变化与老龄化"},{"phrase":"measure demographic change","zh":"测量人口变化"}],"forms":[{"label":"单数","form":"demographic change"},{"label":"复数（多类变化）","form":"demographic changes"},{"label":"形容词（人口的）","form":"demographic"},{"label":"名词（人口学）","form":"demography"},{"label":"名词（人口统计资料）","form":"demographics"}],"derivatives":[{"word":"demography","pos":"n.","zh":"人口学"},{"word":"demographic","pos":"adj./n.","zh":"人口的；人口统计资料"},{"word":"demographer","pos":"n.","zh":"人口学家"},{"word":"demographically","pos":"adv.","zh":"从人口统计角度"},{"word":"change","pos":"n./v.","zh":"变化；改变"}],"senses":[{"no":"01","title":"A shift in population composition","titleCN":"人口构成的整体变动","definition":"a change over time in the size, age structure or make-up of a population","definitionCN":"一段时间内人口规模、年龄结构或构成成分的变化","example":"The shrinking schools and rising median age are signs of rapid demographic change in the coastal town.","exampleCN":"学校缩减与年龄中位数上升，是这座海边小城人口结构快速变化的迹象。","why":"Demographic comes from Greek demos 'people' plus graphein 'to write', so demographic change is literally a change in what is written down about a people.","whyCN":"demographic 来自希腊 demos「人民」加 graphein「书写」，因此这个短语字面就是「关于人群的记述发生了变化」。"},{"no":"02","title":"A shift in births and deaths","titleCN":"出生与死亡结构的变化","definition":"a change in birth rates, death rates or life expectancy that alters the balance of a population","definitionCN":"出生率、死亡率或预期寿命的变化，改变了一个人口的平衡","example":"Falling births and longer lives drove demographic change across the whole province.","exampleCN":"出生减少与寿命延长推动了全省的人口变化。","why":"The field began by counting births and deaths, so the phrase first named the change in those two rates.","whyCN":"这门学科最初统计出生与死亡，因此这个短语首先指这两项比率的变化。"},{"no":"03","title":"A shift caused by migration","titleCN":"由迁移引起的变化","definition":"a change produced by people moving into or out of an area rather than by natural increase alone","definitionCN":"由人口迁入或迁出而非仅由自然增长造成的变化","example":"The departure of young workers produced a demographic change that no birth policy could reverse.","exampleCN":"年轻工人的外流造成了一种任何生育政策都无法逆转的人口变化。","why":"Migration changes who lives where, so it became one of the standard engines listed under the phrase.","whyCN":"迁移改变谁住在哪里，因此成为这一短语下列举的标准动因之一。"},{"no":"04","title":"Population aging","titleCN":"人口老龄化","definition":"the part of the shift in which the share of older people rises and the share of children falls","definitionCN":"人口变化中老年人口比例上升、儿童比例下降的那一部分","example":"Demographic change in the town showed up first as a shortage of primary pupils.","exampleCN":"镇上的人口变化最早表现为小学生源不足。","why":"Aging is the most visible result of long-term changes in births and deaths, and it is often named by the same phrase.","whyCN":"老龄化是出生与死亡长期变化最可见的结果，因此常被同一短语概括。"},{"no":"05","title":"A shift in household structure","titleCN":"家庭结构的变化","definition":"a change in household size and type, such as smaller families, single households or later marriage","definitionCN":"家庭规模与类型的变化，如家庭变小、单人户增多或婚龄推迟","example":"Demographic change reduced the average household to two people within a generation.","exampleCN":"人口变化在一代人的时间里把平均家庭规模降到两人。","why":"Counting people also means counting how they live together, so the phrase extends from individuals to households.","whyCN":"清点人口也意味着清点他们如何共同生活，因此这个短语从个人延伸到家庭。"},{"no":"06","title":"A policy challenge","titleCN":"作为政策挑战的人口变化","definition":"the same shift considered as a problem that governments must plan for in schools, pensions and housing","definitionCN":"把同一变动视为政府必须在学校、养老金与住房上作出规划的问题","example":"The ministry published a plan in response to demographic change along the coast.","exampleCN":"该部发布计划，以应对沿海地区的人口变化。","why":"Politicians borrowed the term because a change in age structure forces decisions about budgets and services.","whyCN":"政治人物借用这个术语，因为年龄结构的变化会迫使预算与服务作出决定。"},{"no":"07","title":"A measurable statistical trend","titleCN":"可测量的统计趋势","definition":"the numerical trend itself, as shown by censuses, birth records and migration figures","definitionCN":"由普查、出生记录与迁移数字显示出来的数量趋势本身","example":"The census chart made three decades of demographic change visible in one line.","exampleCN":"普查图表用一条线把三十年的人口变化显示出来。","why":"The phrase is used for the data series as well as the event, because the trend is what analysts actually measure.","whyCN":"这个短语既指事件，也指数据序列，因为分析者实际测量的正是趋势。"},{"no":"08","title":"Regional variation","titleCN":"地区之间的差异","definition":"the uneven pattern of the shift, with some districts growing while neighbouring ones lose people","definitionCN":"变化在不同地区的不均衡格局，一些区在增长，邻近的区却在流失人口","example":"Demographic change in the capital looked nothing like the change in the hill villages.","exampleCN":"首都的人口变化与山村的人口变化看上去完全不同。","why":"The same national trend hits local labour markets differently, so the phrase also names the uneven map rather than one uniform wave.","whyCN":"同一国家趋势对各地劳动力市场的冲击不同，因此这个短语也指那张不均衡的地图，而非一道均匀的浪。"},{"no":"09","title":"A generational turnover","titleCN":"代际更替","definition":"the replacement of one generation by the next, with different habits, expectations and household forms","definitionCN":"一代人被下一代人替代，并带来习惯、期待与家庭形式的差异","example":"Demographic change in the electorate reshaped the party's promises.","exampleCN":"选民人口的变化重塑了这个政党的承诺。","why":"Turnover is the long-run form of the same shift, so the phrase can name a change of generations rather than of totals.","whyCN":"代际更替是同一变动的长期形态，因此这个短语也可指代际变化而非总量变化。"}],"etymology":{"intro":{"en":"Demographic change joins demographic, from Greek demos 'people' and graphein 'to write', with the English word change, from Latin cambire through Old French. Dates are approximate.","cn":"这个短语由「人口的」与「变化」两个词组合；前者来自希腊 demos「人民」与 graphein「书写」，后者经古法语来自拉丁 cambire。年代均为约数。"},"items":[{"era":"GREEK DEMOS","en":"Demos meant 'the people, the common people', and it supplied the first element of demography.","cn":"demos 意为「人民、平民」，提供人口学的第一个成分。"},{"era":"GREEK GRAPHEIN","en":"Graphein meant 'to write, to draw'. The combining form -graphia named a written description of a subject.","cn":"graphein 意为「书写、描画」，组合成分 -graphia 指对某主题的书面描述。"},{"era":"LATIN CAMBIRE","en":"Change came through Old French from Latin cambire 'to exchange, to barter', which developed the sense 'to become different'.","cn":"change 经古法语来自拉丁 cambire「交换、以物易物」，逐步发展出「变得不同」的意思。"},{"era":"MODERN TERM","en":"Demography as a discipline took shape in the nineteenth century, and demographic change became its standard phrase for shifts in population structure.","cn":"人口学在十九世纪成形，这一短语成为其指人口结构变动的标准说法。"},{"era":"POLICY USE","en":"In the twentieth century the phrase spread into planning, pensions and migration debates, widening beyond the counting office.","cn":"到二十世纪，这个短语扩散到规划、养老金与移民争论，超出统计机构的范围。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest use of the exact phrase is not precisely dated, and the deeper origin of cambire is unsettled.","cn":"来源不确定（首见年代）：这个确切短语的最早用例缺乏精确年代，cambire 的更深来源亦无定论。"}]},"similar":{"note":{"en":"Group one holds terms built on the same population root or the same change word; group two holds terms for related population events and measures.","cn":"第一组是同出「人口」词根或同带「变化」一词的术语；第二组是关于相关人口事件与测量的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"demographic","ipa":"/ˌdeməˈɡræfɪk/","tag":"the adjective","definition":"Means relating to population statistics; the phrase adds the idea of a shift over time.","definitionCN":"意为与人口统计有关的；短语加上的是随时间变动的意思。"},{"word":"demography","ipa":"/dɪˈmɒɡrəfi/","tag":"the discipline","definition":"The study of populations; demographic change is one of its central objects.","definitionCN":"研究人口的学科；人口变化是它的核心对象之一。"},{"word":"demographics","ipa":"/ˌdeməˈɡræfɪks/","tag":"the data or the groups","definition":"The statistical facts about a population, or the customer groups defined by them.","definitionCN":"关于人口的统计事实，或由此划分的客户群体。"},{"word":"social change","ipa":"/ˈsəʊʃəl tʃeɪndʒ/","tag":"wider than numbers","definition":"Any shift in norms, institutions or behaviour; demographic change is specifically about population structure.","definitionCN":"规范、制度或行为的任何变动；人口变化专指人口结构。"}]},{"heading":"NEAR MEANING","entries":[{"word":"population shift","ipa":"/ˌpɒpjəˈleɪʃən ʃɪft/","tag":"plain wording","definition":"A general phrase for people moving or changing in number; demographic change is the technical equivalent.","definitionCN":"指人口移动或数量变化的一般说法；人口变化是其技术对应语。"},{"word":"migration","ipa":"/maɪˈɡreɪʃən/","tag":"the movement itself","definition":"The act of moving from one place to another; it is one cause of demographic change, not the whole of it.","definitionCN":"指从一个地方迁到另一个地方，是人口变化的一个原因，而非全部。"},{"word":"aging population","ipa":"/ˈeɪdʒɪŋ ˌpɒpjəˈleɪʃən/","tag":"one result","definition":"A population with a rising share of older people; it is often the most visible face of the wider change.","definitionCN":"老年人口比例上升的人口；常是更大变化最可见的一面。"},{"word":"census","ipa":"/ˈsensəs/","tag":"the count","definition":"The official counting of a population; it measures change but is not the change itself.","definitionCN":"官方对人口的清点；它测量变化，但本身不是变化。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek demos 'people' plus graphein 'write' gives demographic: a written account of a people.","cn":"希腊 demos「人民」加 graphein「书写」构成 demographic：对人民的书面记述。"},{"en":"Fixed phrases mark the sense: rapid demographic change, demographic change and aging, the pace of change.","cn":"固定搭配标出词义：快速的人口变化、人口变化与老龄化、变化速度。"},{"en":"The family runs demography, demographic, demographer and demographics.","cn":"同族词包括 demography、demographic、demographer 与 demographics。"},{"en":"Change has its own root, Latin cambire 'to exchange', so the phrase joins two separate word families.","cn":"change 有自己的词根，即拉丁 cambire「交换」，因此这个短语连接了两个不同词族。"},{"en":"The phrase names both the event and the statistical trend that measures it.","cn":"这个短语既指事件，也指测量该事件的统计趋势。"}],"abstract":[{"en":"Picture a school corridor where the desks are removed one row at a time.","cn":"想象一条学校走廊，课桌一排一排被搬走。"},{"en":"Picture a line on a graph bending slowly, then suddenly, across a decade.","cn":"想象图上一条线在十年间先缓后急地弯下去。"},{"en":"Picture a village where the only sound at noon is a radio playing to empty rooms.","cn":"想象一个村庄，正午唯一的声音是唱给空屋子的收音机。"}]},"examples":[{"en":"Housing plans must account for demographic change, not only for current demand.","cn":"住房规划必须考虑人口变化，而不只是当前需求。"},{"en":"The province's demographic change was driven more by migration than by births.","cn":"该省的人口变化更多由迁移而非出生推动。"},{"en":"Researchers used census data to chart two decades of demographic change.","cn":"研究者用普查数据绘制了二十年的人口变化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「demo（人民）+ graphic（书写）+ change（变化）」——人民构成的记录变了 → 人口结构变化","word":"demographic change"},"root":"demographic 来自希腊 demos「人民」与 graphein「书写」；change 经古法语来自拉丁 cambire「交换」。该短语是现代社会科学的合成术语，最早书证年代不确定。","sensesIntro":{"en":"Nine senses follow one shift: the whole composition, births and deaths, migration, aging, households, policy, measurable trend, regional unevenness and generational turnover.","cn":"九个义项跟随着同一场变动：整体构成、出生与死亡、迁移、老龄化、家庭、政策、可测趋势、地区不均衡与代际更替。"},"semanticMap":{"core":{"en":"CORE IMAGE: a graph line bending across a decade while the desks leave a school one row at a time.","cn":"核心意象：十年间一条曲线弯下去，同时学校里的课桌一排排被搬走。"},"chain":["PEOPLE","WRITTEN COUNT","CHANGE","AGE STRUCTURE","HOUSEHOLDS","POLICY PRESSURE"],"branches":[{"senses":"01 · 02","en":"COUNT AND BALANCE: the composition changes because births and deaths change first.","cn":"清点与平衡：构成的变化，先从出生与死亡的变化开始。"},{"senses":"03","en":"MIGRATION: people moving in or out changes the count without any birth or death.","cn":"迁移：人口迁入或迁出，不靠出生死亡也能改变数字。"},{"senses":"04 · 09","en":"AGE AND GENERATION: aging and generational turnover are the same shift seen in cohorts.","cn":"年龄与代际：老龄化与代际更替是同一变动在同代人身上的显现。"},{"senses":"05","en":"HOUSEHOLDS: counting people also counts how they live together.","cn":"家庭：清点人口也在清点他们如何共同生活。"},{"senses":"06 · 07 · 08","en":"MEASURE AND POLICY: the trend is measured, felt unevenly by region, and answered by budgets.","cn":"测量与政策：趋势被测量，在地区间感受不均，并由预算作出回应。"}]},"affixes":{"intro":{"en":"The phrase joins a Greek-derived adjective with a Latin-derived noun, and both halves have their own derived forms.","cn":"这个短语把希腊来源的形容词与拉丁来源的名词组合起来，两半各有派生形式。"},"latinIntro":{"en":"Greek demos and graphein supply demographic; Latin cambire supplies change; English added demography and demographer.","cn":"希腊 demos 与 graphein 提供 demographic；拉丁 cambire 提供 change；英语又造出 demography 与 demographer。"},"items":[{"word":"demo-","structure":"demos (Greek noun, 'the people')","meaning":"people; population","meaningCN":"人民；人口","example":"The first element names the people counted.","exampleCN":"第一个成分指被清点的人民。"},{"word":"-graphic","structure":"graphein (Greek verb, 'to write') + -ikos","meaning":"written, described","meaningCN":"书写的；描述的","example":"The second element names the written record.","exampleCN":"第二个成分指书面记录。"},{"word":"demographic","structure":"demo- + -graphic","meaning":"of population statistics","meaningCN":"人口统计的","example":"Demographic data drove the plan.","exampleCN":"人口统计数据推动了这项计划。"},{"word":"demography","structure":"demo- + -graphy (written description)","meaning":"the study of populations","meaningCN":"人口学","example":"Demography began with parish registers.","exampleCN":"人口学始于教区登记簿。"},{"word":"demographer","structure":"demography + -er (person)","meaning":"a specialist in populations","meaningCN":"人口学家","example":"The demographer projected the decline.","exampleCN":"这位人口学家预测了下降趋势。"},{"word":"demographics","structure":"demographic + -s (plural noun)","meaning":"population data or groups","meaningCN":"人口统计资料；人口群体","example":"The brand studied its demographics.","exampleCN":"这个品牌研究了其客户人口构成。"},{"word":"change","structure":"Latin cambire through Old French","meaning":"to become different","meaningCN":"变化；改变","example":"The town changed quickly.","exampleCN":"这座城镇变化很快。"},{"word":"demographic change","structure":"demographic + change","meaning":"a shift in population structure","meaningCN":"人口结构变化","example":"The phrase names the trend.","exampleCN":"这个短语命名这一趋势。"},{"word":"unchanged","structure":"un- + change + -ed","meaning":"not altered","meaningCN":"未改变的","example":"The birth rate stayed unchanged.","exampleCN":"出生率保持不变。"}],"derivatives":[{"word":"demography","structure":"demo- + -graphy (written description)","meaning":"the study of populations","meaningCN":"人口学"},{"word":"demographer","structure":"demography + -er (person)","meaning":"a specialist in population statistics","meaningCN":"人口学家"},{"word":"demographics","structure":"demographic + -s (plural noun)","meaning":"population data or groups","meaningCN":"人口统计资料；人口群体"}],"latinEntries":[{"word":"demos","structure":"demos, demou (m., Greek noun)","meaning":"the people, the common people","meaningCN":"人民；平民"},{"word":"graphein","structure":"graphein (Greek verb)","meaning":"to write, to draw","meaningCN":"书写；描画"},{"word":"cambire","structure":"cambire, cambivi, cambitum (verb, fourth conjugation)","meaning":"to exchange, to barter","meaningCN":"交换；以物易物"}]}},{"word":"class structure","ipa_uk":"/klɑːs ˈstrʌktʃə/","ipa_us":"/klæs ˈstrʌktʃər/","definition_zh":"阶级结构；一个社会中按财富、职业与地位划分的层次及其相互关系","definition_en":"the layered arrangement of social classes in a society and the relations between those layers","core_image":"老工业城里，厂主、技师与临时工住在不同街区，子女上不同学校，婚姻也很少跨越这几层，地图上的街道就是层次的剖面","scene":"The mill town's class structure was visible in its separate streets, schools and marriage circles.","sceneCN":"此处指「按财富与职业划分、并体现在居住与婚姻中的社会层次」（第 1 个义项：社会分层的整体格局）；句意为这座磨坊城镇的阶级结构，从各自分开的街道、学校与通婚圈子就能看出来。可辨识物件：厂主宅邸、工人排屋、两所校门、教堂婚姻登记簿。","pos":[{"tag":"n.","zh":"阶级结构（社会学意义上的分层格局）"},{"tag":"n.","zh":"某一组织或行业的职级结构"}],"collocations":[{"phrase":"the class structure of a society","zh":"一个社会的阶级结构"},{"phrase":"rigid class structure","zh":"僵化的阶级结构"},{"phrase":"class structure and mobility","zh":"阶级结构与流动"},{"phrase":"industrial class structure","zh":"工业社会的阶级结构"},{"phrase":"analyse class structure","zh":"分析阶级结构"},{"phrase":"class structure in education","zh":"教育中的阶级结构"}],"forms":[{"label":"单数","form":"class structure"},{"label":"复数","form":"class structures"},{"label":"名词（阶级）","form":"class"},{"label":"动词（分类）","form":"classify"},{"label":"名词（结构）","form":"structure"},{"label":"形容词（结构的）","form":"structural"}],"derivatives":[{"word":"class","pos":"n.","zh":"阶级；班级；类别"},{"word":"classify","pos":"v.","zh":"分类"},{"word":"classification","pos":"n.","zh":"分类；类别"},{"word":"structure","pos":"n./v.","zh":"结构；构建"},{"word":"structural","pos":"adj.","zh":"结构的；结构性的"},{"word":"structured","pos":"adj.","zh":"有结构的"}],"senses":[{"no":"01","title":"A layered social hierarchy","titleCN":"分层的社会等级格局","definition":"the overall arrangement of social classes, ranked by wealth, occupation and status, and the relations between them","definitionCN":"按财富、职业与地位排序的各社会阶级的整体安排及其相互关系","example":"The mill town's class structure was visible in its separate streets, schools and marriage circles.","exampleCN":"这座磨坊城镇的阶级结构，从各自分开的街道、学校与通婚圈子就能看出来。","why":"Class names a rank and structure names an arrangement, so together they name the ranked arrangement of a society.","whyCN":"class 指等级，structure 指安排，两者合起来就指一个社会按等级形成的安排。"},{"no":"02","title":"Occupational grading","titleCN":"职业等级划分","definition":"the ranking of jobs into groups with different pay, autonomy and prestige","definitionCN":"按薪酬、自主性与声望把职业划入不同层级的做法","example":"The class structure of the shipyard ran from engineers to apprentices in four clear steps.","exampleCN":"造船厂的阶级结构从工程师到学徒，分成四级清楚的台阶。","why":"Industrial work put people into visible job grades, and the phrase was used for that ladder before it was used for society as a whole.","whyCN":"工业劳动把人放进看得见的职级，这个短语先用于这种阶梯，后来才用于整个社会。"},{"no":"03","title":"A division by wealth and ownership","titleCN":"按财富与所有权划分","definition":"the split between those who own productive property and those who work for them","definitionCN":"拥有生产性财产者与为其工作者的分野","example":"Class structure in the valley followed the ownership of the mills rather than the skills of the workers.","exampleCN":"山谷里的阶级结构取决于磨坊归谁所有，而非工人的技能。","why":"Marxist analysis made ownership the axis of class, and the phrase came to name the resulting two-sided arrangement.","whyCN":"马克思主义分析把所有权当作阶级的主轴，这个短语便用来指由此形成的两侧格局。"},{"no":"04","title":"Institutional reproduction","titleCN":"制度的再生产","definition":"the way schools, marriage and inheritance pass a person's class position on to the next generation","definitionCN":"学校、婚姻与继承把一个人的阶级位置传给下一代的方式","example":"The class structure survived the reform because the same families still met at the same schools.","exampleCN":"改革之后阶级结构仍然存在，因为同一批家庭仍在同样的学校相遇。","why":"Structure is not only a snapshot; it is also a machine that keeps producing the same layers, which is why the phrase describes durability.","whyCN":"结构不只是快照，也是不断生产同样层次的机器，因此这个短语描述的是持久性。"},{"no":"05","title":"Cultural markers of class","titleCN":"阶级的文化标志","definition":"the tastes, accents, hobbies and manners by which people recognize one another's class","definitionCN":"人们借以辨认彼此阶级的品味、口音、爱好与举止","example":"The class structure showed in which paper each household read on Sunday.","exampleCN":"阶级结构从每家在星期天读哪份报纸就能看出。","why":"Once economic rank is lived out in daily habits, the phrase extends from ownership to taste and speech.","whyCN":"当经济等级在日常习惯中体现出来，这个短语便从所有权延伸到品味与言谈。"},{"no":"06","title":"Mobility between strata","titleCN":"层次之间的流动","definition":"the extent to which people move up or down the layers over a lifetime or across generations","definitionCN":"一个人在一生中或几代人之内沿层次向上或向下移动的程度","example":"Class structure shapes whether a bright child from the terraces can reach the university.","exampleCN":"阶级结构决定一个来自排屋区的聪明孩子能否进入大学。","why":"A structure implies both walls and doors, so the phrase also frames the question of who can move through them.","whyCN":"结构既意味着墙，也意味着门，因此这个短语也框定谁能够穿门而过的问题。"},{"no":"07","title":"The grading inside an organization","titleCN":"组织内部的职级结构","definition":"the formal ladder of ranks, titles and pay bands within a firm or institution","definitionCN":"公司或机构内部由等级、头衔与薪酬区间构成的正式阶梯","example":"The bank's class structure was rewritten when the clerks were given a single grade.","exampleCN":"银行把职员统一为一个职级后，其内部阶级结构被改写。","why":"Organizations borrowed the social term for their own ladders, because a firm also has layers that reproduce themselves.","whyCN":"组织借用了这个社会学术语来指自身的阶梯，因为公司同样有会自我复制的层次。"},{"no":"08","title":"A historically formed order","titleCN":"历史形成的秩序","definition":"the particular class arrangement produced by a country's history of land, industry and law","definitionCN":"由一国的土地、工业与法律历史所造就的特定阶级格局","example":"The class structure of the port grew out of two centuries of dock work and inherited leases.","exampleCN":"这个港口的阶级结构源于两个世纪的码头劳动与继承下来的租约。","why":"The phrase is used historically because layers are not natural kinds but products of particular struggles and laws.","whyCN":"这个短语带有历史性，因为层次并非自然类别，而是特定斗争与法律的产物。"}],"etymology":{"intro":{"en":"Class structure joins class, from Latin classis 'a division or group of citizens', with structure, from Latin structura 'a building, an arrangement', from struere 'to build'. Dates are approximate.","cn":"这个短语由「阶级」与「结构」两个词组合；class 来自拉丁 classis「公民的划分或群体」，structure 来自拉丁 structura「建筑、安排」，其动词为 struere「建造」。年代均为约数。"},"items":[{"era":"LATIN CLASSIS","en":"Classis named a division or rank of citizens, especially a census division in the Roman army and assembly.","cn":"classis 指公民的划分或等级，尤指罗马军队与公民大会中按财产划分的等级。"},{"era":"ENGLISH CLASS","en":"English class first named a group of pupils and later, from the eighteenth century, a social rank.","cn":"英语 class 先指一群学生，到十八世纪之后又指社会等级。"},{"era":"LATIN STRUCTURA","en":"Structura meant 'a building, a construction, an arrangement', from struere 'to pile up, to build'.","cn":"structura 意为「建筑、构造、安排」，来自 struere「堆叠、建造」。"},{"era":"SOCIOLOGICAL TERM","en":"Class structure became a standard phrase in nineteenth and twentieth-century sociology for the durable layering of society.","cn":"这一短语在十九与二十世纪的社会学中成为描述社会持久分层的标准短语。"},{"era":"EXTENDED USE","en":"Firms and schools later borrowed the phrase for their own ladders of rank and pay.","cn":"公司与学校后来借用这个短语指自身的等级与薪酬阶梯。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-Roman origin of classis is unsettled, and any earlier form offered for it is a reconstruction rather than a documented word.","cn":"来源不确定（更深词源）：classis 在罗马以前的来源无定论，凡为其给出的更早形态均属重构，而非有书证的词。"}]},"similar":{"note":{"en":"Group one holds phrases and words built on class or structure; group two holds terms for stratification and rank with a different emphasis.","cn":"第一组是建立在 class 或 structure 之上的短语与单词；第二组是侧重不同的分层与等级术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"social class","ipa":"/ˈsəʊʃəl klɑːs/","tag":"one layer, not the whole","definition":"A single rank within the arrangement; class structure is the whole ladder.","definitionCN":"指安排中的单个等级；阶级结构指整架梯子。"},{"word":"class system","ipa":"/klɑːs ˈsɪstəm/","tag":"the working arrangement","definition":"The rules and institutions that keep classes operating; structure stresses the shape more than the machinery.","definitionCN":"维持阶级运作的规则与制度；structure 更强调形状而非机器。"},{"word":"structure","ipa":"/ˈstrʌktʃə/","tag":"the general noun","definition":"Any arranged whole of parts; with class it narrows to social layering.","definitionCN":"泛指任何部分的安排；与 class 连用则收窄为社会分层。"},{"word":"classification","ipa":"/ˌklæsɪfɪˈkeɪʃən/","tag":"the act of sorting","definition":"The activity of putting things into groups; it is a method, not a social order.","definitionCN":"把事物归入类别的活动，是方法而非社会秩序。"}]},{"heading":"NEAR MEANING","entries":[{"word":"stratification","ipa":"/ˌstrætɪfɪˈkeɪʃən/","tag":"the technical term","definition":"The division of society into ranked strata; it is close to class structure but more neutral in tone.","definitionCN":"把社会划分为排序的层次；与阶级结构接近，但语气更中性。"},{"word":"hierarchy","ipa":"/ˈhaɪərɑːki/","tag":"any ranked order","definition":"A ranking of people or offices by authority; it need not be economic.","definitionCN":"按权威排列的人或职位，不一定涉及经济。"},{"word":"caste system","ipa":"/kɑːst ˈsɪstəm/","tag":"closed by birth","definition":"A hereditary order with sharply closed groups; class structure is usually more open to movement.","definitionCN":"按出生决定、群体边界森严的世袭秩序；阶级结构通常更容许流动。"},{"word":"social order","ipa":"/ˈsəʊʃəl ˈɔːdə/","tag":"stability, not layers","definition":"The maintenance of accepted rules and peace; it says nothing about ranking.","definitionCN":"指公认规则与和平的维持，不涉及等级。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Class from Latin classis 'division' plus structure from struere 'to build': a built arrangement of divisions.","cn":"class 来自拉丁 classis「划分」，structure 来自 struere「建造」：由划分建成的安排。"},{"en":"Fixed phrases mark the scale: rigid class structure, industrial class structure, class structure and mobility.","cn":"固定搭配标出规模：僵化的阶级结构、工业阶级结构、阶级结构与流动。"},{"en":"The family runs class, classify, classification, structure, structural and structured.","cn":"同族词包括 class、classify、classification、structure、structural 与 structured。"},{"en":"The phrase is used both for a whole society and for one firm's ladder of grades.","cn":"这个短语既用于整个社会，也用于一家公司的职级阶梯。"},{"en":"Structure implies both walls and doors, which is why mobility is studied alongside it.","cn":"结构既意味着墙也意味着门，因此流动总与它一起被研究。"}],"abstract":[{"en":"Picture a town map where each street is a rung and each school a gate.","cn":"想象一张城镇地图，每条街是一级台阶，每所学校是一道门。"},{"en":"Picture a building whose floors are reachable only by separate staircases.","cn":"想象一栋楼，各层只能通过彼此分开的楼梯到达。"},{"en":"Picture a wedding guest list that quietly repeats the seating plan of the parents.","cn":"想象一份婚礼宾客名单，悄悄重复了父母的座次表。"}]},"examples":[{"en":"The novel describes a class structure so rigid that a clerk could not marry a mill owner's daughter.","cn":"这部小说描写了一种僵化的阶级结构，职员无法娶厂主之女。"},{"en":"The survey found that class structure still shaped university admissions.","cn":"这项调查发现，阶级结构仍在影响大学录取。"},{"en":"Within the firm, the class structure had five grades and very few doors between them.","cn":"在这家公司内部，职级结构有五级，级与级之间几乎没有门。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「class（阶级）+ structure（结构）」——社会按阶级搭起的层次 → 阶级结构","word":"class structure"},"root":"class 来自拉丁 classis「公民的划分、等级」；structure 来自拉丁 structura「建筑、安排」，动词 struere「建造」。该短语为现代社会学术语，classis 的更早来源不确定。","sensesIntro":{"en":"Eight senses describe one ladder: the whole hierarchy, job grades, ownership, reproduction, taste, mobility, the firm's own ladder and the historical making of the order.","cn":"八个义项描述同一架梯子：整体等级、职业分级、所有权、再生产、品味、流动、公司内部的梯子与秩序的历史形成。"},"semanticMap":{"core":{"en":"CORE IMAGE: a town map where each street is a rung and each school a gate.","cn":"核心意象：一张城镇地图，每条街是一级台阶，每所学校是一道门。"},"chain":["DIVISION","RANK","OWNERSHIP","REPRODUCTION","CULTURE","HISTORICAL ORDER"],"branches":[{"senses":"01 · 02","en":"DIVISION AND RANK: the ladder begins as a ranking of people and of jobs.","cn":"划分与等级：梯子起初是人与其职业的排序。"},{"senses":"03","en":"OWNERSHIP: who owns the mill decides who stands where on the ladder.","cn":"所有权：谁拥有磨坊，决定谁站在梯子的哪一级。"},{"senses":"04 · 06","en":"REPRODUCTION AND MOBILITY: the structure copies itself, and mobility asks whether its doors open.","cn":"再生产与流动：结构自我复制，流动则追问它的门是否打开。"},{"senses":"05","en":"CULTURE: taste and speech make the ladder visible in daily life.","cn":"文化：品味与言谈使梯子在日常生活中可见。"},{"senses":"07 · 08","en":"ORGANIZATION AND HISTORY: a firm's grades and a port's past are the same ladder at smaller and longer scales.","cn":"组织与历史：公司的职级与港口的往昔，是同一梯子在更小与更长的尺度上。"}]},"affixes":{"intro":{"en":"The phrase joins two Latin nouns, one naming a division and one naming a built arrangement; both have large English families.","cn":"这个短语组合了两个拉丁名词，一个指划分，一个指建成的安排；两者在英语中都有庞大的词族。"},"latinIntro":{"en":"Latin classis supplies class and classification; Latin struere and structura supply structure, structural and construct.","cn":"拉丁 classis 提供 class 与 classification；拉丁 struere 与 structura 提供 structure、structural 与 construct。"},"items":[{"word":"class","structure":"classis (Latin noun, 'division, rank')","meaning":"a division or rank","meaningCN":"划分；等级","example":"The word names the layers.","exampleCN":"这个词命名各层次。"},{"word":"structure","structure":"structura (Latin noun, 'a building, arrangement')","meaning":"an arranged whole","meaningCN":"有安排的总体","example":"The word names the shape.","exampleCN":"这个词命名形状。"},{"word":"class structure","structure":"class + structure","meaning":"the ranked arrangement of classes","meaningCN":"阶级结构","example":"The town's class structure was visible.","exampleCN":"这座城镇的阶级结构清晰可见。"},{"word":"classify","structure":"classis + -ficare (to make)","meaning":"to put into classes","meaningCN":"分类","example":"Sociologists classify households.","exampleCN":"社会学家对家庭分类。"},{"word":"classification","structure":"classify + -ation (process)","meaning":"the act of sorting","meaningCN":"分类行为","example":"The classification was revised.","exampleCN":"分类法被修订。"},{"word":"structural","structure":"structure + -al (relating to)","meaning":"of a structure","meaningCN":"结构的","example":"The cause was structural.","exampleCN":"原因是结构性的。"},{"word":"structured","structure":"structure + -ed (having)","meaning":"having a structure","meaningCN":"有结构的","example":"The interview was structured.","exampleCN":"面试是有结构的。"},{"word":"restructure","structure":"re- + structure","meaning":"to arrange again","meaningCN":"重组；重构","example":"The firm restructured its grades.","exampleCN":"公司重组了职级。"},{"word":"classless","structure":"class + -less (without)","meaning":"without class divisions","meaningCN":"无阶级的","example":"The ideal was a classless order.","exampleCN":"理想是无阶级的秩序。"}],"derivatives":[{"word":"classify","structure":"classis + -ficare (to make)","meaning":"to put into classes","meaningCN":"分类"},{"word":"structural","structure":"structure + -al (relating to)","meaning":"of a structure","meaningCN":"结构的；结构性的"},{"word":"restructure","structure":"re- + structure (arrange again)","meaning":"to arrange anew","meaningCN":"重组；重构"}],"latinEntries":[{"word":"classis","structure":"classis, classis (f., third declension)","meaning":"division, rank, fleet","meaningCN":"划分；等级；舰队"},{"word":"structura","structure":"structura, structurae (f., first declension)","meaning":"a building, an arrangement","meaningCN":"建筑；安排"},{"word":"struere","structure":"struere, struxi, structum (verb, third conjugation)","meaning":"to build, to pile up","meaningCN":"建造；堆叠"}]}},{"word":"equity","ipa_uk":"/ˈekwɪti/","ipa_us":"/ˈekwəti/","definition_zh":"公平；公正；股权；权益；资产净值；衡平法","definition_en":"fairness in the way people are treated, or the value of an owner's share in an asset","core_image":"水灾过后，富户能搬进旅馆，穷人只能住体育馆，市议会按实际损失发放补助，努力把起点上的差距补平","scene":"After the flood, the council distributed relief with an eye to equity rather than equal shares.","sceneCN":"此处指「按实际需要与损失分配、以求结果公平」（第 1 个义项：公正对待，而非机械平均）；句意为水灾之后，议会发放救济时看重的是公平，而非每人一份的平均分配。可辨识物件：临时旅馆、体育馆床位、补助登记表、泥水痕迹。","pos":[{"tag":"n.","zh":"公平；公正（不可数）"},{"tag":"n.","zh":"股权；权益（金融、法律）"},{"tag":"n.","zh":"资产净值；所有者权益"},{"tag":"n.","zh":"衡平法（英美法律体系）"}],"collocations":[{"phrase":"equity in education","zh":"教育公平"},{"phrase":"pay equity","zh":"薪酬公平"},{"phrase":"equity stake","zh":"股权"},{"phrase":"home equity","zh":"房屋净值"},{"phrase":"equity and inclusion","zh":"公平与包容"},{"phrase":"court of equity","zh":"衡平法院"}],"forms":[{"label":"不可数（公平义）","form":"equity"},{"label":"可数复数（权益、股份）","form":"equities"},{"label":"形容词（公平的）","form":"equitable"},{"label":"副词（公平地）","form":"equitably"},{"label":"反义名词（不公平）","form":"inequity"}],"derivatives":[{"word":"equitable","pos":"adj.","zh":"公平的；公正的"},{"word":"equitably","pos":"adv.","zh":"公平地"},{"word":"inequity","pos":"n.","zh":"不公平；不平等"},{"word":"inequitable","pos":"adj.","zh":"不公平的"},{"word":"equal","pos":"adj./n.","zh":"平等的；相等的人或物"},{"word":"equality","pos":"n.","zh":"平等"}],"senses":[{"no":"01","title":"Fairness in treatment","titleCN":"公平对待","definition":"the quality of treating people justly, especially by adjusting for differences in need or disadvantage","definitionCN":"公正待人的品质，尤指按需要或不利处境作出调整","example":"After the flood, the council distributed relief with an eye to equity rather than equal shares.","exampleCN":"水灾之后，议会发放救济时看重的是公平，而非每人一份的平均分配。","why":"Equity comes from Latin aequitas 'evenness, fairness', from aequus 'level, even', so the base sense is a level scale rather than an identical portion.","whyCN":"equity 来自拉丁 aequitas「均平、公正」，词根 aequus「平的、相等的」，因此基础义是「把秤放平」，而非「每份一样」。"},{"no":"02","title":"An ownership stake","titleCN":"股权；权益","definition":"a share of ownership in a company or asset, giving a claim on its value","definitionCN":"在公司或资产中的一份所有权，可对其价值提出主张","example":"The founders kept a small equity stake after the second round of funding.","exampleCN":"第二轮融资后，创始人仍保留一小部分股权。","why":"Finance borrowed the word because a fair share of value is literally a share in the asset, so 'fairness' became 'ownership portion'.","whyCN":"金融借用这个词，因为价值中「应得的一份」字面上就是资产中的一份，于是「公平」转为「所有权份额」。"},{"no":"03","title":"Net value of an asset","titleCN":"资产净值","definition":"the value of an asset after all claims against it are subtracted, as in home equity","definitionCN":"扣除全部相关债务后资产的剩余价值，如房屋净值","example":"Their equity in the house grew as the mortgage was paid down.","exampleCN":"随着房贷逐步偿还，他们在这栋房子上的净值增加了。","why":"The accounting sense measures what is truly the owner's, which is the ownership sense reduced to a number.","whyCN":"会计义衡量真正属于所有者的部分，也就是把所有权义化成一个数字。"},{"no":"04","title":"The law of equity","titleCN":"衡平法","definition":"the body of English law developed to soften the strictness of common law and to provide fair remedies","definitionCN":"为缓和普通法的严苛并提供公平救济而形成的英国法律体系","example":"The court of equity granted an injunction where the common law could only award damages.","exampleCN":"衡平法院签发了禁令，而普通法只能判决损害赔偿。","why":"Legal history used the word for fairness itself, and the name stuck to the court that administered it.","whyCN":"法律史直接用「公平」一词来称呼这套制度，名称便固定在执行它的法院上。"},{"no":"05","title":"Equal treatment policy","titleCN":"平等待遇政策","definition":"a policy that aims to remove barriers so that groups can reach the same opportunities","definitionCN":"旨在消除障碍、使不同群体获得相同机会的政策","example":"The university adopted an equity plan for students from the hill villages.","exampleCN":"这所大学为来自山村的学生制定了公平计划。","why":"Modern policy uses equity for the active removal of barriers, as distinct from formal equality of rules.","whyCN":"现代政策用 equity 指主动消除障碍，与规则上的形式平等相区别。"},{"no":"06","title":"Residual claim in finance","titleCN":"金融中的剩余索取权","definition":"the right of shareholders to what remains after all debts and other claims are paid","definitionCN":"在清偿全部债务与其他主张后，股东对剩余部分的权利","example":"Equity holders are paid last, so they carry the greatest risk.","exampleCN":"权益持有人最后受偿，因此承担最大风险。","why":"Because owners are paid last, the finance sense also names the riskiest claim, not just the largest one.","whyCN":"由于所有者最后受偿，金融义也指风险最大的主张，而不只是最大的一份。"},{"no":"07","title":"Justice in distribution","titleCN":"分配正义","definition":"the fairness of how goods, burdens and opportunities are distributed across a society","definitionCN":"商品、负担与机会在一个社会中如何分配的公平性","example":"The report asked whether the tax system produced equity across the income scale.","exampleCN":"报告追问税制是否在收入阶梯上实现了公平。","why":"Political philosophy widened the word from individual fairness to the fairness of a whole distribution.","whyCN":"政治哲学把这个词从个人公平扩展到整个分配的公平。"},{"no":"08","title":"Equitable access in education","titleCN":"教育中的公平机会","definition":"the principle that a person's background should not decide their access to schooling or support","definitionCN":"一个人的出身不应决定其受教育或获得支持的机会这一原则","example":"Equity in admissions meant offering tutoring before the entrance test, not lowering the standard.","exampleCN":"录取公平意味着在入学考试前提供辅导，而不是降低标准。","why":"Schools use the term for support given earlier, because fairness in access is judged by outcomes, not by identical treatment.","whyCN":"学校用这个词指提前给予的支持，因为入学公平由结果衡量，而非由相同对待衡量。"}],"etymology":{"intro":{"en":"Equity comes from Latin aequitas 'evenness, fairness', from aequus 'level, even', through Old French. Its legal and financial senses grew in English. Dates are approximate.","cn":"equity 经古法语来自拉丁 aequitas「均平、公正」，词根 aequus「平的、相等的」。其法律与金融义在英语中发展出来。年代均为约数。"},"items":[{"era":"LATIN AEQUUS","en":"Aequus meant 'level, even, equal'. Its deeper origin is not established, and earlier forms proposed for it are reconstructions.","cn":"aequus 意为「平的、均等的、相等的」。其更深来源未得到证明，凡为其提出的更早形态均属重构。"},{"era":"LATIN AEQUITAS","en":"Aequitas named evenness and fairness, the quality of a level scale. It was also personified as a Roman virtue.","cn":"aequitas 指均平与公正，即秤杆放平的性质，也曾被拟人化为罗马美德。"},{"era":"OLD FRENCH EQUITE","en":"Old French equite carried the word into English, where it first meant fairness of judgment.","cn":"古法语 equite 把这个词带入英语，最初指判断的公正。"},{"era":"LEGAL SENSE","en":"English law developed courts of equity to give remedies that the strict common law could not, and the word became the name of that system.","cn":"英国法发展出衡平法院，以提供严格普通法无法给出的救济，这个词便成为该体系的名称。"},{"era":"FINANCIAL SENSE","en":"From the seventeenth century equity also named the owner's share in a venture, since a fair portion of value is a portion of ownership.","cn":"从十七世纪起，equity 也指所有者在事业中的份额，因为价值中应得的一份就是所有权的一份。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-Latin origin of aequus is unsettled, and any Indo-European form offered for it is a reconstruction rather than a documented word.","cn":"来源不确定（更深词源）：aequus 在拉丁语之前的来源无定论，凡为其给出的印欧形态均属重构，而非有书证的词。"}]},"similar":{"note":{"en":"Group one holds words built on the same level root; group two holds terms about fairness or ownership that answer a different question.","cn":"第一组是同出「均平」词根的词；第二组是关于公平或所有权的说法，回答的是不同问题。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"equality","ipa":"/iˈkwɒləti/","tag":"same amount","definition":"Means identical shares or status; equity asks for fair shares, which may differ.","definitionCN":"指份额或地位相同；equity 要求公平份额，份额可以不同。"},{"word":"equitable","ipa":"/ˈekwɪtəbl/","tag":"the adjective","definition":"Means fair or just; it describes a decision or arrangement, not a financial stake.","definitionCN":"意为公平的、公正的，描述决定或安排，不指金融份额。"},{"word":"inequity","ipa":"/ɪnˈekwəti/","tag":"the negative noun","definition":"Unfairness or unjust difference; it is the opposite of the fairness sense, not of the financial one.","definitionCN":"指不公平或不公正差异，是公平义的反面，而非金融义的反面。"},{"word":"equanimity","ipa":"/ˌekwəˈnɪməti/","tag":"same root, different word","definition":"Calmness of mind, from aequus plus animus 'mind'; it shares the root but has nothing to do with fairness.","definitionCN":"指心境的平静，由 aequus 加 animus「心」构成；同根但与公平无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fairness","ipa":"/ˈfeənəs/","tag":"the plain word","definition":"The everyday noun for just treatment; equity is its formal and legal counterpart.","definitionCN":"指公正对待的日常名词；equity 是其正式与法律对应语。"},{"word":"justice","ipa":"/ˈdʒʌstɪs/","tag":"the wider ideal","definition":"A broader ideal of right order and law; equity often names a corrective within that order.","definitionCN":"指正当秩序与法律的更宽理想；equity 常指该秩序内的矫正。"},{"word":"ownership","ipa":"/ˈəʊnəʃɪp/","tag":"the financial side","definition":"The fact or right of possessing something; equity in finance is a measured share of that right.","definitionCN":"指拥有某物的事实或权利；金融中的 equity 是这一权利的可计量份额。"},{"word":"stake","ipa":"/steɪk/","tag":"a share in a venture","definition":"An interest or share in an enterprise; it is close to the financial sense but less technical.","definitionCN":"指在事业中的利益或份额，接近金融义但较不技术化。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin aequus 'level' gives equity: first a level scale, then a fair share, then an ownership share.","cn":"拉丁 aequus「平的」给出 equity：先指放平的秤，再指公平的一份，再指所有权份额。"},{"en":"Fixed phrases mark the field: pay equity, equity stake, home equity, court of equity.","cn":"固定搭配标出领域：薪酬公平、股权、房屋净值、衡平法院。"},{"en":"The family runs equitable, equitably, inequity, inequitable, equal and equality.","cn":"同族词包括 equitable、equitably、inequity、inequitable、equal 与 equality。"},{"en":"The same root appears in equator, equilibrium and equanimity, all built on the idea of level.","cn":"同一词根见于 equator、equilibrium 与 equanimity，都建立在「平」的观念上。"},{"en":"Finance pays equity last, which is why the word also carries risk.","cn":"金融中权益最后受偿，因此这个词也带着风险。"}],"abstract":[{"en":"Picture a scale adjusted so that the lighter side is not simply outvoted.","cn":"想象一杆秤被调整过，较轻的一边不会因分量小而直接被压过去。"},{"en":"Picture a deed that names who truly owns the house after every loan is counted.","cn":"想象一张契据，数清每笔贷款后写明谁真正拥有这栋房子。"},{"en":"Picture a court that can order someone to stop, not merely to pay.","cn":"想象一个法院能命令某人停手，而不只是让其赔钱。"}]},"examples":[{"en":"The scholarship fund was designed for equity, not for equal awards to every applicant.","cn":"这项奖学金着眼于公平，而非给每位申请者相同金额。"},{"en":"She sold half her equity in the startup to pay for the factory.","cn":"她卖掉初创公司一半股权，用来支付工厂费用。"},{"en":"The ruling came from a court of equity and stopped the eviction.","cn":"这项裁决出自衡平法院，阻止了驱逐。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「equal（相等）+ ity（性质）」——把秤放平 → 公平；自己应得的那一份 → 权益","word":"equity"},"root":"equity 经古法语来自拉丁 aequitas「均平、公正」，词根 aequus「平的、相等的」；aequus 更深来源不确定，凡更早形态均属重构。同根词包括 equal、equality、equator、equilibrium。","sensesIntro":{"en":"Eight senses follow one level scale: fair treatment, an ownership share, net value, the law of fairness, equal-access policy, the residual financial claim, distributive justice and fair access to schooling.","cn":"八个义项沿同一杆秤展开：公平对待、所有权份额、净值、衡平法、平权政策、剩余索取权、分配正义与教育机会公平。"},"semanticMap":{"core":{"en":"CORE IMAGE: a scale adjusted so that the lighter side is heard, not simply outweighed.","cn":"核心意象：一杆被调整过的秤，较轻的一边也能被听见，而不只是被压过去。"},"chain":["LEVEL","FAIR SCALE","FAIR SHARE","OWNERSHIP PORTION","NET VALUE","LEGAL REMEDY"],"branches":[{"senses":"01 · 07","en":"FAIR SCALE: fairness of treatment and fairness of distribution are the same level scale writ large.","cn":"公平的秤：对待公平与分配公平，是同一杆秤放大后的样子。"},{"senses":"02 · 06","en":"OWNERSHIP: a fair share becomes a stake, and the last-paid claim carries the risk.","cn":"所有权：公平的一份变成股份，最后受偿的主张承担风险。"},{"senses":"03","en":"NET VALUE: accounting reduces the stake to the number left after debts.","cn":"净值：会计把股份化约为清偿债务后剩下的数字。"},{"senses":"04","en":"LEGAL REMEDY: the court of fairness can order a stop, not merely a payment.","cn":"法律救济：公平法院能命令停手，而不只是判赔。"},{"senses":"05 · 08","en":"ACCESS: policy removes barriers before the test rather than lowering the standard after it.","cn":"机会：政策在考试前消除障碍，而非在考试后降低标准。"}]},"affixes":{"intro":{"en":"The noun comes from the Latin word for evenness, and its derived adjectives and negatives keep the same root.","cn":"这个名词来自拉丁语表示「均平」的词，其派生形容词与反义词延续同一词根。"},"latinIntro":{"en":"Latin aequus and aequitas supply the root; English built equitable, equitably, inequity and equality on the same stock.","cn":"拉丁 aequus 与 aequitas 提供词根；英语在同一来源上造出 equitable、equitably、inequity 与 equality。"},"items":[{"word":"equ-","structure":"aequus (Latin adjective, 'level, even')","meaning":"level; equal","meaningCN":"平的；相等的","example":"The root supplies the image of a level scale.","exampleCN":"这个词根提供水平秤的意象。"},{"word":"-ity","structure":"-itas (Latin noun ending, 'quality')","meaning":"the quality of","meaningCN":"……的性质","example":"The ending turns the adjective into a noun.","exampleCN":"这个词尾把形容词变成名词。"},{"word":"equity","structure":"aequus + -ity","meaning":"fairness; a fair share","meaningCN":"公平；应得的一份","example":"Equity guided the relief.","exampleCN":"公平原则指导了救济。"},{"word":"equitable","structure":"equity + -able (fit for)","meaning":"fair, just","meaningCN":"公平的；公正的","example":"The division was equitable.","exampleCN":"分配是公平的。"},{"word":"equitably","structure":"equitable + -ly (adverbial)","meaning":"fairly","meaningCN":"公平地","example":"The funds were equitably shared.","exampleCN":"资金被公平分配。"},{"word":"inequity","structure":"in- + equity (not)","meaning":"unfairness","meaningCN":"不公平","example":"The report found inequity in pay.","exampleCN":"报告发现薪酬不公。"},{"word":"equality","structure":"aequus + -ality (state)","meaning":"the state of being equal","meaningCN":"平等","example":"Equality names identical status.","exampleCN":"平等指地位相同。"},{"word":"equator","structure":"aequare (to make level) + -or","meaning":"the level line around the earth","meaningCN":"赤道","example":"The equator divides the globe.","exampleCN":"赤道把地球分开。"},{"word":"equilibrium","structure":"aequus + libra 'balance'","meaning":"a state of balance","meaningCN":"平衡","example":"The market reached equilibrium.","exampleCN":"市场达到平衡。"}],"derivatives":[{"word":"equitable","structure":"equity + -able (fit for)","meaning":"fair, just","meaningCN":"公平的；公正的"},{"word":"equitably","structure":"equitable + -ly (adverbial)","meaning":"in a fair way","meaningCN":"公平地"},{"word":"inequity","structure":"in- + equity (not)","meaning":"unfairness","meaningCN":"不公平；不平等"}],"latinEntries":[{"word":"aequus","structure":"aequus, -a, -um (adjective)","meaning":"level, even, equal","meaningCN":"平的；均等的；相等的"},{"word":"aequitas","structure":"aequitas, aequitatis (f., third declension)","meaning":"evenness, fairness","meaningCN":"均平；公正"},{"word":"aequare","structure":"aequare, aequavi, aequatum (verb, first conjugation)","meaning":"to make level, to equalize","meaningCN":"使平；使相等"}]}},{"word":"discriminatory","ipa_uk":"/dɪˈskrɪmɪnətəri/","ipa_us":"/dɪˈskrɪmɪnətɔːri/","definition_zh":"歧视性的；区别对待的；以不公平方式按群体特征区分人的","definition_en":"treating people unfairly because they belong to a particular group, or making distinctions that produce unequal treatment","core_image":"同样的岗位、同样的简历，只因姓名与口音属于某个群体就被直接刷掉，公司却拿不出与工作相关的理由","scene":"The hiring rule was discriminatory because it screened out equally qualified applicants from one group.","sceneCN":"此处指「按群体身份而非工作能力淘汰应聘者」（第 1 个义项：以不公平方式按群体特征区别对待）；句意为此项招聘规则具有歧视性，因为它把同一群体中同样合格的申请者筛掉了。可辨识物件：两摞相同的简历、面试桌、被划掉的名字、招聘公告。","pos":[{"tag":"adj.","zh":"歧视性的；不公平区别对待的"},{"tag":"adj.","zh":"有区分作用的（较技术化，通常用 discriminative）"}],"collocations":[{"phrase":"discriminatory practice","zh":"歧视性做法"},{"phrase":"discriminatory policy","zh":"歧视性政策"},{"phrase":"discriminatory treatment","zh":"歧视性对待"},{"phrase":"discriminatory hiring","zh":"歧视性招聘"},{"phrase":"discriminatory language","zh":"歧视性语言"},{"phrase":"discriminatory against women","zh":"对女性有歧视的"}],"forms":[{"label":"原级","form":"discriminatory"},{"label":"比较级","form":"more discriminatory"},{"label":"最高级","form":"most discriminatory"},{"label":"动词（区分；歧视）","form":"discriminate"},{"label":"名词（歧视）","form":"discrimination"},{"label":"形容词（有鉴别力的）","form":"discriminating"}],"derivatives":[{"word":"discriminate","pos":"v.","zh":"区分；歧视；区别对待"},{"word":"discrimination","pos":"n.","zh":"歧视；辨别力"},{"word":"discriminating","pos":"adj.","zh":"有鉴别力的"},{"word":"discriminative","pos":"adj.","zh":"有区分作用的"},{"word":"nondiscriminatory","pos":"adj.","zh":"非歧视性的"},{"word":"indiscriminate","pos":"adj.","zh":"不加区分的；滥施的"}],"senses":[{"no":"01","title":"Unfair treatment by group","titleCN":"按群体身份的不公平对待","definition":"treating people worse because of their race, sex, age, religion or other group membership rather than their individual qualities","definitionCN":"因种族、性别、年龄、宗教或其他群体身份而非个人素质而给予较差待遇","example":"The hiring rule was discriminatory because it screened out equally qualified applicants from one group.","exampleCN":"这项招聘规则具有歧视性，因为它把同一群体中同样合格的申请者筛掉了。","why":"Discriminatory is the adjective of discriminate, which means 'to separate, to distinguish'; when the separation is unjust, the word carries the modern condemnatory sense.","whyCN":"discriminatory 是 discriminate 的形容词，后者意为「分开、区分」；当这种区分不公正时，这个词就带上现代的谴责义。"},{"no":"02","title":"Making a distinction","titleCN":"作出区分","definition":"capable of drawing a difference between things, a neutral and rather technical reading","definitionCN":"能够辨别事物之间的差别，这一读法中性且偏技术化","example":"A discriminatory test can tell two similar alloys apart.","exampleCN":"一项有区分力的测试能分辨两种相似的合金。","why":"The neutral sense survives in technical writing, where discrimination means accurate separation rather than prejudice.","whyCN":"中性义保留在技术写作中，那里的 discrimination 指准确区分，而非偏见。"},{"no":"03","title":"Of a rule or policy","titleCN":"政策或规则层面的歧视性","definition":"describing a formal rule whose effect is to exclude one group from a benefit or opportunity","definitionCN":"描述某项正式规则的效果是把某一群体排除在某种利益或机会之外","example":"The zoning rule was discriminatory in effect even though its wording was neutral.","exampleCN":"这项分区规则措辞中立，效果上却具有歧视性。","why":"Modern law looks at effects as well as intentions, so the adjective is applied to rules that produce exclusion indirectly.","whyCN":"现代法律既看意图也看效果，因此这个形容词也用于间接造成排斥的规则。"},{"no":"04","title":"Of differential pricing","titleCN":"差别定价的","definition":"describing prices or terms set differently for groups in a way that is judged unfair","definitionCN":"描述按群体设定不同价格或条件、并被判定不公的做法","example":"Charging the same service more in the poorer district was ruled discriminatory.","exampleCN":"在较贫困地区对同一服务收取更高费用被裁定为歧视性做法。","why":"Price is a form of treatment, so unequal terms can be called discriminatory even without an explicit rule about identity.","whyCN":"价格也是一种对待方式，因此即使没有明文身份规定，不平等的条件也可被称为歧视性。"},{"no":"05","title":"Of biased wording","titleCN":"措辞带偏见的","definition":"describing language that assumes one group is inferior or treats it as the exception","definitionCN":"描述假定某一群体低劣、或将其视为例外的语言","example":"The manual's discriminatory wording described female engineers as unusual.","exampleCN":"这本手册的歧视性措辞把女性工程师写成不寻常的例外。","why":"Language carries judgments, so the adjective extends from acts to the words that shape them.","whyCN":"语言带着判断，因此这个形容词从行为延伸到塑造行为的词语。"},{"no":"06","title":"Of hiring and admission","titleCN":"招聘与录取中的歧视性","definition":"describing selection practices that disadvantage applicants because of group membership","definitionCN":"描述因群体身份而使申请者处于不利地位的选拔做法","example":"The inquiry found discriminatory admission practices in three of the five colleges.","exampleCN":"调查发现五所学院中有三所存在歧视性录取做法。","why":"Selection is where unequal treatment is most easily measured, which is why the word appears so often with hiring and admission.","whyCN":"选拔最容易测量不平等待遇，因此这个词常与招聘、录取连用。"},{"no":"07","title":"Statistical discrimination","titleCN":"统计性歧视","definition":"using group averages as a shortcut to judge an individual, even when the average is accurate","definitionCN":"用群体平均值作为判断个人的捷径，即使该平均值本身准确","example":"Insurers used a discriminatory proxy when they priced policies by postcode alone.","exampleCN":"保险公司仅按邮政编码定价时，使用了一个带歧视性的替代指标。","why":"Economics gave the word a precise reading: a group average can be true and still unjust when applied to one person.","whyCN":"经济学赋予这个词精确读法：群体平均可以真实，用在个人身上仍可能不公。"},{"no":"08","title":"Of intent or motive","titleCN":"主观意图上的歧视","definition":"describing an act done because of prejudice, not merely one that happens to produce an unequal result","definitionCN":"描述因偏见而实施的行为，而不只是碰巧造成不平等结果的行为","example":"The tribunal asked whether the remark showed discriminatory intent or mere carelessness.","exampleCN":"审裁处追问那句话显示的是歧视意图，还是仅仅疏忽。","why":"Intent matters in law and ethics, so the adjective can qualify a motive as well as an outcome.","whyCN":"意图在法律与伦理中很重要，因此这个形容词既可修饰结果，也可修饰动机。"}],"etymology":{"intro":{"en":"Discriminatory is the adjective of discriminate, from Latin discriminare 'to separate, to distinguish', built on discrimen 'a dividing line', from discernere 'to sift apart'. Dates are approximate.","cn":"discriminatory 是 discriminate 的形容词，后者来自拉丁 discriminare「分开、辨别」，其名词 discrimen 意为「分界线」，源于 discernere「筛分开」。年代均为约数。"},"items":[{"era":"LATIN CERNERE","en":"Cernere meant 'to sift, to separate, to decide'. It supplied the core of discernere and discriminare.","cn":"cernere 意为「筛、分开、判定」，是 discernere 与 discriminare 的核心。"},{"era":"LATIN DISCERNERE","en":"Dis- 'apart' plus cernere gave discernere 'to separate, to distinguish, to perceive a difference'.","cn":"dis-「分开」加 cernere 构成 discernere「分开、辨别、看出差别」。"},{"era":"LATIN DISCRIMEN","en":"Discrimen named a dividing line, a decisive moment, or a distinction between things.","cn":"discrimen 指分界线、关键时刻或事物之间的区别。"},{"era":"LATIN DISCRIMINARE","en":"Discriminare meant 'to divide, to distinguish, to set apart'. The English verb discriminate came from it.","cn":"discriminare 意为「划分、辨别、使分离」，英语动词 discriminate 由此而来。"},{"era":"MODERN NEGATIVE SENSE","en":"In the nineteenth and twentieth centuries the verb acquired the strong sense of treating a group unjustly, and the adjective followed.","cn":"到十九与二十世纪，这个动词获得「不公平对待某一群体」的强义，形容词也随之带上该义。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest English use of discriminatory is not precisely dated, and the deeper origin of cernere is unsettled.","cn":"来源不确定（首见年代）：discriminatory 的最早英语用例缺乏精确年代，cernere 的更深来源亦无定论。"}]},"similar":{"note":{"en":"Group one holds words built on the same separating root; group two holds adjectives of unfair treatment with a different emphasis.","cn":"第一组是同出「分开」词根的词；第二组是侧重不同的不公平对待类形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"discriminate","ipa":"/dɪˈskrɪmɪneɪt/","tag":"the verb","definition":"Can mean either to distinguish accurately or to treat a group unfairly; context decides which.","definitionCN":"既可指准确辨别，也可指不公平对待群体，由语境决定。"},{"word":"discrimination","ipa":"/ˌdɪskrɪmɪˈneɪʃən/","tag":"the noun","definition":"The act or practice of unfair distinction, or the ability to make fine distinctions.","definitionCN":"指不公平区分的做法，或精细辨别的能力。"},{"word":"discriminating","ipa":"/dɪˈskrɪmɪneɪtɪŋ/","tag":"good taste","definition":"Usually means showing refined judgment, as in a discriminating reader; it is not the same as discriminatory.","definitionCN":"通常指有精细判断力，如「有鉴别力的读者」，与 discriminatory 不同。"},{"word":"discriminative","ipa":"/dɪˈskrɪmɪnətɪv/","tag":"technical distinction","definition":"Means serving to distinguish, a neutral technical adjective rather than a moral one.","definitionCN":"意为起区分作用的，是中性技术形容词，而非道德评价。"}]},{"heading":"NEAR MEANING","entries":[{"word":"biased","ipa":"/ˈbaɪəst/","tag":"leaning to one side","definition":"Shows a preference that favours one side; it can be unconscious and need not be a formal rule.","definitionCN":"显示偏袒一方，可能无意识，也不一定是正式规则。"},{"word":"prejudiced","ipa":"/prɪˈdʒʌdɪst/","tag":"pre-judged","definition":"Holds an opinion formed before evidence; it names an attitude more than a practice.","definitionCN":"指在证据之前就形成看法，更多指态度而非做法。"},{"word":"unfair","ipa":"/ˌʌnˈfeə/","tag":"the plain word","definition":"The everyday adjective for unequal or unjust treatment; discriminatory adds the group basis.","definitionCN":"指不平等或不公正对待的日常形容词；discriminatory 加上群体依据。"},{"word":"exclusionary","ipa":"/ɪkˈskluːʒənəri/","tag":"shuts people out","definition":"Describes rules or systems that keep people out; it stresses the effect rather than the motive.","definitionCN":"描述把人挡在外的规则或制度，强调效果而非动机。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Dis- 'apart' plus cernere 'to sift': to sift apart, hence to distinguish and, unjustly, to separate people.","cn":"dis-「分开」加 cernere「筛」：把东西筛开，因此指辨别，也指不公正地把人分开。"},{"en":"Fixed phrases mark the field: discriminatory practice, discriminatory hiring, discriminatory language.","cn":"固定搭配标出领域：歧视性做法、歧视性招聘、歧视性语言。"},{"en":"The family runs discriminate, discrimination, discriminating, discriminative and indiscriminate.","cn":"同族词包括 discriminate、discrimination、discriminating、discriminative 与 indiscriminate。"},{"en":"The neutral and the condemnatory senses sit side by side: a discriminatory test versus a discriminatory rule.","cn":"中性义与谴责义并存：有区分力的测试，与歧视性的规则。"},{"en":"Law looks at effects, so a neutral word can still describe a discriminatory outcome.","cn":"法律看效果，因此中性的措辞仍可能描述歧视性结果。"}],"abstract":[{"en":"Picture a sieve that keeps one kind of grain and throws the rest away.","cn":"想象一只筛子，留下一种谷粒，把其余的都扔掉。"},{"en":"Picture two identical envelopes, only one of which reaches the desk.","cn":"想象两个一模一样的信封，只有一个被送到桌上。"},{"en":"Picture a door marked neutral that only opens for certain accents.","cn":"想象一扇标着中立的门，只对某些口音打开。"}]},"examples":[{"en":"The tribunal ruled that the promotion rule was discriminatory against older staff.","cn":"审裁处裁定该晋升规则对年长员工具有歧视性。"},{"en":"Discriminatory pricing meant the same delivery cost more in the poorer district.","cn":"歧视性定价使同一配送在较贫困地区收费更高。"},{"en":"The report found no discriminatory intent, only a careless procedure.","cn":"报告未发现歧视意图，只发现程序草率。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「dis（分开）+ crimin（筛选）+ atory（的）」——把人按群体筛开 → 歧视性的","word":"discriminatory"},"root":"discriminatory 是 discriminate 的形容词；discriminate 来自拉丁 discriminare「分开、辨别」，源于 discrimen「分界线」与 discernere「筛分开」，其核心为 cernere「筛、分开」。cernere 更深来源不确定，最早书证年代亦不确定。","sensesIntro":{"en":"Eight senses follow one act of sifting: unfair group treatment, neutral distinction, exclusionary rules, differential prices, biased wording, hiring practice, statistical shortcuts and guilty intent.","cn":"八个义项沿同一次「筛分」展开：不公平的群体对待、中性的辨别、排斥性规则、差别定价、偏见措辞、招聘做法、统计捷径与有罪意图。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sieve that keeps one kind of grain and throws the rest away.","cn":"核心意象：一只筛子，留下一种谷粒，把其余的都扔掉。"},"chain":["SIFT","SEPARATE","DISTINGUISH","TREAT UNEQUALLY","EXCLUDE","INTENT"],"branches":[{"senses":"01","en":"UNFAIR GROUP TREATMENT: the sifting is applied to people because of group membership.","cn":"不公平的群体对待：筛分被用到人身上，依据是群体身份。"},{"senses":"02","en":"NEUTRAL DISTINCTION: the same root can mean accurate separation with no moral judgment.","cn":"中性辨别：同一词根也可指准确分开，不带道德判断。"},{"senses":"03 · 06","en":"RULES AND HIRING: formal selection is where exclusion becomes measurable.","cn":"规则与招聘：正式选拔是排斥最容易被测量的地方。"},{"senses":"04 · 05","en":"PRICE AND WORDING: unequal terms and biased language are quieter forms of the same sieve.","cn":"价格与措辞：不平等条件与偏见语言是同一只筛子更安静的形式。"},{"senses":"07 · 08","en":"AVERAGES AND INTENT: a true group average can still misjudge a person, and motive decides blame.","cn":"平均值与意图：真实的群体平均仍可能误判个人，而动机决定责任。"}]},"affixes":{"intro":{"en":"The adjective is built on a Latin verb of separating, and its derived forms keep the neutral and the condemnatory readings side by side.","cn":"这个形容词建立在拉丁「分开」动词上，其派生形式同时保留中性义与谴责义。"},"latinIntro":{"en":"Latin cernere, discernere and discriminare supply the root; English added discriminate, discrimination and the negative forms.","cn":"拉丁 cernere、discernere 与 discriminare 提供词根；英语又造出 discriminate、discrimination 与否定形式。"},"items":[{"word":"dis-","structure":"dis- (Latin prefix, 'apart')","meaning":"apart, in different directions","meaningCN":"分开；朝不同方向","example":"The prefix separates the sieve from the grain.","exampleCN":"这个前缀把筛子与谷粒分开。"},{"word":"cern-","structure":"cernere (Latin verb, 'to sift, to separate')","meaning":"to sift; to decide","meaningCN":"筛；分开；判定","example":"The root carries the image of sifting.","exampleCN":"这个词根带着筛分的意象。"},{"word":"discriminate","structure":"discriminare (Latin verb)","meaning":"to distinguish or to treat unequally","meaningCN":"辨别；区别对待","example":"The verb can be neutral or damning.","exampleCN":"这个动词可以是中性，也可以是谴责。"},{"word":"discriminatory","structure":"discriminate + -ory (tending to)","meaning":"tending to treat unfairly","meaningCN":"有歧视倾向的","example":"The rule was discriminatory.","exampleCN":"这条规则具有歧视性。"},{"word":"discrimination","structure":"discriminate + -ation (action)","meaning":"the act of distinguishing or unfair treatment","meaningCN":"辨别；歧视","example":"The law banned discrimination.","exampleCN":"法律禁止歧视。"},{"word":"discriminating","structure":"discriminate + -ing (present participle)","meaning":"showing fine judgment","meaningCN":"有鉴别力的","example":"She has a discriminating eye.","exampleCN":"她有挑剔的眼光。"},{"word":"discriminative","structure":"discriminate + -ive (having the quality)","meaning":"serving to distinguish","meaningCN":"有区分作用的","example":"The test is discriminative.","exampleCN":"这项测试有区分力。"},{"word":"nondiscriminatory","structure":"non- + discriminatory (not)","meaning":"not unfair by group","meaningCN":"非歧视性的","example":"The policy is nondiscriminatory.","exampleCN":"这项政策不带歧视。"},{"word":"indiscriminate","structure":"in- + discriminate (not separated)","meaning":"without distinction, random","meaningCN":"不加区分的；滥施的","example":"The bombing was indiscriminate.","exampleCN":"那次轰炸不分目标。"}],"derivatives":[{"word":"discrimination","structure":"discriminate + -ation (action)","meaning":"unfair distinction or the act of distinguishing","meaningCN":"歧视；辨别"},{"word":"discriminative","structure":"discriminate + -ive (having the quality)","meaning":"serving to distinguish","meaningCN":"有区分作用的"},{"word":"nondiscriminatory","structure":"non- + discriminatory (not)","meaning":"not unfair by group","meaningCN":"非歧视性的"}],"latinEntries":[{"word":"cernere","structure":"cernere, crevi, cretum (verb, third conjugation)","meaning":"to sift, to separate, to decide","meaningCN":"筛；分开；判定"},{"word":"discrimen","structure":"discrimen, discriminis (n., third declension)","meaning":"a dividing line, a distinction","meaningCN":"分界线；区别"},{"word":"discriminare","structure":"discriminare, discriminavi, discriminatum (verb, first conjugation)","meaning":"to divide, to distinguish","meaningCN":"划分；辨别"}]}},{"word":"stereotype","ipa_uk":"/ˈsteriətaɪp/","ipa_us":"/ˈsteriətaɪp/","definition_zh":"刻板印象；对某群体过度简化且固定不变的看法；印刷铅版；套用固定印象","definition_en":"a fixed, oversimplified image of a group that is applied to every member regardless of individual difference","core_image":"外地人以为这座城只有煤矿和灰墙，电视反复播同一个镜头，居民每次解释都要先推翻这块早就铸好的印版","scene":"Visitors arrive with a stereotype of the town as nothing but coal and grey walls.","sceneCN":"此处指「对某地或某群体固定而过度简化的印象」（第 1 个义项：套在每个人身上的固定图像）；句意为来访者带着「这座城只有煤与灰墙」的刻板印象而来。可辨识物件：旅行指南封面、电视画面、煤矿剪影、灰墙街景。","pos":[{"tag":"n.","zh":"刻板印象；固定化的群体图像"},{"tag":"n.","zh":"铅版；印刷用的固定印版"},{"tag":"v.","zh":"对……形成刻板印象；把……固定化"}],"collocations":[{"phrase":"racial stereotype","zh":"种族刻板印象"},{"phrase":"gender stereotype","zh":"性别刻板印象"},{"phrase":"break the stereotype","zh":"打破刻板印象"},{"phrase":"reinforce a stereotype","zh":"强化刻板印象"},{"phrase":"cultural stereotype","zh":"文化刻板印象"},{"phrase":"stereotype threat","zh":"刻板印象威胁"}],"forms":[{"label":"单数","form":"stereotype"},{"label":"复数","form":"stereotypes"},{"label":"过去式","form":"stereotyped"},{"label":"过去分词","form":"stereotyped"},{"label":"现在分词","form":"stereotyping"},{"label":"形容词（刻板化的）","form":"stereotypical"}],"derivatives":[{"word":"stereotypical","pos":"adj.","zh":"刻板化的；类型化的"},{"word":"stereotyped","pos":"adj.","zh":"固定化的；套用刻板印象的"},{"word":"stereotyping","pos":"n.","zh":"刻板化过程"},{"word":"stereotypic","pos":"adj.","zh":"刻板类型的"},{"word":"stereotypically","pos":"adv.","zh":"以刻板方式"}],"senses":[{"no":"01","title":"A fixed group image","titleCN":"固定化的群体图像","definition":"an oversimplified and rigid picture of a group that is applied to all its members","definitionCN":"对某一群体过度简化且僵硬、并套用到全体成员的图像","example":"Visitors arrive with a stereotype of the town as nothing but coal and grey walls.","exampleCN":"来访者带着「这座城只有煤与灰墙」的刻板印象而来。","why":"The word began in printing, where a fixed plate prints the same image again and again; the social sense borrows exactly that repetition.","whyCN":"这个词始于印刷业，固定印版反复印出同一图像；社会义正是借用了这种重复。"},{"no":"02","title":"A printing plate","titleCN":"印刷铅版","definition":"a solid metal printing plate cast from a mould, used to reproduce the same page many times","definitionCN":"由模具浇铸的实心金属印版，用来反复印制同一版面","example":"The printer kept the stereotype in a rack long after the edition sold out.","exampleCN":"那一版售罄很久之后，印刷商仍把铅版存放在架子上。","why":"This is the literal origin: Greek stereos 'solid' plus typos 'impression' named a solid plate.","whyCN":"这是字面来源：希腊 stereos「坚固」加 typos「压印」，指一块坚固的印版。"},{"no":"03","title":"To apply a fixed image","titleCN":"套用固定印象","definition":"to treat a person as if they must match a pre-existing picture of their group","definitionCN":"把一个人当作必然符合其群体既有图像来对待","example":"The presenter stereotyped the village women as patient and passive.","exampleCN":"主持人把村里的女性刻板化为耐心而被动。","why":"The verb was formed from the noun, so to stereotype is to press the same plate onto a new person.","whyCN":"动词由名词构成，因此「刻板化」就是把同一块印版压到新的人身上。"},{"no":"04","title":"A typed character in art","titleCN":"艺术中的类型化角色","definition":"a character or role that repeats a familiar pattern rather than showing an individual","definitionCN":"重复熟悉套路、而非展现个体的角色或类型","example":"The play's generous grandmother is a stereotype rather than a person.","exampleCN":"剧中那位慷慨的祖母是类型化角色，而非一个人物。","why":"Drama borrowed the printing image because a repeated character is like a repeated print.","whyCN":"戏剧借用了印刷意象，因为重复出现的角色就像反复印出的图像。"},{"no":"05","title":"To repeat mechanically","titleCN":"机械重复","definition":"to reproduce something without change or thought, as a plate reproduces an image","definitionCN":"像印版复制图像那样，不加变化或思考地重复某物","example":"The clerk stereotyped the same reply to every complaint.","exampleCN":"那名职员对每一起投诉都机械地重复同一套答复。","why":"The oldest transferred sense is mechanical copying, which survives in phrases about stereotyped replies.","whyCN":"最早的转义是机械复制，这一义仍见于「刻板答复」一类说法。"},{"no":"06","title":"A group schema in psychology","titleCN":"心理学中的群体图式","definition":"a mental shortcut that stores a generalised image of a group and guides quick judgments about its members","definitionCN":"储存某一群体概括图像、并指导对其成员快速判断的心理捷径","example":"Social psychology studies how a stereotype survives even when people meet counter-examples.","exampleCN":"社会心理学研究刻板印象为何在遇到反例后仍然存续。","why":"Psychology adopted the word because a fixed image works like a plate in the mind: it prints the same judgment quickly.","whyCN":"心理学采用这个词，因为固定图像在大脑中像一块印版，快速印出同样的判断。"},{"no":"07","title":"A conventional formula","titleCN":"陈规套语","definition":"a fixed phrase or plot device used without freshness","definitionCN":"缺乏新意、被反复使用的固定语句或情节装置","example":"The speech was a stereotype of every graduation address.","exampleCN":"那篇演讲是每场毕业致辞的套语拼合。","why":"From repeated printing the word came to mean any repeated formula, spoken or written.","whyCN":"由反复印刷，这个词转而指任何被重复的套式，无论口头还是书面。"},{"no":"08","title":"To fix in an unchanging form","titleCN":"使固定不变","definition":"to make something rigid and unchanging, as a solid plate is fixed","definitionCN":"使某事物僵硬不变，如同坚固的印版被固定住","example":"The archive stereotyped the story in one version and lost the others.","exampleCN":"档案馆把这个故事固定成一个版本，其余版本都失传了。","why":"The core image of solidity produced a general sense of freezing something into one form.","whyCN":"「坚固」的核心意象产生出「把某物冻结成一种形态」的一般义。"}],"etymology":{"intro":{"en":"Stereotype joins Greek stereos 'solid' with typos 'a blow, an impression'. It named a solid printing plate before it named a fixed social image. Dates are approximate.","cn":"stereotype 由希腊 stereos「坚固的」与 typos「敲击、压印」组合而成。它先指坚固的印刷版，后指固定的社会图像。年代均为约数。"},"items":[{"era":"GREEK STEREOS","en":"Stereos meant 'solid, firm, three-dimensional'. It supplied the first element of the compound.","cn":"stereos 意为「坚固的、结实的、立体的」，提供复合词的第一个成分。"},{"era":"GREEK TYPOS","en":"Typos meant 'a blow, a mark, an impression', from typtein 'to strike'. It gave the word for a printed impression.","cn":"typos 意为「敲击、印记、压印」，来自 typtein「打、敲」，是表示印刷印记的词。"},{"era":"PRINTING TERM","en":"In the eighteenth century the compound named a solid plate cast from movable type, which printed the same page repeatedly.","cn":"到十八世纪，这个复合词指用活字浇铸的坚固印版，可反复印出同一版面。"},{"era":"SOCIAL SENSE","en":"In the twentieth century the word was extended to a fixed image of a group, especially in discussions of public opinion.","cn":"到二十世纪，这个词被扩展到指对某一群体的固定图像，尤见于舆论讨论。"},{"era":"PSYCHOLOGY","en":"Social psychology made the term technical, naming a mental shortcut that guides judgments about group members.","cn":"社会心理学把这个词术语化，用来指指导群体成员判断的心理捷径。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest English use of the social sense is not precisely dated, and the deeper origin of typtein is unsettled.","cn":"来源不确定（首见年代）：社会义的最早英语用例缺乏精确年代，typtein 的更深来源亦无定论。"}]},"similar":{"note":{"en":"Group one holds words built on the same solid-impression elements; group two holds terms for simplified or repeated images with a different tone.","cn":"第一组是同出「坚固—压印」成分的词；第二组是语气不同的简化或重复图像类说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stereotypical","ipa":"/ˌsteriəˈtɪpɪkəl/","tag":"the adjective","definition":"Describes something that matches a fixed image; stereotype is the image or the act.","definitionCN":"描述符合固定图像的事物；stereotype 是图像或行为。"},{"word":"stereotyped","ipa":"/ˈsteriətaɪpt/","tag":"the participle","definition":"Means already fixed into a standard form; it stresses the result more than the act.","definitionCN":"意为已被固定成标准形态，强调结果多于行为。"},{"word":"stereotyping","ipa":"/ˈsteriətaɪpɪŋ/","tag":"the process","definition":"The ongoing act of applying fixed images to people.","definitionCN":"指持续把固定图像套到人身上的行为。"},{"word":"stereotypic","ipa":"/ˌsteriəˈtɪpɪk/","tag":"technical adjective","definition":"A technical variant used in psychology for behaviour that fits a fixed pattern.","definitionCN":"心理学中使用的技术变体，指符合固定模式的行为。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cliché","ipa":"/kliːˈʃeɪ/","tag":"worn phrase","definition":"A phrase worn thin by overuse; a stereotype may be an image or belief rather than a phrase.","definitionCN":"因过度使用而失去新意的语句；stereotype 可以是图像或信念，而不只是语句。"},{"word":"label","ipa":"/ˈleɪbl/","tag":"a tag","definition":"A short name attached to a person or group; it may be neutral, while a stereotype is usually rigid and generalising.","definitionCN":"贴在人或群体上的短名称，可以中性；刻板印象通常僵硬且概括化。"},{"word":"generalization","ipa":"/ˌdʒenərəlaɪˈzeɪʃən/","tag":"a broad statement","definition":"A statement drawn from some cases; it becomes a stereotype when it is treated as fixed and applied to all.","definitionCN":"由部分案例得出的概括陈述；当它被当作固定并套用到全体时，就成了刻板印象。"},{"word":"preconception","ipa":"/ˌpriːkənˈsepʃən/","tag":"an idea formed earlier","definition":"An opinion formed before evidence; stereotype stresses the fixed group image rather than the timing.","definitionCN":"在证据之前形成的看法；stereotype 更强调固定的群体图像而非形成时间。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek stereos 'solid' plus typos 'impression': a solid plate that prints the same image again and again.","cn":"希腊 stereos「坚固」加 typos「压印」：一块反复印出同一图像的坚固版。"},{"en":"Fixed phrases mark the social sense: racial stereotype, gender stereotype, break the stereotype.","cn":"固定搭配标出社会义：种族刻板印象、性别刻板印象、打破刻板印象。"},{"en":"The family runs stereotypical, stereotyped, stereotyping, stereotypic and stereotypically.","cn":"同族词包括 stereotypical、stereotyped、stereotyping、stereotypic 与 stereotypically。"},{"en":"The printing sense survives in the trade: a stereotype is a plate kept for reprinting.","cn":"印刷义仍留在行业中：铅版是留作重印的印版。"},{"en":"The word moves from a metal plate to a mental plate, which is why the image of repeated printing fits so well.","cn":"这个词从金属版转到心智版，因此反复印刷的意象格外贴切。"}],"abstract":[{"en":"Picture a rubber stamp that puts the same face on every passport photo.","cn":"想象一枚橡皮图章，给每张护照照片盖上同一张脸。"},{"en":"Picture a television that shows one street scene no matter which town you tune to.","cn":"想象一台电视，不论调到哪座城都播同一条街景。"},{"en":"Picture a mould that refuses to cool into any other shape.","cn":"想象一个模具，拒绝冷却成别的形状。"}]},"examples":[{"en":"The film challenged the stereotype that engineers cannot write.","cn":"这部电影挑战了「工程师不会写作」的刻板印象。"},{"en":"She refused to let one bad interview stereotype the whole department.","cn":"她不愿让一次糟糕的面试把整个部门刻板化。"},{"en":"The old stereotype was kept in the print room and reused for the second edition.","cn":"旧铅版被保存在印刷间，第二版时再次使用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「stereo（立体、坚固）+ type（类型、印记）」——一块固定的印版，反复印同一个印象 → 刻板印象","word":"stereotype"},"root":"stereotype 由希腊 stereos「坚固的」与 typos「压印」构成；先指十八世纪的实心印刷铅版，二十世纪扩展为对群体的固定图像。typtein 更深来源不确定，社会义最早书证年代不确定。","sensesIntro":{"en":"Eight senses follow one plate: a fixed group image, the printing plate itself, the act of applying it, a typed role, mechanical repetition, a mental schema, a worn formula and the freezing of a thing into one form.","cn":"八个义项沿同一块印版展开：固定的群体图像、印版本身、套用行为、类型化角色、机械重复、心理图式、陈旧套式与把事物冻结成一种形态。"},"semanticMap":{"core":{"en":"CORE IMAGE: a solid plate that prints the same face on every new sheet.","cn":"核心意象：一块坚固的印版，在每一张新纸上印出同一张脸。"},"chain":["SOLID","IMPRESSION","PRINTING PLATE","REPEATED IMAGE","GROUP IMAGE","MENTAL SHORTCUT"],"branches":[{"senses":"02","en":"PRINTING PLATE: the literal plate is the base from which everything else is borrowed.","cn":"印版：字面的印版是其余义项借用的基础。"},{"senses":"01","en":"FIXED GROUP IMAGE: the plate becomes a rigid picture applied to every member.","cn":"固定的群体图像：印版变成套在每位成员身上的僵硬图像。"},{"senses":"03 · 04","en":"APPLYING AND TYPING: the act of stereotyping and the typed role both press the same plate onto people.","cn":"套用与类型化：刻板化行为与类型化角色，都是把同一印版压到人身上。"},{"senses":"05 · 07","en":"MECHANICAL REPETITION: a repeated reply and a worn formula are the plate running without thought.","cn":"机械重复：重复的答复与陈旧的套式，是不加思考运转的印版。"},{"senses":"06 · 08","en":"MIND AND FIXITY: psychology makes the plate mental, and the last sense names the freezing itself.","cn":"心智与固定：心理学把印版放进心里，最后一个义项则命名「冻结」本身。"}]},"affixes":{"intro":{"en":"The word is a Greek compound that entered English through printing and later moved into social description.","cn":"这个词是希腊复合词，经印刷业进入英语，后来转入社会描述。"},"latinIntro":{"en":"Greek stereos and typos supply both halves; English built the printing term, the verb and the adjective from them.","cn":"希腊 stereos 与 typos 提供两半；英语由此造出印刷术语、动词与形容词。"},"items":[{"word":"stereo-","structure":"stereos (Greek adjective, 'solid, firm')","meaning":"solid; three-dimensional","meaningCN":"坚固的；立体的","example":"The first element names the plate's solidity.","exampleCN":"第一个成分指印版的坚固。"},{"word":"-type","structure":"typos (Greek noun, 'impression, mark')","meaning":"impression; printed mark","meaningCN":"压印；印记","example":"The second element names the impression.","exampleCN":"第二个成分指压出的印记。"},{"word":"stereotype","structure":"stereo- + -type","meaning":"a solid printing plate; a fixed image","meaningCN":"铅版；固定图像","example":"The word moved from plate to person.","exampleCN":"这个词从印版转到人身上。"},{"word":"stereotyped","structure":"stereotype + -ed (past participle)","meaning":"already fixed into a form","meaningCN":"已被固定化的","example":"The reply was stereotyped.","exampleCN":"答复是刻板化的。"},{"word":"stereotyping","structure":"stereotype + -ing (gerund)","meaning":"the act of applying fixed images","meaningCN":"刻板化行为","example":"Stereotyping begins early.","exampleCN":"刻板化很早就开始。"},{"word":"stereotypical","structure":"stereotype + -ical (relating to)","meaning":"matching a fixed image","meaningCN":"刻板化的","example":"The role was stereotypical.","exampleCN":"这个角色是类型化的。"},{"word":"stereotypically","structure":"stereotypical + -ly (adverbial)","meaning":"in a fixed-image way","meaningCN":"以刻板方式","example":"He spoke stereotypically of the village.","exampleCN":"他以刻板方式谈论这个村庄。"},{"word":"stereotypic","structure":"stereotype + -ic (technical adjective)","meaning":"of a fixed pattern","meaningCN":"刻板类型的","example":"The behaviour was stereotypic.","exampleCN":"这种行为是刻板类型的。"},{"word":"typeset","structure":"-type + set (to arrange)","meaning":"to arrange type for printing","meaningCN":"排字","example":"The page was typeset by hand.","exampleCN":"这一页是手工排字的。"}],"derivatives":[{"word":"stereotypical","structure":"stereotype + -ical (relating to)","meaning":"matching a fixed image","meaningCN":"刻板化的；类型化的"},{"word":"stereotyped","structure":"stereotype + -ed (past participle)","meaning":"already fixed into a form","meaningCN":"固定化的"},{"word":"stereotyping","structure":"stereotype + -ing (gerund)","meaning":"the act of applying fixed images","meaningCN":"刻板化行为"}],"latinEntries":[{"word":"stereos","structure":"stereos, -on (Greek adjective)","meaning":"solid, firm","meaningCN":"坚固的；结实的"},{"word":"typos","structure":"typos, typou (m., Greek noun)","meaning":"a blow, an impression, a mark","meaningCN":"敲击；压印；印记"},{"word":"typus","structure":"typus, typi (m., Latin loan from Greek)","meaning":"figure, image, type","meaningCN":"形象；图像；类型"}]}},{"word":"stereotypical","ipa_uk":"/ˌsteriəˈtɪpɪkəl/","ipa_us":"/ˌsteriəˈtɪpɪkəl/","definition_zh":"刻板化的；类型化的；符合固定印象而缺乏个性的","definition_en":"matching a fixed and oversimplified image of a group or type, rather than showing individual detail","core_image":"影片里的乡村教师总戴眼镜、骑旧自行车、在黑板前叹气，这个反复出现的固定形象让人物失去自己的脸","scene":"The film's stereotypical village teacher wears glasses and sighs at the blackboard.","sceneCN":"此处指「符合固定印象、缺乏个体特征的类型化形象」（第 1 个义项：与刻板图像相符的）；句意为影片中那位类型化的乡村教师戴眼镜、在黑板前叹气。可辨识物件：圆框眼镜、旧自行车、黑板、叹息的侧影。","pos":[{"tag":"adj.","zh":"刻板化的；类型化的"},{"tag":"adj.","zh":"符合固定印象的；缺乏个性的"}],"collocations":[{"phrase":"stereotypical image","zh":"刻板化的形象"},{"phrase":"stereotypical role","zh":"类型化角色"},{"phrase":"stereotypical view","zh":"刻板看法"},{"phrase":"stereotypical behaviour","zh":"刻板化的行为"},{"phrase":"stereotypical portrayal","zh":"类型化描绘"},{"phrase":"highly stereotypical","zh":"高度类型化的"}],"forms":[{"label":"原级","form":"stereotypical"},{"label":"比较级","form":"more stereotypical"},{"label":"最高级","form":"most stereotypical"},{"label":"副词","form":"stereotypically"},{"label":"名词（刻板印象）","form":"stereotype"},{"label":"分词形容词（已固定化的）","form":"stereotyped"}],"derivatives":[{"word":"stereotype","pos":"n./v.","zh":"刻板印象；套用固定印象"},{"word":"stereotypically","pos":"adv.","zh":"以刻板方式"},{"word":"stereotyped","pos":"adj.","zh":"固定化的"},{"word":"stereotypic","pos":"adj.","zh":"刻板类型的"},{"word":"stereotyping","pos":"n.","zh":"刻板化过程"}],"senses":[{"no":"01","title":"Matching a fixed image","titleCN":"符合固定图像","definition":"matching an oversimplified and fixed image of a group or type rather than showing individual detail","definitionCN":"符合对某一群体或类型的过度简化且固定的图像，而非展现个体细节","example":"The film's stereotypical village teacher wears glasses and sighs at the blackboard.","exampleCN":"影片中那位类型化的乡村教师戴眼镜、在黑板前叹气。","why":"Stereotypical is the adjective of stereotype, whose base sense is a solid printing plate, so the adjective means 'printed from the same fixed plate'.","whyCN":"stereotypical 是 stereotype 的形容词，后者本义是坚固印版，因此这个形容词意为「从同一块固定印版印出来的」。"},{"no":"02","title":"Predictable and lacking individuality","titleCN":"可预测而缺乏个性","definition":"so familiar in form that the person or thing could be replaced by any other of the same kind","definitionCN":"形式过于熟悉，以致人事物可以被同类任何一个替代","example":"The novel's hero is a stereotypical young lawyer with a kind heart and no debts.","exampleCN":"这部小说的主人公是一个心地善良、毫无债务的典型年轻律师。","why":"When a pattern repeats without variation, it loses individuality, which is the everyday reading of the adjective.","whyCN":"当模式不加变化地重复，就失去个性，这是这个形容词的日常读法。"},{"no":"03","title":"Of a role in media","titleCN":"媒体中的类型化角色","definition":"describing a character in film, television or advertising who stands for a group rather than a person","definitionCN":"描述电影、电视或广告中代表某个群体而非某个人的角色","example":"The advertisement relied on a stereotypical housewife who loved every cleaning product.","exampleCN":"这则广告依赖一个热爱所有清洁用品的类型化主妇。","why":"Media repeats images to be quickly understood, so it is a natural home for the adjective.","whyCN":"媒体为求快速理解而重复图像，因此这个词在媒体语境中最自然。"},{"no":"04","title":"Of behaviour presumed by group","titleCN":"按群体预设的行为","definition":"describing behaviour that observers expect from a group member simply because of the group","definitionCN":"描述观察者仅因群体归属就期待某成员做出的行为","example":"The interviewer's stereotypical questions assumed she would not want the night shift.","exampleCN":"面试官的刻板提问假定她不会想要夜班。","why":"Expectation is the mental side of the plate: it prints the same question before meeting the person.","whyCN":"期待是印版的心理面：在见到本人之前就印出同样的问题。"},{"no":"05","title":"Of a formulaic plot or style","titleCN":"公式化的情节或风格","definition":"describing a story, design or speech that follows a repeated formula","definitionCN":"描述遵循重复套式的故事、设计或演讲","example":"The ending was stereotypical: a train, a letter and a sudden rainstorm.","exampleCN":"结局是公式化的：火车、信件与一场骤雨。","why":"The printing sense survives here as repetition of form rather than of people.","whyCN":"印刷义在这里以形式重复而非人物重复的方式留存。"},{"no":"06","title":"Of a typical setting","titleCN":"类型化的场景","definition":"describing a place shown with its most familiar markers rather than with specific detail","definitionCN":"描述一个只呈现最熟悉标志、缺乏具体细节的地点","example":"The postcard used a stereotypical harbour with three fishing boats and one lighthouse.","exampleCN":"这张明信片用了类型化港口：三条渔船加一座灯塔。","why":"Places as well as people can be printed from a fixed plate, which is why the adjective also describes settings.","whyCN":"地点与人一样能从固定印版印出，因此这个形容词也描述场景。"},{"no":"07","title":"Of a knee-jerk response","titleCN":"刻板反应","definition":"describing a reaction produced by habit or expectation rather than by the actual situation","definitionCN":"描述由习惯或期待而非实际情况产生的反应","example":"The committee gave a stereotypical answer before reading the proposal.","exampleCN":"委员会还没读提案就给出了刻板答复。","why":"Habit repeats without checking, and the adjective extends from images to responses.","whyCN":"习惯不经核对就重复，这个形容词便从图像延伸到反应。"},{"no":"08","title":"Of a group label","titleCN":"群体标签化的","definition":"describing a label that compresses a whole group into a few traits","definitionCN":"描述把一个整群体压缩成少数特征标签的做法","example":"The headline used a stereotypical label for the whole district.","exampleCN":"这则标题给整个地区贴了一个标签化的名称。","why":"The most abstract reading is the label itself, where the plate has become a word.","whyCN":"最抽象的读法是标签本身，此时印版已经变成了一个词。"}],"etymology":{"intro":{"en":"Stereotypical is stereotype plus the adjectival ending -ical, from Greek -ikos through Latin -icus. The base noun began in printing and later named a fixed social image. Dates are approximate.","cn":"stereotypical 由 stereotype 加形容词词尾 -ical 构成，后者经拉丁 -icus 来自希腊 -ikos。基础名词始于印刷业，后指固定的社会图像。年代均为约数。"},"items":[{"era":"GREEK STEREOS","en":"Stereos meant 'solid, firm', the first element of the printing compound.","cn":"stereos 意为「坚固的、结实的」，是印刷复合词的第一个成分。"},{"era":"GREEK TYPOS","en":"Typos meant 'a blow, an impression', from typtein 'to strike'; it named the printed mark.","cn":"typos 意为「敲击、压印」，来自 typtein「打」，指印出的痕迹。"},{"era":"PRINTING PLATE","en":"The noun stereotype named a solid plate cast from type, used to print the same page again and again.","cn":"名词 stereotype 指用活字浇铸的坚固印版，可反复印出同一版面。"},{"era":"SOCIAL IMAGE","en":"In the twentieth century the noun was extended to a fixed image of a group, and the adjective followed.","cn":"到二十世纪，名词被扩展到指对群体的固定图像，形容词也随之出现。"},{"era":"ADJECTIVAL ENDING","en":"The ending -ical, from Greek -ikos through Latin -icus, turns the noun into an adjective of relation.","cn":"词尾 -ical 经拉丁 -icus 来自希腊 -ikos，把名词变成表示关系的形容词。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (first date): the earliest English use of stereotypical is not precisely dated, and the deeper origin of typtein is unsettled.","cn":"来源不确定（首见年代）：stereotypical 的最早英语用例缺乏精确年代，typtein 的更深来源亦无定论。"}]},"similar":{"note":{"en":"Group one holds words built on the same plate image; group two holds adjectives for things that are too familiar or too general.","cn":"第一组是同出「印版」意象的词；第二组是表示过于熟悉或过于笼统的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stereotype","ipa":"/ˈsteriətaɪp/","tag":"the noun or verb","definition":"The fixed image itself, or the act of applying it; stereotypical describes what matches it.","definitionCN":"指固定图像本身或套用行为；stereotypical 描述符合它的事物。"},{"word":"stereotyped","ipa":"/ˈsteriətaɪpt/","tag":"already fixed","definition":"A participle meaning 'already pressed into a form'; it stresses the result, not the match.","definitionCN":"分词形容词，意为「已被压成固定形态」，强调结果而非相符。"},{"word":"stereotypic","ipa":"/ˌsteriəˈtɪpɪk/","tag":"technical variant","definition":"A psychology term for behaviour that repeats a fixed pattern, often without social content.","definitionCN":"心理学术语，指重复固定模式的行为，常不含社会内容。"},{"word":"stereotypically","ipa":"/ˌsteriəˈtɪpɪkli/","tag":"the adverb","definition":"Means in the manner of a fixed image; it modifies the action rather than the thing.","definitionCN":"意为以固定图像的方式，修饰行为而非事物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"formulaic","ipa":"/ˌfɔːmjʊˈleɪɪk/","tag":"built from a formula","definition":"Describes language or plots assembled from set pieces; it stresses repetition of form, not group prejudice.","definitionCN":"描述由固定片段拼成的语言或情节，强调形式重复，而非群体偏见。"},{"word":"predictable","ipa":"/prɪˈdɪktəbl/","tag":"easy to foresee","definition":"Means able to be foretold; a predictable ending may be good craft, whereas stereotypical implies a worn image.","definitionCN":"意为可被预见；可预测的结局可能是好手艺，而 stereotypical 含陈旧图像之意。"},{"word":"conventional","ipa":"/kənˈvenʃənəl/","tag":"following custom","definition":"Means according to accepted custom; it can be neutral or approving, unlike stereotypical.","definitionCN":"意为符合公认习俗，可中性甚至褒义，与 stereotypical 不同。"},{"word":"clichéd","ipa":"/kliːˈʃeɪd/","tag":"worn by overuse","definition":"Describes phrases or scenes worn out by overuse; it is close but usually about expression, not group images.","definitionCN":"描述因过度使用而失新的语句或场景，接近但通常指表达，而非群体图像。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Stereotype plus -ical: the adjective says something is printed from the same fixed plate.","cn":"stereotype 加 -ical：这个形容词表示某物是从同一块固定印版印出的。"},{"en":"Fixed phrases mark the use: stereotypical image, stereotypical role, stereotypical portrayal.","cn":"固定搭配标出用法：刻板化形象、类型化角色、类型化描绘。"},{"en":"The family runs stereotype, stereotyped, stereotyping, stereotypic and stereotypically.","cn":"同族词包括 stereotype、stereotyped、stereotyping、stereotypic 与 stereotypically。"},{"en":"The adjective applies to people, roles, plots, settings and labels, all of which can be printed the same way.","cn":"这个形容词可用于人、角色、情节、场景与标签，它们都能被同样地印出。"},{"en":"It differs from conventional: a conventional ending may be skilled, a stereotypical one is merely fixed.","cn":"它与 conventional 不同：惯例式结局可能有手艺，刻板化结局只是固定。"}],"abstract":[{"en":"Picture a postcard of a harbour with exactly three boats and one lighthouse.","cn":"想象一张港口明信片，不多不少三条船、一座灯塔。"},{"en":"Picture a mask that fits every face because it has no features to speak of.","cn":"想象一张能套上每张脸的面具，因为它几乎没有五官。"},{"en":"Picture a question asked before the applicant has even sat down.","cn":"想象申请者还没坐下，问题就已经问出。"}]},"examples":[{"en":"The review called the portrayal stereotypical and asked for a more specific story.","cn":"评论称这一描绘过于类型化，要求讲一个更具体的故事。"},{"en":"A stereotypical answer came before anyone had read the figures.","cn":"还没人读数字，刻板的答复就已经给出。"},{"en":"The design was attractive but stereotypical, with the usual fishing boats and lighthouse.","cn":"这个设计好看却类型化，仍是常见的渔船与灯塔。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「stereotype（刻板印象）+ ical（的）」——像同一块印版印出来的 → 刻板化的","word":"stereotypical"},"root":"stereotypical 由 stereotype 加 -ical 构成，-ical 经拉丁 -icus 来自希腊 -ikos；stereotype 由希腊 stereos「坚固」与 typos「压印」构成，先指印刷铅版，后指固定社会图像。最早书证年代不确定。","sensesIntro":{"en":"Eight senses apply one fixed plate to different surfaces: a group image, a predictable person, a media role, expected behaviour, a formulaic plot, a typical setting, a knee-jerk response and a group label.","cn":"八个义项把同一块固定印版压到不同表面：群体图像、可预测的人、媒体角色、被预设的行为、公式化情节、典型场景、刻板反应与群体标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mask with almost no features that can nevertheless be fitted to every face.","cn":"核心意象：一张几乎没有五官、却能套上每张脸的面具。"},"chain":["SOLID PLATE","FIXED IMAGE","REPEATED TYPE","NO INDIVIDUALITY","EXPECTED RESPONSE","GROUP LABEL"],"branches":[{"senses":"01","en":"FIXED IMAGE: the adjective begins with a match to a pre-printed picture.","cn":"固定图像：这个形容词从「与预先印好的图像相符」开始。"},{"senses":"02","en":"NO INDIVIDUALITY: repetition removes the details that would make a person specific.","cn":"缺乏个性：重复抹去了使一个人具体起来的细节。"},{"senses":"03 · 06","en":"ROLE AND SETTING: media characters and familiar places are printed from the same plate.","cn":"角色与场景：媒体人物与熟悉地点都从同一块印版印出。"},{"senses":"04 · 07","en":"EXPECTATION: the plate works in the mind, printing questions and reactions before evidence.","cn":"期待：印版在头脑中运作，在证据之前就印出问题与反应。"},{"senses":"05 · 08","en":"FORMULA AND LABEL: a worn plot and a group label are repetition in story and in name.","cn":"套式与标签：陈旧情节与群体标签，是故事与名称层面的重复。"}]},"affixes":{"intro":{"en":"The adjective adds a relational ending to a noun that began as a printing term, and its derived family keeps both the print and the social readings.","cn":"这个形容词给一个源于印刷术语的名词加上关系词尾，其派生词族同时保留印刷义与社会义。"},"latinIntro":{"en":"Greek stereos and typos supply the noun; Latin -icus and English -ical supply the adjective ending; English added the adverb and related nouns.","cn":"希腊 stereos 与 typos 提供名词；拉丁 -icus 与英语 -ical 提供形容词词尾；英语又造出副词与相关名词。"},"items":[{"word":"stereo-","structure":"stereos (Greek adjective, 'solid')","meaning":"solid, firm","meaningCN":"坚固的；结实的","example":"The first element names the plate.","exampleCN":"第一个成分指印版。"},{"word":"-type","structure":"typos (Greek noun, 'impression')","meaning":"impression; printed mark","meaningCN":"压印；印记","example":"The second element names the print.","exampleCN":"第二个成分指印痕。"},{"word":"stereotype","structure":"stereo- + -type","meaning":"a solid plate; a fixed image","meaningCN":"铅版；固定图像","example":"The noun carries both readings.","exampleCN":"这个名词兼有两义。"},{"word":"-ical","structure":"-ikos (Greek adjectival suffix, through Latin -icus)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending makes the adjective.","exampleCN":"这个词尾构成形容词。"},{"word":"stereotypical","structure":"stereotype + -ical","meaning":"matching a fixed image","meaningCN":"刻板化的","example":"The portrayal was stereotypical.","exampleCN":"这一描绘是类型化的。"},{"word":"stereotypically","structure":"stereotypical + -ly (adverbial)","meaning":"in a fixed-image way","meaningCN":"以刻板方式","example":"He acted stereotypically.","exampleCN":"他的行为很刻板。"},{"word":"stereotyped","structure":"stereotype + -ed (past participle)","meaning":"already fixed","meaningCN":"已固定化的","example":"The answer sounded stereotyped.","exampleCN":"这个答复听起来很刻板。"},{"word":"stereotypic","structure":"stereotype + -ic (technical)","meaning":"of a fixed pattern","meaningCN":"刻板类型的","example":"The motion was stereotypic.","exampleCN":"这个动作是刻板类型的。"},{"word":"stereotyping","structure":"stereotype + -ing (gerund)","meaning":"the act of fixing images","meaningCN":"刻板化行为","example":"Stereotyping harms hiring.","exampleCN":"刻板化损害招聘。"}],"derivatives":[{"word":"stereotypically","structure":"stereotypical + -ly (adverbial)","meaning":"in a fixed-image way","meaningCN":"以刻板方式"},{"word":"stereotyped","structure":"stereotype + -ed (past participle)","meaning":"already fixed","meaningCN":"已固定化的"},{"word":"stereotyping","structure":"stereotype + -ing (gerund)","meaning":"the act of fixing images","meaningCN":"刻板化行为"}],"latinEntries":[{"word":"stereos","structure":"stereos, -on (Greek adjective)","meaning":"solid, firm","meaningCN":"坚固的；结实的"},{"word":"typos","structure":"typos, typou (m., Greek noun)","meaning":"an impression, a mark","meaningCN":"压印；印记"},{"word":"typicus","structure":"typicus, -a, -um (adjective, Late Latin)","meaning":"of a type, typical","meaningCN":"类型的；典型的"}]}},{"word":"marginalization","ipa_uk":"/ˌmɑːdʒɪnəlaɪˈzeɪʃən/","ipa_us":"/ˌmɑːrdʒɪnələˈzeɪʃən/","definition_zh":"边缘化；把某些人或群体推到社会、经济与决策的边缘的过程","definition_en":"the process by which a group or issue is pushed to the edge of society, the economy or decision-making","core_image":"旧城改造把摊贩赶出主街，听证会不给他们发言时间，政策文件里也找不到他们的名字，一群人被慢慢推到页边","scene":"The redevelopment plan led to the marginalization of street vendors from the main avenue.","sceneCN":"此处指「把某群体逐步推到城市与决策边缘的过程」（第 1 个义项：社会边缘化的整体过程）；句意为这项旧城改造计划导致街头摊贩被排挤出主街。可辨识物件：主街围挡、空出的摊位、听证会空椅、文件页边空白。","pos":[{"tag":"n.","zh":"边缘化（社会、经济或政治过程，常作不可数）"},{"tag":"n.","zh":"被边缘化的状态（可数，指具体案例）"}],"collocations":[{"phrase":"social marginalization","zh":"社会边缘化"},{"phrase":"economic marginalization","zh":"经济边缘化"},{"phrase":"marginalization of minority groups","zh":"少数群体的边缘化"},{"phrase":"marginalization from decision-making","zh":"被排除在决策之外"},{"phrase":"risk of marginalization","zh":"边缘化风险"},{"phrase":"fight marginalization","zh":"对抗边缘化"}],"forms":[{"label":"不可数（整体过程）","form":"marginalization"},{"label":"可数复数（具体案例）","form":"marginalizations"},{"label":"动词（使边缘化）","form":"marginalize"},{"label":"过去分词/形容词（被边缘化的）","form":"marginalized"},{"label":"形容词（边缘的）","form":"marginal"},{"label":"名词（边缘）","form":"margin"}],"derivatives":[{"word":"marginalize","pos":"v.","zh":"使边缘化；把……排到边缘"},{"word":"marginalized","pos":"adj.","zh":"被边缘化的"},{"word":"marginal","pos":"adj.","zh":"边缘的；微小的"},{"word":"marginally","pos":"adv.","zh":"略微；在边缘上"},{"word":"margin","pos":"n.","zh":"边缘；页边；利润空间"},{"word":"marginality","pos":"n.","zh":"边缘状态"}],"senses":[{"no":"01","title":"Being pushed to society's edge","titleCN":"被推到社会边缘","definition":"the process by which a group is excluded from the ordinary life, rights and recognition of a society","definitionCN":"某一群体被排除在社会的普通生活、权利与承认之外的过程","example":"The redevelopment plan led to the marginalization of street vendors from the main avenue.","exampleCN":"这项旧城改造计划导致街头摊贩被排挤出主街。","why":"Marginalization comes from marginal, from Latin margo 'edge', so the process is literally being pushed to the edge of the page.","whyCN":"marginalization 来自 marginal，后者源于拉丁 margo「边缘」，因此这个过程字面上就是被推到页边。"},{"no":"02","title":"Economic exclusion","titleCN":"经济排斥","definition":"the process by which a group is kept out of secure work, credit and markets","definitionCN":"某一群体被挡在稳定工作、信贷与市场之外的过程","example":"The closure of the small workshops accelerated the economic marginalization of the district.","exampleCN":"小作坊关闭加速了这一地区的经济边缘化。","why":"Economies place some workers at the edge of the labour market, and the word names that placement as a process.","whyCN":"经济把一些劳动者放在劳动力市场的边缘，这个词把这个安置过程命名出来。"},{"no":"03","title":"Political silencing","titleCN":"政治失声","definition":"the process by which a group loses a voice in decisions that affect it","definitionCN":"某一群体在影响自身的决策中失去声音的过程","example":"Marginalization from the budget debate meant the tenants never heard the plan before it passed.","exampleCN":"被排除在预算辩论之外，意味着租户在计划通过前从未听说它。","why":"A voice at the table is a central good, so being kept from it is one of the clearest forms of the process.","whyCN":"在决策桌上有发言权是一项核心利益，被挡在桌外因而是这一过程最清楚的形式之一。"},{"no":"04","title":"Spatial exclusion","titleCN":"空间排斥","definition":"the process by which a group is pushed away from central places, transport or public space","definitionCN":"某一群体被推离中心地点、交通或公共空间的过程","example":"The new barriers completed the spatial marginalization of the market traders.","exampleCN":"新设的围栏完成了对市场商贩的空间边缘化。","why":"Cities express exclusion through distance, and the word captures that physical pushing away.","whyCN":"城市用距离表达排斥，这个词正好捕捉那种物理上的推离。"},{"no":"05","title":"In the labour market","titleCN":"劳动力市场中的边缘化","definition":"the process by which workers are kept in insecure, low-paid or informal jobs","definitionCN":"劳动者被限制在不稳定、低薪或非正式工作中的过程","example":"Migrant workers faced marginalization into short contracts with no benefits.","exampleCN":"外来工人面临被边缘化到无福利的短期合同之中。","why":"Work is where the edge becomes a contract, so the process has a precise labour-market reading.","whyCN":"工作是把「边缘」变成合同的地方，因此这个过程有精确的劳动力市场读法。"},{"no":"06","title":"In education","titleCN":"教育中的边缘化","definition":"the process by which pupils are quietly routed away from the best courses and support","definitionCN":"学生被悄然分流到较差课程与支持之外的过程","example":"Language barriers produced marginalization in the very schools that should have helped.","exampleCN":"语言障碍在本应提供帮助的学校里造成了边缘化。","why":"Schools sort as well as teach, and the word names the sorting that leaves some pupils at the edge.","whyCN":"学校既教学也分类，这个词命名那种把部分学生留在边缘的分类。"},{"no":"07","title":"In discourse","titleCN":"话语中的边缘化","definition":"the process by which a group's experience is left out of the stories, terms and images a society uses","definitionCN":"某一群体的经验被排除在社会所用故事、术语与图像之外的过程","example":"The archive showed the discursive marginalization of rural women in early radio.","exampleCN":"档案显示了早期广播中农村女性在话语上的边缘化。","why":"Being unnamed is a form of being placed at the edge, so the word extends from institutions to language.","whyCN":"不被命名也是被置于边缘的一种方式，因此这个词从制度延伸到语言。"},{"no":"08","title":"In the policy process","titleCN":"政策过程中的边缘化","definition":"the process by which an issue or group is kept off the agenda until decisions are already made","definitionCN":"某一议题或群体被排除在议程之外、直到决定已经作成的过程","example":"Consultation came late, and the result was the marginalization of the very people the policy targeted.","exampleCN":"咨询来得太晚，结果正是政策对象本身被边缘化。","why":"Agendas decide what can be discussed, and the final sense names exclusion from that list.","whyCN":"议程决定什么能被讨论，最后一个义项命名被排除在这份清单之外。"}],"etymology":{"intro":{"en":"Marginalization is formed from marginal plus -ize plus -ation. Marginal goes back to Latin margo, marginis 'edge, border'. The word is a modern social-science formation. Dates are approximate.","cn":"marginalization 由 marginal 加 -ize 再加 -ation 构成。marginal 可追溯到拉丁 margo、marginis「边缘、边界」。这个词是现代社会科学的合成词。年代均为约数。"},"items":[{"era":"LATIN MARGO","en":"Margo, marginis meant 'edge, border, brink'. Its deeper origin is not established; proposed earlier forms are reconstructions.","cn":"margo、marginis 意为「边缘、边界、崖边」。其更深来源未得到证明，所提出的更早形态均属重构。"},{"era":"ENGLISH MARGIN","en":"English margin named the blank edge of a page and later the edge of anything, including profit and error.","cn":"英语 margin 先指书页的空白边缘，后指任何事物的边缘，包括利润空间与误差范围。"},{"era":"MARGINAL","en":"The adjective marginal meant 'on the edge' and then 'of little importance', since what is at the edge counts for less.","cn":"形容词 marginal 意为「在边缘的」，后指「不重要的」，因为边缘之物分量较小。"},{"era":"VERB AND NOUN","en":"English added -ize to make marginalize 'to push to the edge', and -ation to name the process.","cn":"英语加 -ize 构成 marginalize「推到边缘」，再加 -ation 命名这一过程。"},{"era":"SOCIAL SCIENCE","en":"In the twentieth century the noun became standard in sociology and policy writing for exclusion from the centre of power and resources.","cn":"到二十世纪，这个名词在社会学与政策写作中成为指被排除在权力与资源中心之外的标准用语。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin and first date): the pre-Latin origin of margo is unsettled, and the earliest English use of marginalization is not precisely dated.","cn":"来源不确定（更深词源与首见年代）：margo 在拉丁语之前的来源无定论，marginalization 的最早英语用例也缺乏精确年代。"}]},"similar":{"note":{"en":"Group one holds words built on the same edge root; group two holds terms for exclusion with a different mechanism or tone.","cn":"第一组是同出「边缘」词根的词；第二组是机制或语气不同的排斥类术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"marginalize","ipa":"/ˈmɑːdʒɪnəlaɪz/","tag":"the verb","definition":"To push someone or something to the edge; marginalization is the process it performs.","definitionCN":"把某人或某物推到边缘；marginalization 是这一动作的过程名词。"},{"word":"marginalized","ipa":"/ˈmɑːdʒɪnəlaɪzd/","tag":"the participle","definition":"Describes a group already pushed to the edge; it stresses the resulting state.","definitionCN":"描述已被推到边缘的群体，强调结果状态。"},{"word":"marginal","ipa":"/ˈmɑːdʒɪnəl/","tag":"the adjective","definition":"Means at the edge or of small importance; it can describe a small effect, not only a social position.","definitionCN":"意为在边缘或不重要，可描述微小效果，不限于社会位置。"},{"word":"margin","ipa":"/ˈmɑːdʒɪn/","tag":"the noun","definition":"The blank edge of a page, or the space between cost and price; it is the literal edge.","definitionCN":"指书页空白边缘，或成本与价格之间的空间，是字面的边缘。"}]},{"heading":"NEAR MEANING","entries":[{"word":"exclusion","ipa":"/ɪkˈskluːʒən/","tag":"kept out","definition":"The state or act of keeping someone out of a group or service; it is broader and more direct than marginalization.","definitionCN":"指被挡在群体或服务之外的状态或行为，比边缘化更宽、更直接。"},{"word":"alienation","ipa":"/ˌeɪliəˈneɪʃən/","tag":"feeling estranged","definition":"A sense of estrangement from society or from one's own work; it stresses feeling more than placement.","definitionCN":"指与社会或自身工作的疏离感，强调感受多于位置。"},{"word":"displacement","ipa":"/dɪsˈpleɪsmənt/","tag":"moved away","definition":"The act of forcing people or things out of their place; marginalization keeps them nearby but powerless.","definitionCN":"指把人或物逐出原地的行为；边缘化则让人留在附近却无权。"},{"word":"sidelining","ipa":"/ˈsaɪdlaɪnɪŋ/","tag":"set aside","definition":"An informal term for removing someone from the main activity; it is close but less structural.","definitionCN":"指把某人从主要活动中挪开的非正式说法，接近但结构性较弱。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real related words, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin margo 'edge' plus -al, -ize and -ation: the process of being placed at the edge.","cn":"拉丁 margo「边缘」加 -al、-ize 与 -ation：被放到边缘的过程。"},{"en":"Fixed phrases mark the field: social marginalization, economic marginalization, marginalization from decision-making.","cn":"固定搭配标出领域：社会边缘化、经济边缘化、被排除在决策之外。"},{"en":"The family runs marginalize, marginalized, marginal, marginally, margin and marginality.","cn":"同族词包括 marginalize、marginalized、marginal、marginally、margin 与 marginality。"},{"en":"The literal picture is a page: the text stays in the centre and some people are written into the blank edge.","cn":"字面图像是一页纸：正文留在中央，有些人被写进空白页边。"},{"en":"The word differs from exclusion: the excluded are kept out, the marginalized are kept near but unheard.","cn":"这个词与 exclusion 不同：被排斥者被挡在外，被边缘化者留在附近却无人听见。"}],"abstract":[{"en":"Picture a meeting room where one chair is placed outside the door.","cn":"想象一间会议室，有一把椅子被放在门外。"},{"en":"Picture a page whose centre is crowded and whose margin holds the names nobody reads.","cn":"想象一页纸，中央拥挤，页边写着没人读的名字。"},{"en":"Picture a market pushed off the main street but still visible from it.","cn":"想象一个市场被推离主街，却仍从主街看得见。"}]},"examples":[{"en":"The report documented the marginalization of riverside households after the new road opened.","cn":"这份报告记录了新路开通后江边住户被边缘化的过程。"},{"en":"Economic marginalization followed the loss of the small workshops.","cn":"小作坊消失之后，经济边缘化随之而来。"},{"en":"Consultation came so late that it completed the marginalization it was meant to prevent.","cn":"咨询来得太晚，反而完成了它本应防止的边缘化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「margin（边缘）+ al + ization（过程）」——把人一点点推到页边 → 边缘化","word":"marginalization"},"root":"marginalization 由 marginal 加 -ize 再加 -ation 构成；marginal 来自拉丁 margo、marginis「边缘、边界」。margo 更深来源不确定，该社会学术语的最早英语书证年代亦不确定。","sensesIntro":{"en":"Eight senses follow one push toward the edge: social exclusion, economic exclusion, lost voice, spatial pushing, insecure work, school sorting, missing names and a closed agenda.","cn":"八个义项沿着同一次「推向边缘」展开：社会排斥、经济排斥、失去声音、空间推离、不稳定工作、学校分流、名字缺席与封闭议程。"},"semanticMap":{"core":{"en":"CORE IMAGE: a page whose centre is full and whose margin holds the names nobody reads.","cn":"核心意象：一页纸，中央写满，页边写着没人读的名字。"},"chain":["EDGE","MARGIN OF A PAGE","PUSH TO THE EDGE","LOSE A VOICE","LOSE RESOURCES","STRUCTURAL PROCESS"],"branches":[{"senses":"01","en":"SOCIAL EDGE: the base process pushes a group out of ordinary life and recognition.","cn":"社会边缘：基础过程把一个群体推出普通生活与承认之外。"},{"senses":"02 · 05","en":"ECONOMIC EDGE: insecure work and lost markets place people at the edge of livelihood.","cn":"经济边缘：不稳定工作与失去市场，把人放到生计的边缘。"},{"senses":"03","en":"LOST VOICE: being kept from the table is the political form of the same push.","cn":"失去声音：被挡在决策桌外，是同一推力的政治形态。"},{"senses":"04","en":"SPACE: distance and barriers turn exclusion into a map.","cn":"空间：距离与围栏把排斥变成一张地图。"},{"senses":"06 · 07 · 08","en":"SORTING, NAMING AND AGENDA: schools, discourse and agendas each decide who stays at the edge.","cn":"分流、命名与议程：学校、话语与议程各自决定谁留在边缘。"}]},"affixes":{"intro":{"en":"The noun chains a Latin root for 'edge' to a verb ending and a process ending, all of which remain visible in the family.","cn":"这个名词把表示「边缘」的拉丁词根依次接上动词词尾与过程词尾，这些成分在词族中仍清楚可见。"},"latinIntro":{"en":"Latin margo supplies margin and marginal; English added -ize and -ation, and also marginality and marginally.","cn":"拉丁 margo 提供 margin 与 marginal；英语又加上 -ize 与 -ation，并造出 marginality 与 marginally。"},"items":[{"word":"margin","structure":"margo, marginis (Latin noun, 'edge, border')","meaning":"edge; border","meaningCN":"边缘；边界","example":"The noun is the literal edge.","exampleCN":"这个名词就是字面的边缘。"},{"word":"-al","structure":"-alis (Latin adjectival suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix forms marginal.","exampleCN":"这个词尾构成 marginal。"},{"word":"marginal","structure":"margin + -al","meaning":"on the edge; of little weight","meaningCN":"边缘的；不重要的","example":"The effect was marginal.","exampleCN":"影响是微小的。"},{"word":"-ize","structure":"-izein (Greek verb ending, 'to make')","meaning":"to make or put","meaningCN":"使……；把……放到","example":"The ending forms marginalize.","exampleCN":"这个词尾构成 marginalize。"},{"word":"marginalize","structure":"marginal + -ize","meaning":"to push to the edge","meaningCN":"使边缘化","example":"The plan marginalized the vendors.","exampleCN":"这项计划使摊贩边缘化。"},{"word":"-ation","structure":"-atio (Latin noun ending, process)","meaning":"process or result","meaningCN":"过程或结果","example":"The ending forms the noun.","exampleCN":"这个词尾构成名词。"},{"word":"marginalization","structure":"marginalize + -ation","meaning":"the process of being pushed to the edge","meaningCN":"边缘化过程","example":"The process was documented.","exampleCN":"这一过程被记录。"},{"word":"marginalized","structure":"marginalize + -ed (past participle)","meaning":"already pushed to the edge","meaningCN":"被边缘化的","example":"The marginalized groups organized.","exampleCN":"被边缘化的群体组织起来。"},{"word":"marginally","structure":"marginal + -ly (adverbial)","meaning":"slightly; at the edge","meaningCN":"略微；在边缘上","example":"Costs rose marginally.","exampleCN":"成本略微上升。"}],"derivatives":[{"word":"marginalize","structure":"marginal + -ize (to make)","meaning":"to push to the edge","meaningCN":"使边缘化"},{"word":"marginalized","structure":"marginalize + -ed (past participle)","meaning":"already pushed to the edge","meaningCN":"被边缘化的"},{"word":"marginality","structure":"marginal + -ity (state)","meaning":"the state of being at the edge","meaningCN":"边缘状态"}],"latinEntries":[{"word":"margo","structure":"margo, marginis (m., third declension)","meaning":"edge, border, brink","meaningCN":"边缘；边界；崖边"},{"word":"marginalis","structure":"marginalis, -e (adjective, Late Latin)","meaning":"of the edge","meaningCN":"边缘的"},{"word":"marginare","structure":"marginare (verb, Late Latin)","meaning":"to furnish with a margin","meaningCN":"加页边；留边"}]}}]);
